window.LEERHUIS_DOCUMENT_INDEX = {"sources":[{"title":"Opleidingsinformatie Verzorgende IG · Boerhaavehof (2026)","kind":"guide","course":"vig","location":"boerhaavehof","year":"2026","id":"bron-1","count":87},{"title":"Opleidingsinformatie Verpleegkundige · Boerhaavehof (2026)","kind":"guide","course":"vp","location":"boerhaavehof","year":"2026","id":"bron-2","count":59},{"title":"Opleidingsinformatie Verzorgende IG · Villa Verde (2026)","kind":"guide","course":"vig","location":"villaverde","year":"2026","id":"bron-3","count":66},{"title":"Opleidingsinformatie Verpleegkundige · Villa Verde (2026)","kind":"guide","course":"vp","location":"villaverde","year":"2026","id":"bron-4","count":66},{"title":"Examenreglement studenten (2026–2027)","kind":"reglement","year":"2026–2027","id":"bron-5","count":134},{"title":"Handboek Examinering (2026–2027), studentenrelevante delen","kind":"handboek","year":"2026–2027","id":"bron-6","count":140},{"title":"EPP Prove2Move · instructie student (2025)","kind":"epp","year":"2025","id":"bron-7","count":49},{"title":"EPP · account en inloggen","kind":"epp","year":"datum onbekend","id":"bron-8","count":1},{"title":"Routeplanner rekenen (2025–2026, verifiëren)","kind":"rekenen","year":"2025–2026","id":"bron-9","count":11},{"title":"Aftekenboek verpleegtechnische handelingen · niveau 3","kind":"skills","course":"vig","year":"datum onbekend","id":"bron-10","count":14},{"title":"Aftekenboek verpleegtechnische handelingen · niveau 4","kind":"skills","course":"vp","year":"datum onbekend","id":"bron-11","count":24},{"title":"EPP Prove2Move · algemene handleiding (2022)","kind":"epp","year":"2022","id":"bron-12","count":81},{"title":"Reflecteren met de ABCD-methode","kind":"reflectie","year":"datum onbekend","id":"bron-13","count":8},{"title":"Reflecteren met STARRT","kind":"reflectie","year":"datum onbekend","id":"bron-14","count":7},{"title":"Reflectiespiraal van Korthagen","kind":"reflectie","year":"datum onbekend","id":"bron-15","count":4},{"title":"Afspraken medisch rekenen · studentenversie","kind":"medisch","year":"datum in document","id":"bron-16","count":19},{"title":"BPV-handleidingen en verwijzingen","kind":"bpv","year":"datum onbekend","id":"bron-17","count":0},{"title":"De BPV-wijzer · instructie","kind":"bpv","year":"datum onbekend","id":"bron-18","count":8},{"title":"SkillsLab · informatie en regels","kind":"skills","year":"datum onbekend","id":"bron-19","count":15},{"title":"Medisch rekenen · oefenvragen en uitlegvideo’s","kind":"medisch","year":"datum onbekend","id":"bron-20","count":7}],"passages":[{"id":"bron-1-1","sourceId":"bron-1","title":"Guide","text":"Je gaat beginnen met je opleiding tot verzorgende IG in Boerhaavehof. Ook namens Landstede heten we je van harte welkom!","page":4},{"id":"bron-1-2","sourceId":"bron-1","title":"Guide","text":"Deze gids is bedoeld om je op weg te helpen in je opleiding. Starten met een zorgopleiding kan in het begin best overweldigend zijn. Je coach en je medestudenten zijn er om je hierin te ondersteunen. En dit document kan je gebruiken als naslagwerk. Heel veel succes gewenst!","page":4},{"id":"bron-1-3","sourceId":"bron-1","title":"Start met de opleiding","text":"Je begint met een opleiding en dan komt er veel op je af. Je krijgt de tijd om hier rustig je weg in te vinden. Om je wat houvast te geven hierbij een checklist voor je eerste dagen/weken van je opleiding:","page":5},{"id":"bron-1-4","sourceId":"bron-1","title":"Voorbereiding eerste lesdag","text":"De laptop is cruciaal om aan je opdrachten te kunnen werken, mee te doen met het onderwijs en gebruik te maken van alle digitale systemen. Voorafgaand aan de start van je opleiding krijg je een brief met tips en informatie over de aanschaf van een laptop. o Check je inloggegevens. Je gaat werken met verschillende systemen en daarbij","page":5},{"id":"bron-1-5","sourceId":"bron-1","title":"Voorbereiding eerste lesdag","text":"moet je inloggen. De inloggegevens ontvang je voorafgaand aan je opleiding thuis. Kijk er vast naar of neem ze mee op je eerste lesdag. o Zorg dat je een digitale foto beschikbaar hebt voor in het schoolsysteem en op de","page":5},{"id":"bron-1-6","sourceId":"bron-1","title":"Eerste lesdag/week","text":"o Je sluit s ‘ochtends om 09.00 uur aan bij de groep. Je draait mee in de eerste les.","page":5},{"id":"bron-1-7","sourceId":"bron-1","title":"Eerste lesdag/week","text":"Je hoeft je hier op niet voor te bereiden o In het tweede blok staat een coach uur gepland. Hierin wordt tijd gereserveerd","page":5},{"id":"bron-1-8","sourceId":"bron-1","title":"waarin je door een van de docenten uitleg krijgt over:","text":"Inloggen in de digitale systemen (Eduarte, ETO, Connect) • Uploaden van een foto & aanvragen studentenpas (Eenmaal ingelogd mag","page":5},{"id":"bron-1-9","sourceId":"bron-1","title":"waarin je door een van de docenten uitleg krijgt over:","text":"je jouw foto uploaden via het studentendashboard op Connect en je studentpas aanvragen. Die krijg je dan volgende week binnen via je coach. • Boeken bestellen (Je gaat boeken bestellen via www.mbowebshop.nl","page":5},{"id":"bron-1-10","sourceId":"bron-1","title":"waarin je door een van de docenten uitleg krijgt over:","text":"De docent geeft aan welke boeken je kunt bestellen) • Je studiemaatje (Je wordt tijdens je opleiding gekoppeld aan een","page":5},{"id":"bron-1-11","sourceId":"bron-1","title":"waarin je door een van de docenten uitleg krijgt over:","text":"medestudent die als maatje fungeert. Gebruik je maatje om uitleg te vragen over de opleiding, de systemen etc.) • Invullen derdenmachtiging schoolgeld • Procedure ziekmelden","page":5},{"id":"bron-1-12","sourceId":"bron-1","title":"In het coach uur krijg je uitleg over:","text":"ILP (Individueel leerplan) • Evt. vrijstellingen • Werken met de digitale systemen (Eduarte, ETO, Connect, Teams) door je","page":6},{"id":"bron-1-13","sourceId":"bron-1","title":"Ziekmelden","text":"Mocht je niet aanwezig kunnen zijn bij de les(sen) door bv. ziekte, dan meld je dit eerst bij je teamleider. Daarna meld je je af voor de les via Eduarte. Het is netjes even kort toe te lichten via Teams of per mail.","page":9},{"id":"bron-1-14","sourceId":"bron-1","title":"Vakken","text":"Je volgt tijdens je opleiding verschillende vakken. Het gaat om ''generieke vakken'' en ''zorg vakken''.","page":12},{"id":"bron-1-15","sourceId":"bron-1","title":"Generieke vakken","text":"Generieke vakken zijn algemene vakken die iedere MBO student doorloopt. Het gaat hier om:","page":12},{"id":"bron-1-16","sourceId":"bron-1","title":"Generieke vakken","text":"In sommige gevallen krijgen studenten op basis van hun vooropleiding een vrijstelling. Dit moet je bespreken met je coach.","page":12},{"id":"bron-1-17","sourceId":"bron-1","title":"Generieke vakken","text":"Het is verstandig om in de eerste fase van de opleiding te werken aan de generieke vakken zodat dit niet ‘opstapelt’ aan het eind van de opleiding.","page":12},{"id":"bron-1-18","sourceId":"bron-1","title":"Generieke vakken","text":"Bij (mogelijke) problemen is extra hulp en begeleiding aan te vragen via het studentadviesbureau (SAB)","page":12},{"id":"bron-1-19","sourceId":"bron-1","title":"Zorgvakken","text":"Tijdens de opleiding krijg je een heel aantal vakken aangeboden die direct gerelateerd zijn aan de zorg. Voorbeelden hiervan zijn:","page":12},{"id":"bron-1-20","sourceId":"bron-1","title":"Zorgvakken","text":"Basiszorg (Wassen, aankleden, verplaatsingstechnieken etc.) • Begeleiden • Gezondheidsvoorlichting • Verpleegtechnische handelingen • Medisch rekenen • Schrijven van een zorgplan • Anatomie/fysiologie/pathologie (AFGP) • Branche vakken (AGZ, VVT, GGZ, GHZ) • Coördineren van zorg • Kwaliteitszorg","page":12},{"id":"bron-1-21","sourceId":"bron-1","title":"Opstarten van vakken","text":"Per periode bepalen de coaches samen met de studenten welke vakken er op het rooster komen. Er zijn ook vakken (LWP's) waar je in je eigen tijd, zelfstandig aan kan werken. Je coach zal dit met je bespreken.","page":13},{"id":"bron-1-22","sourceId":"bron-1","title":"Opstarten van vakken","text":"Wanneer je net bent gestart, haak je ergens in het studiejaar, aan het begin van een lesperiode in. Het rooster wat is afgesproken met de studenten die al langer in opleiding zijn is dan ook voor jou van toepassing.","page":13},{"id":"bron-1-23","sourceId":"bron-1","title":"Opstarten van vakken","text":"De vakken (LWP's) die jij gaat volgen zijn door je coach toegevoegd in het Individueel Leerplan (ILP) in het programma e-TO. De eerste LWP’ s waar je zelfstandig mee aan het werk kan worden door daar ook direct toegevoegd. Dit zijn de LWP's:","page":13},{"id":"bron-1-24","sourceId":"bron-1","title":"Opstarten van vakken","text":"Burgerschap: Van start tot examen • Mijn ik, mijn rol en mijn loopbaan • Opleidingsbeeld ‘leren leren bij Landstede’ • Beroepsbeeld ‘leren leren bij Landstede’","page":13},{"id":"bron-1-25","sourceId":"bron-1","title":"In e-TO ziet dat er bij jouw begin als volgt uit:","text":"Je ziet per vak 4 bolletjes staan. Bolletje 1 kleurt groen bij start van de periode. Binnen e- TO vul je een SMART geformuleerd leerdoel in. Zodra je dat hebt gedaan ga je automatisch door naar bolletje 2. Dit is de periode dat je het onderwijs volgt.","page":13},{"id":"bron-1-26","sourceId":"bron-1","title":"Afronden van vakken","text":"Ieder vak in elke periode krijgt een bepaalde afronding. Denk hierbij aan een kennistoets, een presentatie of het schrijven van een verslag. Dit wordt door de betreffende docent bepaald, meestal in afstemming met de groep. Deze afronding moet zijn voldaan/behaald om de periode af te ronden.","page":14},{"id":"bron-1-27","sourceId":"bron-1","title":"Afronden van vakken","text":"Daarnaast schrijf je aan het eind van de periode een afsluitende reflectie in e-TO. Als je dit hebt gedaan kleurt bolletje 3 groen. Vervolgens vraag je goedkeuring aan voor afronding van het vak bij de betreffende vakdocent. Bij bolletje 4 verschijnt dan een vraagteken.","page":14},{"id":"bron-1-28","sourceId":"bron-1","title":"Afronden van vakken","text":"Wanneer de vakdocent jouw reflectie goedkeurt en je de afgesproken afronding hebt behaald wordt bolletje 4 ook groen. Je hebt het vak dan behaald/afgesloten.","page":14},{"id":"bron-1-29","sourceId":"bron-1","title":"Fasen van de opleiding + Leerwerkprestaties (LWP’s)","text":"Landstede heeft de opleiding ingedeeld in 3 fases: Starter, gevorderd & beroepsbekwaam. Het kan per student verschillen hoelang het duurt deze verschillende fasen te doorlopen. De visie van Landstede is: ‘Talentvol ontwikkelen’. Alle studenten volgen hun eigen route in hun eigen tempo. Dat betekent ook dat niet iedereen met hetzelfde aan het werk is.","page":15},{"id":"bron-1-30","sourceId":"bron-1","title":"Fasen van de opleiding + Leerwerkprestaties (LWP’s)","text":"Maar uiteindelijk moet iedereen voldoen aan het kwalificatiedossier dat is vastgesteld door het ministerie van onderwijs. Uiteindelijk doorloopt iedere student dus dezelfde leerwerkprestaties (LWP’s) richting het afstuderen.","page":15},{"id":"bron-1-31","sourceId":"bron-1","title":"Starter fase","text":"Je begint met je opleiding, wordt ingewerkt, gaat je eerste lessen volgen en je begint aan de eerste opdrachten. Het volgende wordt van je verwacht:","page":15},{"id":"bron-1-32","sourceId":"bron-1","title":"Starter fase","text":"BPV-opdrachten: Op www.debpvwijzer.nl vind je een lijst met opdrachten voor starters waar je aan kunt werken. Je kiest 8 à 10 BPV opdrachten uit, hier ga je in je eerste jaar mee aan de slag. BPV-opdrachten helpen je in de voorbereiding op examens toe. Kies dus opdrachten waar je nog weinig vanaf weet. • LWP’s: Je gaat aan de slag met de LWP’s. Iedere LWP heeft een nummer. In ETO vind je een catalogus.","page":15},{"id":"bron-1-33","sourceId":"bron-1","title":"Starter fase","text":"Hier kan je de LWP opzoeken en bekijken welke doelen er in de LWP staan. De afronding verschilt per LWP. Bespreek met je coach hoe je de LWP afrondt. In de startersfase werk je aan onderstaande LWP’s. Sommige LWP’s zijn gemarkeerd met een kruisje. Deze zijn verplicht. De overige LWP’s zijn optioneel.","page":15},{"id":"bron-1-34","sourceId":"bron-1","title":"Periodes","text":"Start Basiszorg Je volgt praktijklessen, maakt de opdrachten en de E learnings.","page":15},{"id":"bron-1-35","sourceId":"bron-1","title":"Begeleiden Theorielessen","text":"Anatomie en fysiologie (AFGP, lint) Theorielessen AFGP + E learnings Expertcollege","page":15},{"id":"bron-1-36","sourceId":"bron-1","title":"Voorlichting Advies en Instructie (VAI) Theorielessen","text":"LLB Burgerschap: Van start tot examen (lint) 2 delen: Een verslag bij start van de opleiding (start) en een verslag aan het eind van de opleiding (mijlpaal).","page":15},{"id":"bron-1-37","sourceId":"bron-1","title":"Voorlichting Advies en Instructie (VAI) Theorielessen","text":"Opleidingsbeeld ‘leren leren bij Landstede’ Je werkt zelfstandig aan opdrachten. Hierdoor krijg je een goed beeld van de opleiding. Advies om dit snel na de start te doen.","page":16},{"id":"bron-1-38","sourceId":"bron-1","title":"Voorlichting Advies en Instructie (VAI) Theorielessen","text":"Beroepsbeeld werkt zelfstandig aan opdrachten. Hierdoor krijg je een goed beeld van de opleiding. Advies om dit snel na de start te doen.","page":16},{"id":"bron-1-39","sourceId":"bron-1","title":"Gevorderde fase","text":"Zodra je de startersfase gaat afronden, je bent dan een mooi eindje op weg, ga je werken aan de opdrachten die horen bij de gevorderde fase. Het volgende wordt van je verwacht:","page":16},{"id":"bron-1-40","sourceId":"bron-1","title":"Gevorderde fase","text":"BPV-opdrachten: Op www.debpvwijzer.nl vind je een lijst met opdrachten voor gevorderden waar je aan kunt werken. Je kiest 8 à 10 BPV opdrachten uit waar je mee aan de slag gaat. • LWP’s: Binnen de gevorderde fase ga je aan de slag met nieuwe/andere LWP’s. Zie onderstaand overzicht. Ook hier geldt: De LWP’s die gemarkeerd zijn met een kruisje zijn verplicht. De overige LWP’s optioneel.","page":16},{"id":"bron-1-41","sourceId":"bron-1","title":"Handelen in onvoorziene situaties Praktijklessen + examens EHBO & reanimatie","text":"Medisch rekenen Zelfstandig oefenen met medisch rekenen, per onderdeel een apart examen","page":16},{"id":"bron-1-42","sourceId":"bron-1","title":"Methodisch werken gevorderden Theorielessen","text":"Kwaliteit en deskundigheid start Zelfstandig werken aan E learnings Expertcollege","page":16},{"id":"bron-1-43","sourceId":"bron-1","title":"Combi ger/chr zorgvrager Theorielessen","text":"Gehandicaptenzorg Zelfstandig 10 opdrachten uit de LWP uitwerken. Alternatief is een dag meelopen in het werkveld, als je dit zelf kunt regelen. Bespreek de voorwaarden hiervoor met je coach.","page":17},{"id":"bron-1-44","sourceId":"bron-1","title":"GGZ de start Theorielessen","text":"Kraamzorg Zelfstandig LWP uitwerken. Alternatief is een dag meelopen in het werkveld, als je dit zelf kunt regelen. Bespreek de voorwaarden hiervoor met je coach.","page":17},{"id":"bron-1-45","sourceId":"bron-1","title":"Nee 1","text":"Beroepsbekwame fase De laatste fase van je opleiding noemen we de beroepsbekwame fase. Binnen deze fase werk je in principe niet meer aan BPV-opdrachten, tenzij dit voor jou helpend is. Ook bij de beroepsbekwame fase horen een aantal LWP’s:","page":18},{"id":"bron-1-46","sourceId":"bron-1","title":"Zorgvrager in beeld Zelfstandig LWP uitwerken","text":"Werkbegeleiding Theorielessen. Je mag als vervanging van deze LWP ook de cursus werkbegeleiding volgen vanuit de zorggroep. Stem dit af met je coach.","page":18},{"id":"bron-1-47","sourceId":"bron-1","title":"CGI Theorielessen","text":"Overige LWP’s Er zijn nog een aantal LWP’s die naar keuze kunnen worden gemaakt of worden opgenomen in het lesrooster. Beroepsethiek is een LWP die we binnen de setting van Boerhaavehof dusdanig belangrijk vinden dat dit wordt ingeroosterd.","page":18},{"id":"bron-1-48","sourceId":"bron-1","title":"Feedbackformulieren","text":"Je bent in opleiding dus het is belangrijk niet ‘zomaar je dienst te komen werken’. Voor aanvang van een dienst geef je een leerdoel voor die dag aan. Na afloop bespreek je hoe het gegaan is en vraag je om feedback. Minimaal 2x per week laat je door je collega/begeleider een feedbackformulier invullen. Deze plaats je vervolgens in Teams (zorggroep-Boerhaavehof).","page":19},{"id":"bron-1-49","sourceId":"bron-1","title":"BPV meter","text":"De BPV meter heeft als doel jouw ontwikkeling en voortgang in beeld te brengen. 2 keer per jaar vullen zowel jij als je begeleider(s) onafhankelijk van elkaar een BPV meter in. Jij beoordeeld dus jezelf en je begeleiders beoordelen jou. Vervolgens ga je samen in gesprek. Je vergelijkt de BPV meters met elkaar en bespreekt de verschillen. Samen kom je tot een definitieve beoordeling. Op www.debpvwijzer.nl vind je de BPV meter, uitleg en een handige onderlegger.","page":19},{"id":"bron-1-50","sourceId":"bron-1","title":"BPV opdrachten","text":"Op www.debpvwijzer.nl vind je BPV opdrachten. Dit zijn opdrachten die je kunt uitwerken ter voorbereiding op je examens. Advies is om gedurende je opleiding +- 18 opdrachten uit te werken, je zult werken dat je dit houvast geeft in je leerontwikkeling. Je bent zelf vrij om opdrachten te kiezen waarvan jij denkt dat ze van toegevoegde waarde zijn voor jouw leerproces. Je kunt hierin ook overleggen met je praktijkleercoach.","page":19},{"id":"bron-1-51","sourceId":"bron-1","title":"BPV opdrachten","text":"Je BPV opdrachten laat je beoordelen door je werkbegeleider binnen Boerhaavehof.","page":19},{"id":"bron-1-52","sourceId":"bron-1","title":"Voortgangsgesprek","text":"Iedere 3 weken evalueer je met je werkbegeleider(s) jouw voortgang. Punten die besproken zijn:","page":20},{"id":"bron-1-53","sourceId":"bron-1","title":"Voortgangsgesprek","text":"Hoe gaat het met je? Loop je ergens tegenaan? • Waar sta je in je leerproces? • Wat zijn je doelen voor de komende 3 weken? Naar welk examen werk je toe? • Hoe gaat het met het verzamelen van feedback en het plaatsen in de leeromgeving?","page":20},{"id":"bron-1-54","sourceId":"bron-1","title":"Actie werkbegeleider:","text":"Bij missend initiatief de student aanspreken. • Verslag van de student binnen 1 week beoordelen en Go/No Go geven binnen de chatpagina.","page":20},{"id":"bron-1-55","sourceId":"bron-1","title":"BPV-gesprek","text":"In het BPV-gesprek bespreek je jouw voortgang in studie en praktijk. Aan de hand van je POP & PAP wordt gekeken naar je functioneren op de werkvloer en je studievoortgang. Ook de BPV meter kan hierbij worden ingevuld, al loopt dit niet altijd synchroon met de BPV gesprekken.","page":21},{"id":"bron-1-56","sourceId":"bron-1","title":"BPV-gesprek","text":"Aanwezig: Student, praktijkleercoach (Everlien), coach (Hennie/Henri) en minimaal één van je werkbegeleiders (of een vervanger) Student, werkbegeleider(s)","page":21},{"id":"bron-1-57","sourceId":"bron-1","title":"Actie werkbegeleider:","text":"Indien nodig de BPV meter invullen • Aanwezig zijn bij het BPV-gesprek","page":21},{"id":"bron-1-58","sourceId":"bron-1","title":"Leermetergesprek","text":"In het leermetergesprek bespreek je samen met je coach jouw voortgang a.d.h.v. de leermeter in ETO. Je geeft aan bij je coach waar jij denkt dat de leermeter opgeschoven kan worden en ondersteund dat met argumenten/bewijs. Aanwezig: Student & coach (Hennie/Henri)","page":22},{"id":"bron-1-59","sourceId":"bron-1","title":"Gaandeweg de opleiding rond je verschillende examens af:","text":"Rekenen, Engels, Nederlands • Werk in uitvoering • Zorg op maat • Communicatie en preventie • Afstemmen en samenwerken (2e voorlaatste examen) • Reageren in onvoorziene situatie(s) (Voorlaatste examen) • Professionele ontwikkeling en kwaliteit (Laatste examen)","page":24},{"id":"bron-1-60","sourceId":"bron-1","title":"Gaandeweg de opleiding rond je verschillende examens af:","text":"Je ziet dat de examens in een bepaalde volgorde zijn geplaatst. Dit is de meest logische volgorde om de examens af te nemen tijdens je opleiding. In de praktijk zal je als eerst aan het werk gaan met ‘werk in uitvoering'. Je coach zal je hier tijdens je opleiding verder in sturen.","page":24},{"id":"bron-1-61","sourceId":"bron-1","title":"Gaandeweg de opleiding rond je verschillende examens af:","text":"Om een examen te mogen examineren heb je toestemming van je werkbegeleider en je coach nodig. Dit kan je formeel vastleggen via een toestemmingsformulier. Verder moet je de bijbehorende theorie hebben afgerond.","page":24},{"id":"bron-1-62","sourceId":"bron-1","title":"Elektronisch Portfolio Prove2Move (EPP)","text":"Je krijgt bij de start van je opleiding toegang tot een ''digitale examenmap''. Dit is het EPP. Je coach zorgt ervoor dat je wordt aangemeld in het EPP. Je krijgt via de mail een link waarin je vervolgens kan inloggen in het EPP.","page":24},{"id":"bron-1-63","sourceId":"bron-1","title":"Elektronisch Portfolio Prove2Move (EPP)","text":"Zodra je eraan toe bent een examen te gaan afleggen en je aan de voorwaarden voldoet (toestemmingsformulier), meld je dit bij je coach. Die plaatst het betreffende examen van in het EPP. De examinator vult dan de beoordeling digitaal in.","page":24},{"id":"bron-1-64","sourceId":"bron-1","title":"Elektronisch Portfolio Prove2Move (EPP)","text":"Per examen wat in het EPP wordt geplaatst worden kosten in rekening gebracht aan de school. Dat is de reden dat niet direct alle examens op voorhand al in de EPP worden geplaatst.","page":24},{"id":"bron-1-65","sourceId":"bron-1","title":"Elektronisch Portfolio Prove2Move (EPP)","text":"Binnen het EPP vind je duidelijke handleidingen voor het gebruik. Advies is om deze even te bekijken aan het begin van je opleiding.","page":24},{"id":"bron-1-66","sourceId":"bron-1","title":"Veel gestelde vragen","text":"Waar vind ik alle informatie over BPV (opdrachten, gesprekken, BPV meter etc.?) Op www.debpvwijzer.nl • Ik heb binnenkort een BPV-gesprek. Moet dat moment ook de BPV meter zijn ingevuld? Dat kan, maar hoeft niet persé. De BPV meter moet 2x per jaar worden ingevuld maar staat in principe los van het BPV gesprek. Als het wel ongeveer gelijk loopt is dat mooi meegenomen. • Hoe schrijf ik je in voor een BPV-gesprek of leermeter gesprek?","page":25},{"id":"bron-1-67","sourceId":"bron-1","title":"Veel gestelde vragen","text":"Het rooster in Teams bevat een tabel waar je kan inschrijven op een datum. • Ik wil een BPV-gesprek plannen maar het lukt echt niet om dit te plannen met mijn werkbegeleiders. Regel i.o. met je werkbegeleiders een vervangende die hen kan vervangen in het gesprek. Het is handig dat dit een collega is waar je ook regelmatig mee hebt gewerkt.","page":25},{"id":"bron-1-68","sourceId":"bron-1","title":"Veel gestelde vragen","text":"Onderkent de gezondheidstoestand op somatisch en psychosociaal gebied (gezondheidsbevorderaar) • Voert zorg/ begeleidingsactiviteiten uit (Zorgverlener)","page":27},{"id":"bron-1-69","sourceId":"bron-1","title":"Begeleiden (17054) Anatomie & fysiologie (13436)","text":"Voorlichting, advies en instructie (17725) GHZ de start (13852) (verplicht) GGZ de start (17453) (verplicht) Kraamzorg (17356) (verplicht) De chronische ZV (17448) Combinatie chronische/PG ZV (17449)","page":27},{"id":"bron-1-70","sourceId":"bron-1","title":"BPV- opdrachten:","text":"Examen Communicatie en preventie K1 W2, 6 Kerntaak 1 Werkprocess en 2,6","page":27},{"id":"bron-1-71","sourceId":"bron-1","title":"BPV- opdrachten:","text":"Adviseert en instrueert over preventie • Communiceert met de zorgvrager en het sociale netwerk","page":27},{"id":"bron-1-72","sourceId":"bron-1","title":"BPV- opdrachten:","text":"Lwp’s: Start: Gevorderd: Beroeps bekwaam: Begeleiden (17054) Interculturele communicatie (10606) VAI: Voorlichting Advies en Instructie (17725) BPV- opdrachten:","page":27},{"id":"bron-1-73","sourceId":"bron-1","title":"BPV- opdrachten:","text":"Draagt mede zorg voor het individuele plan van de zorgvrager (zorgverlener)","page":28},{"id":"bron-1-74","sourceId":"bron-1","title":"BPV- opdrachten:","text":"Lwp’s: Start: Gevorderd: Beroeps bekwaam: Basiszorg (16849) Begeleiden (17054) Methodisch werken e-learning (15228)","page":28},{"id":"bron-1-75","sourceId":"bron-1","title":"BPV- opdrachten:","text":"De (psycho)geriatrische ZV (10954) De chronische ZV (17448) Combinatie chronische/PG ZV (17449) Revaliderende zorgvrager (16809) Omgaan met de psychiatrische zorgvrager (16814) Gehandicaptenzorg starter en gevorderd (13852) Palliatieve zorg (14311)","page":28},{"id":"bron-1-76","sourceId":"bron-1","title":"BPV- opdrachten:","text":"Methodisch werken 2 (17809) Kwaliteitszorg en deskundigheid e-learning (15227) PDL: Passiviteit Dagelijks Leven (14409) De zorgvrager in beeld (17434)","page":28},{"id":"bron-1-77","sourceId":"bron-1","title":"BPV- opdrachten:","text":"Examen Afstemmen & samenwerken K1 W7 K2 W2 Kerntaak 1 Werkproces 7 Kerntaak 2 Werkproces 2","page":28},{"id":"bron-1-78","sourceId":"bron-1","title":"BPV- opdrachten:","text":"Stemt de zorgverlening af met de zorgvrager en betrokkenen (Organisator)","page":28},{"id":"bron-1-79","sourceId":"bron-1","title":"BPV- opdrachten:","text":"Werkt samen met andere beroepsgroepen in keten Lwp’s: Start: Gevorderd: Beroeps bekwaam: Basiszorg (16849) Begeleiden (17054)","page":28},{"id":"bron-1-80","sourceId":"bron-1","title":"Coördineren van zorg start (17452)","text":"Coördinatie en Ketenzorg (15220) De zorgvrager in beeld (17434) BPV-opdrachten: Zie overzicht www.debpvwijzer.nl Zie overzicht www.debpvwijzer.nl","page":28},{"id":"bron-1-81","sourceId":"bron-1","title":"Coördineren van zorg start (17452)","text":"Lwp’s: Start: Gevorderd: Beroeps bekwaam: Medisch rekenen (17296) VTH 1 (16062) VTH 2 (16095)","page":29},{"id":"bron-1-82","sourceId":"bron-1","title":"Coördineren van zorg start (17452)","text":"Handelen in onvoorziene situaties VIG (16342) VTH 3 (16100) BPV-opdrachten: Zie overzicht www.debpvwijzer.nl","page":29},{"id":"bron-1-83","sourceId":"bron-1","title":"Reageert op onvoorziene en crisissituaties","text":"Lwp’s: Start: Gevorderd: Beroeps bekwaam: Basiszorg (16849) Anatomie & fysiologie (13436)","page":29},{"id":"bron-1-84","sourceId":"bron-1","title":"Reageert op onvoorziene en crisissituaties","text":"GHZ de start (13852) (verplicht) GGZ de start (17453) (verplicht) Kraamzorg (17356) (verplicht) De (psycho)geriatrische ZV (10954) De chronische ZV (17448) Combinatie chronische/PG ZV (17449) Revaliderende zorgvrager (16809) Palliatieve zorg (14311) Kwetsbare ouderen (10155)","page":29},{"id":"bron-1-85","sourceId":"bron-1","title":"Reageert op onvoorziene en crisissituaties","text":"Examen prof. ontwikkeling & kwaliteitszorg K1 W 1,3 Kerntaak Werkprocessen","page":29},{"id":"bron-1-86","sourceId":"bron-1","title":"Reageert op onvoorziene en crisissituaties","text":"Zorgt voor professionele ontwikkeling (reflectieve EBP-professional) • Draagt bij aan goede kwaliteit van zorg (Professional en kwaliteitsverbeteraar) Lwp’s: Start: Gevorderd: Beroeps bekwaam: Kwaliteitszorg en deskundigheid e-learning (15227) Werkbegeleiding (16349) Intervisie (17451) Ethiek (18104)","page":29},{"id":"bron-1-87","sourceId":"bron-1","title":"Reageert op onvoorziene en crisissituaties","text":"Kwaliteit en deskundigheid (12078) CGI (15212) GHZ beroeps bekwaam (13719)","page":29},{"id":"bron-2-1","sourceId":"bron-2","title":"Start met de opleiding","text":"Je begint met een opleiding en dan komt er veel op je af. Je krijgt de tijd om hier rustig je weg in te vinden. Om je wat houvast te geven hierbij een checklist voor je eerste dagen/weken van je opleiding:","page":4},{"id":"bron-2-2","sourceId":"bron-2","title":"Voorbereiding eerste lesdag","text":"De laptop is cruciaal om aan je opdrachten te kunnen werken, mee te doen met het onderwijs en gebruik te maken van alle digitale systemen. Voorafgaand aan de start van je opleiding krijg je een brief met tips en informatie over de aanschaf van een laptop. • Check je inloggegevens. Je gaat werken met verschillende systemen en daarbij","page":4},{"id":"bron-2-3","sourceId":"bron-2","title":"Voorbereiding eerste lesdag","text":"moet je inloggen. De inloggegevens ontvang je voorafgaand aan je opleiding thuis. Kijk er vast naar of neem ze mee op je eerste lesdag. • Zorg dat je een digitale foto beschikbaar hebt voor in het schoolsysteem en op de","page":4},{"id":"bron-2-4","sourceId":"bron-2","title":"Eerste lesdag/week","text":"Je sluit s ‘ochtends om 09.00 uur aan bij de groep. Je draait mee in de eerste les.","page":4},{"id":"bron-2-5","sourceId":"bron-2","title":"Eerste lesdag/week","text":"Je hoeft je hierop niet voor te bereiden • In het tweede blok staat een coach uur gepland. Hierin wordt tijd gereserveerd","page":4},{"id":"bron-2-6","sourceId":"bron-2","title":"Eerste lesdag/week","text":"waarin je door een van de docenten uitleg krijgt over: - Inloggen in de digitale systemen (Eduarte, ETO, Connect) - Uploaden van een foto & aanvragen studentenpas (Eenmaal ingelogd mag je jouw foto uploaden via het studentendashboard op Connect en je studentpas aanvragen.","page":4},{"id":"bron-2-7","sourceId":"bron-2","title":"Eerste lesdag/week","text":"Die krijg je dan volgende week binnen via je coach. - Boeken bestellen (Je gaat boeken bestellen via www.mbowebshop.nl De docent geeft aan welke boeken je kunt bestellen) - Je studiemaatje (Je wordt tijdens je opleiding gekoppeld aan een medestudent die als maatje fungeert. Gebruik je maatje om uitleg te vragen over de opleiding, de systemen etc.) - Invullen derdenmachtiging schoolgeld - Procedure ziekmelden","page":4},{"id":"bron-2-8","sourceId":"bron-2","title":"In het coach uur krijg je uitleg over:","text":"ILP (Individueel leerplan) - Evt. Vrijstellingen - Werken met de digitale systemen (Eduarte, ETO, Connect, Teams) door je maatje","page":5},{"id":"bron-2-9","sourceId":"bron-2","title":"Taken en verantwoordelijkheden","text":"Binnen je opleiding krijg je met verschillende personen te maken. Een overzichtje van functies, namen en bijbehorende taken en verantwoordelijkheden:","page":6},{"id":"bron-2-10","sourceId":"bron-2","title":"Vakken","text":"Je volgt tijdens je opleiding verschillende vakken. Het gaat om ''generieke vakken'' en ''zorg vakken''.","page":9},{"id":"bron-2-11","sourceId":"bron-2","title":"Generieke vakken","text":"Generieke vakken zijn algemene vakken die iedere MBO student doorloopt. Het gaat hier om:","page":9},{"id":"bron-2-12","sourceId":"bron-2","title":"Generieke vakken","text":"In sommige gevallen krijgen studenten op basis van hun vooropleiding een vrijstelling. Dit moet je bespreken met je coach.","page":9},{"id":"bron-2-13","sourceId":"bron-2","title":"Generieke vakken","text":"Het is verstandig om in de eerste fase van de opleiding te werken aan de generieke vakken zodat dit niet ‘opstapelt’ aan het eind van de opleiding.","page":9},{"id":"bron-2-14","sourceId":"bron-2","title":"Generieke vakken","text":"Bij (mogelijke) problemen is extra hulp en begeleiding aan te vragen via het studentadviesbureau (SAB)","page":9},{"id":"bron-2-15","sourceId":"bron-2","title":"Zorgvakken","text":"Tijdens de opleiding krijg je een heel aantal vakken aangeboden die direct gerelateerd zijn aan de zorg. Voorbeelden hiervan zijn:","page":9},{"id":"bron-2-16","sourceId":"bron-2","title":"Zorgvakken","text":"Basiszorg (Wassen, aankleden, verplaatsingstechnieken etc.) • Begeleiden • Gezondheidsvoorlichting • Verpleegtechnische handelingen • Medisch rekenen • Schrijven van een zorgplan • Anatomie/fysiologie/pathologie (AFGP) • Branche vakken (AGZ, VVT, GGZ, GHZ) • Coördineren van zorg • Kwaliteitszorg","page":9},{"id":"bron-2-17","sourceId":"bron-2","title":"Fasen van de opleiding + Leerwerkprestaties (LWP’s)","text":"Landstede heeft de opleiding ingedeeld in 3 fases: Starter, gevorderd & beroepsbekwaam. Het kan per student verschillen hoelang het duurt deze verschillende fasen te doorlopen. De visie van Landstede is: ‘Talentvol ontwikkelen’. Alle studenten volgen hun eigen route in hun eigen tempo. Dat betekent ook dat niet iedereen met hetzelfde aan het werk is.","page":12},{"id":"bron-2-18","sourceId":"bron-2","title":"Fasen van de opleiding + Leerwerkprestaties (LWP’s)","text":"Maar uiteindelijk moet iedereen voldoen aan het kwalificatiedossier dat is vastgesteld door het ministerie van onderwijs. Uiteindelijk doorloopt iedere student dus dezelfde leerwerkprestaties (LWP’s) richting het afstuderen.","page":12},{"id":"bron-2-19","sourceId":"bron-2","title":"Starter fase","text":"Je begint met je opleiding, wordt ingewerkt, gaat je eerste lessen volgen en je begint aan de eerste opdrachten. Het volgende wordt van je verwacht:","page":12},{"id":"bron-2-20","sourceId":"bron-2","title":"Starter fase","text":"BPV-opdrachten: Op www.debpvwijzer.nl vind je een lijst met opdrachten voor starters waar je aan kunt werken. Je kiest 8 à 10 BPV opdrachten uit, hier ga je in je eerste jaar mee aan de slag. BPV-opdrachten helpen je in de voorbereiding op examens toe. Kies dus opdrachten waar je nog weinig vanaf weet. • LWP’s: Je gaat aan de slag met de LWP’s. Iedere LWP heeft een nummer. In ETO vind je een catalogus.","page":12},{"id":"bron-2-21","sourceId":"bron-2","title":"Starter fase","text":"Hier kan je de LWP opzoeken en bekijken welke doelen er in de LWP staan. De afronding verschilt per LWP. Bespreek met je coach hoe je de LWP afrondt. In de startersfase werk je aan onderstaande LWP’s. Sommige LWP’s zijn gemarkeerd met een kruisje. Deze zijn verplicht. De overige LWP’s zijn optioneel.","page":12},{"id":"bron-2-22","sourceId":"bron-2","title":"Periodes","text":"Basiszorg Je volgt praktijklessen, maakt de opdrachten en de E learnings.","page":12},{"id":"bron-2-23","sourceId":"bron-2","title":"Begeleiden Theorielessen","text":"Anatomie en fysiologie (AFGP, lint) Theorielessen AFGP + E learnings Expertcollege","page":12},{"id":"bron-2-24","sourceId":"bron-2","title":"Voorlichting Advies en Instructie (VAI) Theorielessen","text":"LLB Burgerschap: Van start tot examen (lint) 2 delen: Een verslag bij start van de opleiding (start)","page":12},{"id":"bron-2-25","sourceId":"bron-2","title":"Voorlichting Advies en Instructie (VAI) Theorielessen","text":"en een verslag aan het eind van de opleiding (mijlpaal). LOB mijn ik, mijn rol, mijn loopbaan 18204 Ja Opleidingsbeeld ‘leren leren bij Landstede’ Je werkt zelfstandig aan opdrachten. Hierdoor krijg je een goed beeld van de opleiding. Advies om dit snel na de start te doen.","page":13},{"id":"bron-2-26","sourceId":"bron-2","title":"Voorlichting Advies en Instructie (VAI) Theorielessen","text":"Beroepsbeeld werkt zelfstandig aan opdrachten. Hierdoor krijg je een goed beeld van de opleiding. Advies om dit snel na de start te doen.","page":13},{"id":"bron-2-27","sourceId":"bron-2","title":"Gevorderde fase","text":"Zodra je de startersfase gaat afronden, je bent dan een mooi eindje op weg, ga je werken aan de opdrachten die horen bij de gevorderde fase. Het volgende wordt van je verwacht:","page":13},{"id":"bron-2-28","sourceId":"bron-2","title":"Gevorderde fase","text":"BPV-opdrachten: Op www.debpvwijzer.nl vind je een lijst met opdrachten voor gevorderden waar je aan kunt werken. Je kiest 8 à 10 BPV opdrachten uit waar je mee aan de slag gaat. • LWP’s: Binnen de gevorderde fase ga je aan de slag met nieuwe/andere LWP’s. Zie onderstaand overzicht. Ook hier geldt: De LWP’s die gemarkeerd zijn met een kruisje zijn verplicht. De overige LWP’s optioneel.","page":13},{"id":"bron-2-29","sourceId":"bron-2","title":"Handelen in onvoorziene situaties Praktijklessen + examens EHBO & reanimatie","text":"Medisch rekenen Zelfstandig oefenen met medisch rekenen, per onderdeel een apart examen","page":13},{"id":"bron-2-30","sourceId":"bron-2","title":"Methodisch werken gevorderden Theorielessen","text":"Kwaliteit en deskundigheid start Zelfstandig werken aan E learnings Expertcollege","page":13},{"id":"bron-2-31","sourceId":"bron-2","title":"Combi geriatrie/chronische zorgvrager Theorielessen","text":"Gehandicaptenzorg Zelfstandig 10 opdrachten uit de LWP uitwerken. Alternatief is een dag meelopen in het werkveld, als je dit zelf kunt regelen. Bespreek de voorwaarden hiervoor met je coach.","page":14},{"id":"bron-2-32","sourceId":"bron-2","title":"GGZ de start Theorielessen","text":"Kraamzorg Zelfstandig LWP uitwerken. Alternatief is een dag meelopen in het werkveld, als je dit zelf kunt regelen. Bespreek de voorwaarden hiervoor met je coach.","page":14},{"id":"bron-2-33","sourceId":"bron-2","title":"Kwetsbare ouderen Theorielessen","text":"Klinisch redeneren Theorielessen. Afhankelijk van de roosters kunnen verschillende thema's worden aangeboden. Je volgt er minimaal 2: - Maag/darm/uro - Bewegingstelsel/huid - Hart/long - Centraal zenuwstelsel - Oncologie - Immuno/hormonen - Pathologie verdieping","page":14},{"id":"bron-2-34","sourceId":"bron-2","title":"Kwetsbare ouderen Theorielessen","text":"Verdiepend Theorielessen over verschillende thema's. In samenspraak met de docent worden 2 thema's gekozen: - Therapeutisch milieu - Verslaving - Somatiek in GGZ - Omgaan met psychische zorgvrager","page":14},{"id":"bron-2-35","sourceId":"bron-2","title":"Kwetsbare ouderen Theorielessen","text":"16814 14322 9691 Beroepsbekwame fase De laatste fase van je opleiding noemen we de beroepsbekwame fase. Binnen deze fase werk je in principe niet meer aan BPV-opdrachten, tenzij dit voor jou helpend is. Ook bij de beroepsbekwame fase horen een aantal LWP’s:","page":15},{"id":"bron-2-36","sourceId":"bron-2","title":"Periodes","text":"Werkbegeleiding Theorielessen. Je mag als vervanging van deze LWP ook de cursus werkbegeleiding volgen vanuit de zorggroep. Stem dit af met je coach.","page":15},{"id":"bron-2-37","sourceId":"bron-2","title":"CGI Theorielessen","text":"Overige LWP’s Er zijn nog een aantal LWP’s die naar keuze kunnen worden gemaakt of worden opgenomen in het lesrooster. Beroepsethiek is een LWP die we binnen de setting van Boerhaavehof dusdanig belangrijk vinden dat dit wordt ingeroosterd.","page":15},{"id":"bron-2-38","sourceId":"bron-2","title":"Feedbackformulieren","text":"Je bent in opleiding dus het is belangrijk niet ‘zomaar je dienst te komen werken’. Voor aanvang van een dienst geef je een leerdoel voor die dag aan. Na afloop bespreek je hoe het gegaan is en vraag je om feedback. Minimaal 2x per week laat je door je collega/begeleider een feedbackformulier invullen. Deze plaats je vervolgens in Teams (zorggroep-Boerhaave hof).","page":17},{"id":"bron-2-39","sourceId":"bron-2","title":"BPV meter","text":"De BPV meter heeft als doel jouw ontwikkeling en voortgang in beeld te brengen. 2 keer per jaar vullen zowel jij als je begeleider(s) onafhankelijk van elkaar een BPV meter in. Jij beoordeeld dus jezelf en je begeleiders beoordelen jou. Vervolgens ga je samen in gesprek. Je vergelijkt de BPV meters met elkaar en bespreekt de verschillen. Samen kom je tot een definitieve beoordeling. Op www.debpvwijzer.nl vind je de BPV meter, uitleg en een handige onderlegger.","page":17},{"id":"bron-2-40","sourceId":"bron-2","title":"BPV opdrachten","text":"Op www.debpvwijzer.nl vind je BPV opdrachten. Dit zijn opdrachten die je kunt uitwerken ter voorbereiding op je examens. Advies is om gedurende je opleiding +- 18 opdrachten uit te werken, je zult werken dat je dit houvast geeft in je leerontwikkeling. Je bent zelf vrij om opdrachten te kiezen waarvan jij denkt dat ze van toegevoegde waarde zijn voor jouw leerproces. Je kunt hierin ook overleggen met je praktijkleercoach.","page":17},{"id":"bron-2-41","sourceId":"bron-2","title":"BPV opdrachten","text":"Je BPV opdrachten laat je beoordelen door je werkbegeleider binnen Boerhaavehof.","page":17},{"id":"bron-2-42","sourceId":"bron-2","title":"Gesprekken","text":"Binnen je opleiding voer je regelmatig gesprekken om jouw voortgang te bespreken. In dit hoofdstuk vind je een overzicht van de gesprekken en wat er per gesprek gevraagd wordt qua voorbereiding en evt. ter verwerking.","page":18},{"id":"bron-2-43","sourceId":"bron-2","title":"Voortgangsgesprek","text":"Iedere 3 weken evalueer je met je werkbegeleider(s) jouw voortgang. Punten die besproken zijn:","page":18},{"id":"bron-2-44","sourceId":"bron-2","title":"Voortgangsgesprek","text":"Hoe gaat het met je? Loop je ergens tegenaan? • Waar sta je in je leerproces? • Wat zijn je doelen voor de komende 3 weken? Naar welk examen werk je toe? • Hoe gaat het met het verzamelen van feedback en het plaatsen in de leeromgeving?","page":18},{"id":"bron-2-45","sourceId":"bron-2","title":"Actie werkbegeleider:","text":"Bij missend initiatief de student aanspreken. • Verslag van de student binnen 1 week beoordelen en Go/No Go geven binnen de chatpagina.","page":18},{"id":"bron-2-46","sourceId":"bron-2","title":"BPV-gesprek","text":"In het BPV-gesprek bespreek je jouw voortgang in studie en praktijk. Aan de hand van je POP & PAP wordt gekeken naar je functioneren op de werkvloer en je studievoortgang. Ook de BPV meter kan hierbij worden ingevuld, al loopt dit niet altijd synchroon met de BPV gesprekken.","page":19},{"id":"bron-2-47","sourceId":"bron-2","title":"BPV-gesprek","text":"Aanwezig: Student, praktijkleercoach (Everlien), coach (Hennie/Henri) en minimaal één van je werkbegeleiders (of een vervanger) Student, werkbegeleider(s)","page":19},{"id":"bron-2-48","sourceId":"bron-2","title":"Actie werkbegeleider:","text":"Indien nodig de BPV meter invullen • Aanwezig zijn bij het BPV-gesprek","page":19},{"id":"bron-2-49","sourceId":"bron-2","title":"Leermetergesprek","text":"In het leermetergesprek bespreek je samen met je coach jouw voortgang a.d.h.v. de leermeter in ETO. Je geeft aan bij je coach waar jij denkt dat de leermeter opgeschoven kan worden en ondersteund dat met argumenten/bewijs. Aanwezig: Student & coach (Hennie/Henri)","page":19},{"id":"bron-2-50","sourceId":"bron-2","title":"Gaandeweg de opleiding rond je verschillende examens af:","text":"Rekenen, Engels, Nederlands • Werk in uitvoering • Zorg op maat • Communicatie en preventie • Afstemmen en samenwerken (2e voorlaatste examen) • Reageren in onvoorziene situatie(s) (Voorlaatste examen) • Professionele ontwikkeling en kwaliteit (Laatste examen)","page":20},{"id":"bron-2-51","sourceId":"bron-2","title":"Gaandeweg de opleiding rond je verschillende examens af:","text":"Je ziet dat de examens in een bepaalde volgorde zijn geplaatst. Dit is de meest logische volgorde om de examens af te nemen tijdens je opleiding. In de praktijk zal je als eerst aan het werk gaan met ‘werk in uitvoering'. Je coach zal je hier tijdens je opleiding verder in sturen.","page":20},{"id":"bron-2-52","sourceId":"bron-2","title":"Gaandeweg de opleiding rond je verschillende examens af:","text":"Om een examen te mogen examineren heb je toestemming van je werkbegeleider en je coach nodig. Dit kan je formeel vastleggen via een toestemmingsformulier. Verder moet je de bijbehorende theorie hebben afgerond.","page":20},{"id":"bron-2-53","sourceId":"bron-2","title":"Elektronisch Portfolio Prove2Move (EPP)","text":"Je krijgt bij de start van je opleiding toegang tot een ''digitale examenmap''. Dit is het EPP. Je coach zorgt ervoor dat je wordt aangemeld in het EPP. Je krijgt via de mail een link waarin je vervolgens kan inloggen in het EPP.","page":20},{"id":"bron-2-54","sourceId":"bron-2","title":"Elektronisch Portfolio Prove2Move (EPP)","text":"Zodra je eraan toe bent een examen te gaan afleggen en je aan de voorwaarden voldoet (toestemmingsformulier), meld je dit bij je coach. Die plaatst het betreffende examen van in het EPP. De examinator vult dan de beoordeling digitaal in.","page":20},{"id":"bron-2-55","sourceId":"bron-2","title":"Elektronisch Portfolio Prove2Move (EPP)","text":"Per examen wat in het EPP wordt geplaatst worden kosten in rekening gebracht aan de school. Dat is de reden dat niet direct alle examens op voorhand al in de EPP worden geplaatst.","page":20},{"id":"bron-2-56","sourceId":"bron-2","title":"Elektronisch Portfolio Prove2Move (EPP)","text":"Binnen het EPP vind je duidelijke handleidingen voor het gebruik. Advies is om deze even te bekijken aan het begin van je opleiding.","page":20},{"id":"bron-2-57","sourceId":"bron-2","title":"Koppeling LWP's en examens","text":"Onderstaand een overzicht van de koppeling tussen de verschillende LWP’s en de examens.","page":21},{"id":"bron-2-58","sourceId":"bron-2","title":"Veel gestelde vragen","text":"Waar vind ik alle informatie over BPV (opdrachten, gesprekken, BPV meter etc.?) Op www.debpvwijzer.nl • Ik heb binnenkort een BPV-gesprek. Moet dat moment ook de BPV meter zijn ingevuld? Dat kan, maar hoeft niet persé. De BPV meter moet 2x per jaar worden ingevuld maar staat in principe los van het BPV gesprek. Als het wel ongeveer gelijk loopt is dat mooi meegenomen. • Hoe schrijf ik je in voor een BPV-gesprek of leermeter gesprek?","page":23},{"id":"bron-2-59","sourceId":"bron-2","title":"Veel gestelde vragen","text":"Het rooster in Teams bevat een tabel waar je kan inschrijven op een datum. • Ik wil een BPV-gesprek plannen maar het lukt echt niet om dit te plannen met mijn werkbegeleiders. Regel i.o. met je werkbegeleiders een vervangende die hen kan vervangen in het gesprek. Het is handig dat dit een collega is waar je ook regelmatig mee hebt gewerkt.","page":23},{"id":"bron-3-1","sourceId":"bron-3","title":"Start met de opleiding","text":"Je begint met een opleiding en dan komt er veel op je af. Je krijgt de tijd om hier rustig je weg in te vinden. Om je wat houvast te geven hierbij een checklist voor je eerste dagen/weken van je opleiding:","page":4},{"id":"bron-3-2","sourceId":"bron-3","title":"Voorbereiding eerste lesdag","text":"De laptop is cruciaal om aan je opdrachten te kunnen werken, mee te doen met het onderwijs en gebruik te maken van alle digitale systemen. Voorafgaand aan de start van je opleiding krijg je een brief met tips en informatie over de aanschaf van een laptop. o Check je inloggegevens. Je gaat werken met verschillende systemen en daarbij","page":4},{"id":"bron-3-3","sourceId":"bron-3","title":"Voorbereiding eerste lesdag","text":"moet je inloggen. De inloggegevens ontvang je voorafgaand aan je opleiding via de mail thuisgestuurd. Kijk er vast naar of neem ze mee op je eerste lesdag. o Zorg dat je een digitale foto beschikbaar hebt voor in het schoolsysteem en op de","page":4},{"id":"bron-3-4","sourceId":"bron-3","title":"Eerste lesdag/week","text":"o Je sluit s ‘ochtends om 09.00 uur aan bij de groep. Je draait mee in de eerste les.","page":4},{"id":"bron-3-5","sourceId":"bron-3","title":"Eerste lesdag/week","text":"Je hoeft je hier op niet voor te bereiden o In het tweede blok staat een coach uur gepland. Hierin wordt tijd gereserveerd","page":4},{"id":"bron-3-6","sourceId":"bron-3","title":"waarin je door een van de docenten uitleg krijgt over:","text":"Inloggen in de digitale systemen (Eduarte, ETO, Connect) • Uploaden van een foto & aanvragen schoolpas (Eenmaal ingelogd mag je","page":4},{"id":"bron-3-7","sourceId":"bron-3","title":"waarin je door een van de docenten uitleg krijgt over:","text":"jouw foto uploaden via het studentendashboard op Connect en een studentenpas aanvragen). Die krijg je dan volgende week binnen, via je coach. • Boeken bestellen (Je gaat boeken bestellen via www.mbowebshop.nl","page":4},{"id":"bron-3-8","sourceId":"bron-3","title":"waarin je door een van de docenten uitleg krijgt over:","text":"De docent geeft aan welke boeken je kunt bestellen) • Je studiemaatje (Je wordt tijdens je opleiding gekoppeld aan een","page":4},{"id":"bron-3-9","sourceId":"bron-3","title":"waarin je door een van de docenten uitleg krijgt over:","text":"medestudent die als maatje fungeert. Gebruik je maatje om uitleg te vragen over de opleiding, de systemen etc.) • Invullen derdenmachtiging schoolgeld • Procedure ziekmelden","page":4},{"id":"bron-3-10","sourceId":"bron-3","title":"In het coach uur krijg je uitleg over:","text":"ILP (Individueel leerplan) • Evt. vrijstellingen • Werken met de digitale systemen (Eduarte, ETO, Connect, Teams) door je","page":5},{"id":"bron-3-11","sourceId":"bron-3","title":"Indeling studiejaar","text":"Ieder studiejaar is ingedeeld in 4 periodes van ongeveer 10 weken. Voorafgaand","page":9},{"id":"bron-3-12","sourceId":"bron-3","title":"Indeling studiejaar","text":"aan iedere periode wordt in overleg met de studenten het lesrooster bepaald. Het lesrooster is geplaatst in Teams. • Aan het begin van iedere periode wordt per vak een studiewijzer voor de gehele","page":9},{"id":"bron-3-13","sourceId":"bron-3","title":"Indeling studiejaar","text":"periode opgesteld. Zo weet je precies welk onderwerp in welke week wordt behandeld. • Aan het eind van de periode wordt een bufferweek ingepland. De docenten","page":9},{"id":"bron-3-14","sourceId":"bron-3","title":"Indeling studiejaar","text":"gebruiken deze week om producten te beoordelen, reflecties na te kijken en een start te maken met het onderwijs voor de volgende periode. Als student heb je soms tijd om aan je opdrachten te werken of doe je een activiteit binnen je afdeling. Ook worden er in de bufferweek gastlessen georganiseerd vanuit de Zorgggroep Noord West Veluwe.","page":9},{"id":"bron-3-15","sourceId":"bron-3","title":"Vakken","text":"Je volgt tijdens je opleiding verschillende vakken. Het gaat om ''generieke vakken'' en ''zorg vakken''.","page":11},{"id":"bron-3-16","sourceId":"bron-3","title":"Generieke vakken","text":"Generieke vakken zijn algemene vakken die iedere MBO student doorloopt. Het gaat hier om:","page":11},{"id":"bron-3-17","sourceId":"bron-3","title":"Generieke vakken","text":"In sommige gevallen krijgen studenten op basis van hun vooropleiding een vrijstelling. Dit moet je bespreken met je coach.","page":11},{"id":"bron-3-18","sourceId":"bron-3","title":"Generieke vakken","text":"Het is verstandig om in de eerste fase van de opleiding te werken aan de generieke vakken zodat dit niet ‘opstapelt’ aan het eind van de opleiding.","page":11},{"id":"bron-3-19","sourceId":"bron-3","title":"Generieke vakken","text":"Bij (mogelijke) problemen is extra hulp en begeleiding aan te vragen via het studentadviesbureau (SAB)","page":11},{"id":"bron-3-20","sourceId":"bron-3","title":"Zorgvakken","text":"Tijdens de opleiding krijg je een heel aantal vakken aangeboden die direct gerelateerd zijn aan de zorg. Voorbeelden hiervan zijn:","page":11},{"id":"bron-3-21","sourceId":"bron-3","title":"Zorgvakken","text":"Basiszorg (Wassen, aankleden, verplaatsingstechnieken etc.) • Begeleiden • Gezondheidsvoorlichting • Verpleegtechnische handelingen • Medisch rekenen • Schrijven van een zorgplan • Anatomie/fysiologie/pathologie (AFGP) • Branche vakken (AGZ, VVT, GGZ, GHZ) • Coördineren van zorg • Kwaliteitszorg","page":11},{"id":"bron-3-22","sourceId":"bron-3","title":"Opstarten van vakken","text":"Per periode bepalen de coaches samen met de studenten welke vakken er op het rooster komen. Er zijn ook vakken (LWP's) waar je in je eigen tijd, zelfstandig aan kan werken. Je coach zal dit met je bespreken.","page":12},{"id":"bron-3-23","sourceId":"bron-3","title":"Opstarten van vakken","text":"Wanneer je net bent gestart, haak je ergens in het studiejaar, aan het begin van een lesperiode in. Het rooster wat is afgesproken met de studenten die al langer in opleiding zijn is dan ook voor jou van toepassing.","page":12},{"id":"bron-3-24","sourceId":"bron-3","title":"Opstarten van vakken","text":"De vakken (LWP's) die jij gaat volgen zijn door je coach toegevoegd in het Individueel Leerplan (ILP) in het programma e-TO. De eerste LWP’ s waar je zelfstandig mee aan het werk kan worden door daar ook direct toegevoegd. Dit zijn de LWP's:","page":12},{"id":"bron-3-25","sourceId":"bron-3","title":"Opstarten van vakken","text":"Burgerschap: Van start tot examen • Mijn ik, mijn rol en mijn loopbaan • Opleidingsbeeld ‘leren leren bij Landstede’ • Beroepsbeeld ‘leren leren bij Landstede’","page":12},{"id":"bron-3-26","sourceId":"bron-3","title":"In e-TO ziet dat er bij jouw begin als volgt uit:","text":"Je ziet per vak 4 bolletjes staan. Bolletje 1 kleurt groen bij start van de periode. Binnen e- TO vul je een SMART geformuleerd leerdoel in. Zodra je dat hebt gedaan ga je automatisch door naar bolletje 2. Dit is de periode dat je het onderwijs volgt.","page":12},{"id":"bron-3-27","sourceId":"bron-3","title":"Afronden van vakken","text":"Ieder vak in elke periode krijgt een bepaalde afronding. Denk hierbij aan een kennistoets, een presentatie of het schrijven van een verslag. Dit wordt door de betreffende docent bepaald, meestal in afstemming met de groep. Deze afronding moet zijn voldaan/behaald om de periode af te ronden.","page":13},{"id":"bron-3-28","sourceId":"bron-3","title":"Afronden van vakken","text":"Daarnaast schrijf je aan het eind van de periode een afsluitende reflectie in e-TO. Als je dit hebt gedaan kleurt bolletje 3 groen. Vervolgens vraag je goedkeuring aan voor afronding van het vak bij de betreffende vakdocent. Bij bolletje 4 verschijnt dan een vraagteken.","page":13},{"id":"bron-3-29","sourceId":"bron-3","title":"Afronden van vakken","text":"Wanneer de vakdocent jouw reflectie goedkeurt en je de afgesproken afronding hebt behaald wordt bolletje 4 ook groen. Je hebt het vak dan behaald/afgesloten.","page":13},{"id":"bron-3-30","sourceId":"bron-3","title":"Fasen van de opleiding + Leerwerkprestaties (LWP’s)","text":"Landstede heeft de opleiding ingedeeld in 3 fases: Starter, gevorderd & beroepsbekwaam. Het kan per student verschillen hoelang het duurt deze verschillende fasen te doorlopen. De visie van Landstede is: ‘Talentvol ontwikkelen’. Alle studenten volgen hun eigen route in hun eigen tempo. Dat betekent ook dat niet iedereen met hetzelfde aan het werk is.","page":14},{"id":"bron-3-31","sourceId":"bron-3","title":"Fasen van de opleiding + Leerwerkprestaties (LWP’s)","text":"Maar uiteindelijk moet iedereen voldoen aan het kwalificatiedossier dat is vastgesteld door het ministerie van onderwijs. Uiteindelijk doorloopt iedere student dus dezelfde leerwerkprestaties (LWP’s) richting het afstuderen.","page":14},{"id":"bron-3-32","sourceId":"bron-3","title":"Starter fase","text":"Je begint met je opleiding, wordt ingewerkt, gaat je eerste lessen volgen en je begint aan de eerste opdrachten. Het volgende wordt van je verwacht:","page":14},{"id":"bron-3-33","sourceId":"bron-3","title":"Starter fase","text":"BPV-opdrachten: Op www.debpvwijzer.nl vind je een lijst met opdrachten voor starters waar je aan kunt werken. Je kiest 8 à 10 BPV opdrachten uit, hier ga je in je eerste jaar mee aan de slag. BPV-opdrachten helpen je in de voorbereiding op examens toe. Kies dus opdrachten waar je nog weinig vanaf weet. • LWP’s: Je gaat aan de slag met de LWP’s. Iedere LWP heeft een nummer. In ETO vind je een catalogus.","page":14},{"id":"bron-3-34","sourceId":"bron-3","title":"Starter fase","text":"Hier kan je de LWP opzoeken en bekijken welke doelen er in de LWP staan. De afronding verschilt per LWP. Bespreek met je coach hoe je de LWP afrondt. In de startersfase werk je aan onderstaande LWP’s. Sommige LWP’s zijn gemarkeerd met een kruisje. Deze zijn verplicht. De overige LWP’s zijn optioneel.","page":14},{"id":"bron-3-35","sourceId":"bron-3","title":"Periodes","text":"Start Basiszorg Je volgt praktijklessen, maakt de opdrachten en de E learnings. klen","page":14},{"id":"bron-3-36","sourceId":"bron-3","title":"Begeleiden Theorielessen","text":"Anatomie en fysiologie (AFGP, lint) Theorielessen AFGP + E learnings Expertcollege","page":14},{"id":"bron-3-37","sourceId":"bron-3","title":"Voorlichting Advies en Instructie (VAI) Theorielessen","text":"LLB Burgerschap: Van start tot examen (lint) 2 delen: Een verslag bij start van de opleiding (start) en een verslag aan het eind van de opleiding (mijlpaal).","page":14},{"id":"bron-3-38","sourceId":"bron-3","title":"Voorlichting Advies en Instructie (VAI) Theorielessen","text":"LOB mijn ik, mijn rol, mijn loopbaan 18204 x Opleidingsbeeld ‘leren leren bij Landstede’ Je werkt zelfstandig aan opdrachten. Hierdoor krijg","page":14},{"id":"bron-3-39","sourceId":"bron-3","title":"Voorlichting Advies en Instructie (VAI) Theorielessen","text":"je een goed beeld van de opleiding. Advies om dit snel na de start te doen. Beroepsbeeld werkt zelfstandig aan opdrachten. Hierdoor krijg je een goed beeld van de opleiding. Advies om dit snel na de start te doen.","page":15},{"id":"bron-3-40","sourceId":"bron-3","title":"Gevorderde fase","text":"Zodra je de startersfase gaat afronden, je bent dan een mooi eindje op weg, ga je werken aan de opdrachten die horen bij de gevorderde fase. Het volgende wordt van je verwacht:","page":15},{"id":"bron-3-41","sourceId":"bron-3","title":"Gevorderde fase","text":"BPV-opdrachten: Op www.debpvwijzer.nl vind je een lijst met opdrachten voor gevorderden waar je aan kunt werken. Je kiest 8 à 10 BPV opdrachten uit waar je mee aan de slag gaat. • LWP’s: Binnen de gevorderde fase ga je aan de slag met nieuwe/andere LWP’s. Zie onderstaand overzicht. Ook hier geldt: De LWP’s die gemarkeerd zijn met een kruisje zijn verplicht. De overige LWP’s optioneel.","page":15},{"id":"bron-3-42","sourceId":"bron-3","title":"Periodes","text":"Gevorderd VTH 1 t/m 3 Praktijklessen + de E learnings in Expertcollege","page":15},{"id":"bron-3-43","sourceId":"bron-3","title":"Handelen in onvoorziene situaties Praktijklessen + examens EHBO & reanimatie","text":"Medisch rekenen Zelfstandig oefenen met medisch rekenen, per onderdeel een apart examen","page":15},{"id":"bron-3-44","sourceId":"bron-3","title":"Methodisch werken gevorderden Theorielessen","text":"Kwaliteit en deskundigheid start Zelfstandig werken aan E learnings Expertcollege","page":15},{"id":"bron-3-45","sourceId":"bron-3","title":"Combi ger/chr zorgvrager Theorielessen","text":"Gehandicaptenzorg Zelfstandig 10 opdrachten uit de LWP uitwerken. Alternatief is een dag meelopen in het werkveld, als je dit zelf kunt regelen. Bespreek de voorwaarden hiervoor met je coach.","page":16},{"id":"bron-3-46","sourceId":"bron-3","title":"GGZ de start Theorielessen","text":"Kraamzorg Zelfstandig LWP uitwerken. Alternatief is een dag meelopen in het werkveld, als je dit zelf kunt regelen. Bespreek de voorwaarden hiervoor met je coach.","page":16},{"id":"bron-3-47","sourceId":"bron-3","title":"Kwetsbare ouderen Theorielessen","text":"Beroepsbekwame fase De laatste fase van je opleiding noemen we de beroepsbekwame fase. Binnen deze fase werk je in principe niet meer aan BPV-opdrachten, tenzij dit voor jou helpend is. Ook bij de beroepsbekwame fase horen een aantal LWP’s:","page":16},{"id":"bron-3-48","sourceId":"bron-3","title":"Zorgvrager in beeld Zelfstandig LWP uitwerken","text":"Werkbegeleiding Theorielessen. Je mag als vervanging van deze LWP ook de cursus werkbegeleiding volgen vanuit de zorggroep. Stem dit af met je coach.","page":16},{"id":"bron-3-49","sourceId":"bron-3","title":"Gehandicaptenzorg beroepsbekwaam 13719","text":"Overige LWP’s Er zijn nog een aantal LWP’s die naar keuze kunnen worden gemaakt of worden opgenomen in het lesrooster. Beroepsethiek is een LWP die we binnen de setting van Boerhaavehof dusdanig belangrijk vinden dat dit wordt ingeroosterd.","page":17},{"id":"bron-3-50","sourceId":"bron-3","title":"Feedbackformulieren","text":"Je bent in opleiding dus het is belangrijk niet ‘zomaar je dienst te komen werken’. Voor aanvang van een dienst geef je een leerdoel voor die dag aan. Na afloop bespreek je hoe het gegaan is en vraag je om feedback. Minimaal 2x per week laat je door je collega/begeleider een feedbackformulier invullen. Deze plaats je vervolgens in Teams (zorggroep-Boerhaavehof).","page":17},{"id":"bron-3-51","sourceId":"bron-3","title":"BPV meter","text":"De BPV meter heeft als doel jouw ontwikkeling en voortgang in beeld te brengen. 2 keer per jaar vullen zowel jij als je begeleider(s) onafhankelijk van elkaar een BPV meter in. Jij beoordeeld dus jezelf en je begeleiders beoordelen jou. Vervolgens ga je samen in gesprek. Je vergelijkt de BPV meters met elkaar en bespreekt de verschillen. Samen kom je tot een definitieve beoordeling. Op www.debpvwijzer.nl vind je de BPV meter, uitleg en een handige onderlegger.","page":18},{"id":"bron-3-52","sourceId":"bron-3","title":"BPV opdrachten","text":"Op www.debpvwijzer.nl vind je BPV opdrachten. Dit zijn opdrachten die je kunt uitwerken ter voorbereiding op je examens. Advies is om gedurende je opleiding +- 18 opdrachten uit te werken, je zult werken dat je dit houvast geeft in je leerontwikkeling. Je bent zelf vrij om opdrachten te kiezen waarvan jij denkt dat ze van toegevoegde waarde zijn voor jouw leerproces. Je kunt hierin ook overleggen met je praktijkleercoach.","page":18},{"id":"bron-3-53","sourceId":"bron-3","title":"BPV opdrachten","text":"Je BPV opdrachten laat je beoordelen door je werkbegeleider binnen Boerhaavehof.","page":18},{"id":"bron-3-54","sourceId":"bron-3","title":"Voortgangsgesprek","text":"Iedere 3 weken evalueer je met je werkbegeleider(s) jouw voortgang. Punten die besproken zijn:","page":19},{"id":"bron-3-55","sourceId":"bron-3","title":"Voortgangsgesprek","text":"Hoe gaat het met je? Loop je ergens tegenaan? • Waar sta je in je leerproces? • Wat zijn je doelen voor de komende 3 weken? Naar welk examen werk je toe? • Hoe gaat het met het verzamelen van feedback en het plaatsen in de leeromgeving?","page":19},{"id":"bron-3-56","sourceId":"bron-3","title":"Actie werkbegeleider:","text":"Bij missend initiatief de student aanspreken. • Verslag van de student binnen 1 week beoordelen en Go/No Go geven binnen de chatpagina.","page":19},{"id":"bron-3-57","sourceId":"bron-3","title":"BPV-gesprek","text":"In het BPV-gesprek bespreek je jouw voortgang in studie en praktijk. Aan de hand van je POP & PAP wordt gekeken naar je functioneren op de werkvloer en je studievoortgang. Ook de BPV meter kan hierbij worden ingevuld, al loopt dit niet altijd synchroon met de BPV gesprekken.","page":20},{"id":"bron-3-58","sourceId":"bron-3","title":"BPV-gesprek","text":"Aanwezig: Student, praktijkleercoach (Everlien), coach (Hennie/Henri) en minimaal één van je werkbegeleiders (of een vervanger) Student, werkbegeleider(s)","page":20},{"id":"bron-3-59","sourceId":"bron-3","title":"Actie werkbegeleider:","text":"Indien nodig de BPV meter invullen • Aanwezig zijn bij het BPV-gesprek","page":20},{"id":"bron-3-60","sourceId":"bron-3","title":"Ieder schooljaar voer je 4 gesprekken (dus iedere leerperiode 1 gesprek):","text":"Lwp’s: Start: Gevorderd: Beroeps bekwaam: Medisch rekenen (17296) VTH 1 (16062) VTH 2 (16095)","page":28},{"id":"bron-3-61","sourceId":"bron-3","title":"Ieder schooljaar voer je 4 gesprekken (dus iedere leerperiode 1 gesprek):","text":"Handelen in onvoorziene situaties VIG (16342) VTH 3 (16100) BPV-opdrachten: Zie overzicht www.debpvwijzer.nl","page":28},{"id":"bron-3-62","sourceId":"bron-3","title":"Reageert op onvoorziene en crisissituaties","text":"Lwp’s: Start: Gevorderd: Beroeps bekwaam: Basiszorg (16849) Anatomie & fysiologie (13436)","page":28},{"id":"bron-3-63","sourceId":"bron-3","title":"Reageert op onvoorziene en crisissituaties","text":"GHZ de start (13852) (verplicht) GGZ de start (17453) (verplicht) Kraamzorg (17356) (verplicht) De (psycho)geriatrische ZV (10954) De chronische ZV (17448) Combinatie chronische/PG ZV (17449) Revaliderende zorgvrager (16809) Palliatieve zorg (14311) Kwetsbare ouderen (10155)","page":28},{"id":"bron-3-64","sourceId":"bron-3","title":"Reageert op onvoorziene en crisissituaties","text":"Examen prof. ontwikkeling & kwaliteitszorg K1 W 1,3 Kerntaak Werkprocessen","page":28},{"id":"bron-3-65","sourceId":"bron-3","title":"Reageert op onvoorziene en crisissituaties","text":"Zorgt voor professionele ontwikkeling (reflectieve EBP-professional) • Draagt bij aan goede kwaliteit van zorg (Professional en kwaliteitsverbeteraar) Lwp’s: Start: Gevorderd: Beroeps bekwaam: Kwaliteitszorg en deskundigheid e-learning (15227) Werkbegeleiding (16349) Intervisie (17451) Ethiek (18104)","page":28},{"id":"bron-3-66","sourceId":"bron-3","title":"Reageert op onvoorziene en crisissituaties","text":"Kwaliteit en deskundigheid (12078) CGI (15212) GHZ beroeps bekwaam (13719)","page":28},{"id":"bron-4-1","sourceId":"bron-4","title":"Start met de opleiding","text":"Je begint met een opleiding en dan komt er veel op je af. Je krijgt de tijd om hier rustig je weg in te vinden. Om je wat houvast te geven hierbij een checklist voor je eerste dagen/weken van je opleiding:","page":4},{"id":"bron-4-2","sourceId":"bron-4","title":"Voorbereiding eerste lesdag","text":"De laptop is cruciaal om aan je opdrachten te kunnen werken, mee te doen met het onderwijs en gebruik te maken van alle digitale systemen. Voorafgaand aan de start van je opleiding krijg je een brief met tips en informatie over de aanschaf van een laptop. • Check je inloggegevens. Je gaat werken met verschillende systemen en daarbij","page":4},{"id":"bron-4-3","sourceId":"bron-4","title":"Voorbereiding eerste lesdag","text":"moet je inloggen. De inloggegevens ontvang je voorafgaand aan je opleiding via de mail thuisgestuurd. Kijk er vast naar of neem ze mee op je eerste lesdag. • Zorg dat je een digitale foto beschikbaar hebt voor in het schoolsysteem en op de","page":4},{"id":"bron-4-4","sourceId":"bron-4","title":"Eerste lesdag/week","text":"Je sluit s ‘ochtends om 09.00 uur aan bij de groep. Je draait mee in de eerste les.","page":4},{"id":"bron-4-5","sourceId":"bron-4","title":"Eerste lesdag/week","text":"Je hoeft je hierop niet voor te bereiden • In het tweede blok staat een coach uur gepland. Hierin wordt tijd gereserveerd","page":4},{"id":"bron-4-6","sourceId":"bron-4","title":"Eerste lesdag/week","text":"waarin je door een van de docenten uitleg krijgt over: - Inloggen in de digitale systemen (Eduarte, ETO, Connect) - Uploaden van een foto & aanvragen studentenpas (Eenmaal ingelogd mag je jouw foto uploaden via het studentendashboard op Connect en een studentenpas aanvragen).","page":4},{"id":"bron-4-7","sourceId":"bron-4","title":"Eerste lesdag/week","text":"Die krijg je dan volgende week binnen, via je coach. - Boeken bestellen (Je gaat boeken bestellen via www.mbowebshop.nl De docent geeft aan welke boeken je kunt bestellen) - Je studiemaatje (Je wordt tijdens je opleiding gekoppeld aan een medestudent die als maatje fungeert. Gebruik je maatje om uitleg te vragen over de opleiding, de systemen etc.) - Invullen derdenmachtiging schoolgeld - Procedure ziekmelden","page":4},{"id":"bron-4-8","sourceId":"bron-4","title":"In het coach uur krijg je uitleg over:","text":"ILP (Individueel leerplan) - Evt. Vrijstellingen - Werken met de digitale systemen (Eduarte, ETO, Connect, Teams) door je maatje","page":5},{"id":"bron-4-9","sourceId":"bron-4","title":"Vakken","text":"Je volgt tijdens je opleiding verschillende vakken. Het gaat om ''generieke vakken'' en ''zorg vakken''.","page":9},{"id":"bron-4-10","sourceId":"bron-4","title":"Generieke vakken","text":"Generieke vakken zijn algemene vakken die iedere MBO student doorloopt. Het gaat hier om:","page":9},{"id":"bron-4-11","sourceId":"bron-4","title":"Generieke vakken","text":"In sommige gevallen krijgen studenten op basis van hun vooropleiding een vrijstelling. Dit moet je bespreken met je coach.","page":9},{"id":"bron-4-12","sourceId":"bron-4","title":"Generieke vakken","text":"Het is verstandig om in de eerste fase van de opleiding te werken aan de generieke vakken zodat dit niet ‘opstapelt’ aan het eind van de opleiding.","page":9},{"id":"bron-4-13","sourceId":"bron-4","title":"Generieke vakken","text":"Bij (mogelijke) problemen is extra hulp en begeleiding aan te vragen via het studentadviesbureau (SAB)","page":9},{"id":"bron-4-14","sourceId":"bron-4","title":"Zorgvakken","text":"Tijdens de opleiding krijg je een heel aantal vakken aangeboden die direct gerelateerd zijn aan de zorg. Voorbeelden hiervan zijn:","page":9},{"id":"bron-4-15","sourceId":"bron-4","title":"Zorgvakken","text":"Basiszorg (Wassen, aankleden, verplaatsingstechnieken etc.) • Begeleiden • Gezondheidsvoorlichting • Verpleegtechnische handelingen • Medisch rekenen • Schrijven van een zorgplan • Anatomie/fysiologie/pathologie (AFGP) • Branche vakken (AGZ, VVT, GGZ, GHZ) • Coördineren van zorg • Kwaliteitszorg","page":9},{"id":"bron-4-16","sourceId":"bron-4","title":"Opstarten van vakken","text":"Per periode bepalen de coaches samen met de studenten welke vakken er op het rooster komen. Er zijn ook vakken (LWP's) waar je in je eigen tijd, zelfstandig aan kan werken. Je coach zal dit met je bespreken.","page":10},{"id":"bron-4-17","sourceId":"bron-4","title":"Opstarten van vakken","text":"Wanneer je net bent gestart, haak je ergens in het studiejaar, aan het begin van een lesperiode in. Het rooster wat is afgesproken met de studenten die al langer in opleiding zijn is dan ook voor jou van toepassing.","page":10},{"id":"bron-4-18","sourceId":"bron-4","title":"Opstarten van vakken","text":"De vakken (LWP's) die jij gaat volgen zijn door je coach toegevoegd in het Individueel Leerplan (ILP) in het programma e-TO. De eerste LWP’ s waar je zelfstandig mee aan het werk kan worden door daar ook direct toegevoegd. Dit zijn de LWP's:","page":10},{"id":"bron-4-19","sourceId":"bron-4","title":"Opstarten van vakken","text":"Burgerschap: Van start tot examen • Mijn ik, mijn rol en mijn loopbaan • Opleidingsbeeld ‘leren leren bij Landstede’ • Beroepsbeeld ‘leren leren bij Landstede’","page":10},{"id":"bron-4-20","sourceId":"bron-4","title":"In e-TO ziet dat er bij jouw begin als volgt uit:","text":"Je ziet per vak 4 bolletjes staan. Bolletje 1 kleurt groen bij start van de periode. Binnen e- TO vul je een SMART geformuleerd leerdoel in. Zodra je dat hebt gedaan ga je automatisch door naar bolletje 2. Dit is de periode dat je het onderwijs volgt.","page":10},{"id":"bron-4-21","sourceId":"bron-4","title":"Afronden van vakken","text":"Ieder vak in elke periode krijgt een bepaalde afronding. Denk hierbij aan een kennistoets, een presentatie of het schrijven van een verslag. Dit wordt door de betreffende docent bepaald, meestal in afstemming met de groep. Deze afronding moet zijn voldaan/behaald om de periode af te ronden.","page":11},{"id":"bron-4-22","sourceId":"bron-4","title":"Afronden van vakken","text":"Daarnaast schrijf je aan het eind van de periode een afsluitende reflectie in e-TO. Als je dit hebt gedaan kleurt bolletje 3 groen. Vervolgens vraag je goedkeuring aan voor afronding van het vak bij de betreffende vakdocent. Bij bolletje 4 verschijnt dan een vraagteken.","page":11},{"id":"bron-4-23","sourceId":"bron-4","title":"Afronden van vakken","text":"Wanneer de vakdocent jouw reflectie goedkeurt en je de afgesproken afronding hebt behaald wordt bolletje 4 ook groen. Je hebt het vak dan behaald/afgesloten.","page":11},{"id":"bron-4-24","sourceId":"bron-4","title":"Fasen van de opleiding + Leerwerkprestaties (LWP’s)","text":"Landstede heeft de opleiding ingedeeld in 3 fases: Starter, gevorderd & beroepsbekwaam. Het kan per student verschillen hoelang het duurt deze verschillende fasen te doorlopen. De visie van Landstede is: ‘Talentvol ontwikkelen’. Alle studenten volgen hun eigen route in hun eigen tempo. Dat betekent ook dat niet iedereen met hetzelfde aan het werk is.","page":12},{"id":"bron-4-25","sourceId":"bron-4","title":"Fasen van de opleiding + Leerwerkprestaties (LWP’s)","text":"Maar uiteindelijk moet iedereen voldoen aan het kwalificatiedossier dat is vastgesteld door het ministerie van onderwijs. Uiteindelijk doorloopt iedere student dus dezelfde leerwerkprestaties (LWP’s) richting het afstuderen.","page":12},{"id":"bron-4-26","sourceId":"bron-4","title":"Starter fase","text":"Je begint met je opleiding, wordt ingewerkt, gaat je eerste lessen volgen en je begint aan de eerste opdrachten. Het volgende wordt van je verwacht:","page":12},{"id":"bron-4-27","sourceId":"bron-4","title":"Starter fase","text":"BPV-opdrachten: Op www.debpvwijzer.nl vind je een lijst met opdrachten voor starters waar je aan kunt werken. Je kiest 8 à 10 BPV opdrachten uit, hier ga je in je eerste jaar mee aan de slag. BPV-opdrachten helpen je in de voorbereiding op examens toe. Kies dus opdrachten waar je nog weinig vanaf weet. • LWP’s: Je gaat aan de slag met de LWP’s. Iedere LWP heeft een nummer. In ETO vind je een catalogus.","page":12},{"id":"bron-4-28","sourceId":"bron-4","title":"Starter fase","text":"Hier kan je de LWP opzoeken en bekijken welke doelen er in de LWP staan. De afronding verschilt per LWP. Bespreek met je coach hoe je de LWP afrondt. In de startersfase werk je aan onderstaande LWP’s. Sommige LWP’s zijn gemarkeerd met een kruisje. Deze zijn verplicht. De overige LWP’s zijn optioneel.","page":12},{"id":"bron-4-29","sourceId":"bron-4","title":"Periodes","text":"Basiszorg Je volgt praktijklessen, maakt de opdrachten en de E learnings.","page":12},{"id":"bron-4-30","sourceId":"bron-4","title":"Begeleiden Theorielessen","text":"Anatomie en fysiologie (AFGP, lint) Theorielessen AFGP + E learnings Expertcollege","page":12},{"id":"bron-4-31","sourceId":"bron-4","title":"Voorlichting Advies en Instructie (VAI) Theorielessen","text":"LLB Burgerschap: Van start tot examen (lint) 2 delen: Een verslag bij start van de opleiding (start)","page":12},{"id":"bron-4-32","sourceId":"bron-4","title":"Voorlichting Advies en Instructie (VAI) Theorielessen","text":"en een verslag aan het eind van de opleiding (mijlpaal). LOB mijn ik, mijn rol, mijn loopbaan 18204 Ja Opleidingsbeeld ‘leren leren bij Landstede’ Je werkt zelfstandig aan opdrachten. Hierdoor krijg je een goed beeld van de opleiding. Advies om dit snel na de start te doen.","page":13},{"id":"bron-4-33","sourceId":"bron-4","title":"Voorlichting Advies en Instructie (VAI) Theorielessen","text":"Beroepsbeeld werkt zelfstandig aan opdrachten. Hierdoor krijg je een goed beeld van de opleiding. Advies om dit snel na de start te doen.","page":13},{"id":"bron-4-34","sourceId":"bron-4","title":"Gevorderde fase","text":"Zodra je de startersfase gaat afronden, je bent dan een mooi eindje op weg, ga je werken aan de opdrachten die horen bij de gevorderde fase. Het volgende wordt van je verwacht:","page":13},{"id":"bron-4-35","sourceId":"bron-4","title":"Gevorderde fase","text":"BPV-opdrachten: Op www.debpvwijzer.nl vind je een lijst met opdrachten voor gevorderden waar je aan kunt werken. Je kiest 8 à 10 BPV opdrachten uit waar je mee aan de slag gaat. • LWP’s: Binnen de gevorderde fase ga je aan de slag met nieuwe/andere LWP’s. Zie onderstaand overzicht. Ook hier geldt: De LWP’s die gemarkeerd zijn met een kruisje zijn verplicht. De overige LWP’s optioneel.","page":13},{"id":"bron-4-36","sourceId":"bron-4","title":"Handelen in onvoorziene situaties Praktijklessen + examens EHBO & reanimatie","text":"Medisch rekenen Zelfstandig oefenen met medisch rekenen, per onderdeel een apart examen","page":13},{"id":"bron-4-37","sourceId":"bron-4","title":"Methodisch werken gevorderden Theorielessen","text":"Kwaliteit en deskundigheid start Zelfstandig werken aan E learnings Expertcollege","page":13},{"id":"bron-4-38","sourceId":"bron-4","title":"Combi geriatrie/chronische zorgvrager Theorielessen","text":"Gehandicaptenzorg Zelfstandig 10 opdrachten uit de LWP uitwerken. Alternatief is een dag meelopen in het werkveld, als je dit zelf kunt regelen. Bespreek de voorwaarden hiervoor met je coach.","page":14},{"id":"bron-4-39","sourceId":"bron-4","title":"GGZ de start Theorielessen","text":"Kraamzorg Zelfstandig LWP uitwerken. Alternatief is een dag meelopen in het werkveld, als je dit zelf kunt regelen. Bespreek de voorwaarden hiervoor met je coach.","page":14},{"id":"bron-4-40","sourceId":"bron-4","title":"Kwetsbare ouderen Theorielessen","text":"Klinisch redeneren Theorielessen. Afhankelijk van de roosters kunnen verschillende thema's worden aangeboden. Je volgt er minimaal 2: - Maag/darm/uro - Bewegingstelsel/huid - Hart/long - Centraal zenuwstelsel - Oncologie - Immuno/hormonen - Pathologie verdieping","page":14},{"id":"bron-4-41","sourceId":"bron-4","title":"Kwetsbare ouderen Theorielessen","text":"Verdiepend Theorielessen over verschillende thema's. In samenspraak met de docent worden 2 thema's gekozen: - Therapeutisch milieu - Verslaving - Somatiek in GGZ - Omgaan met psychische zorgvrager","page":14},{"id":"bron-4-42","sourceId":"bron-4","title":"Kwetsbare ouderen Theorielessen","text":"Beroepsbekwame fase De laatste fase van je opleiding noemen we de beroepsbekwame fase. Binnen deze fase werk je in principe niet meer aan BPV-opdrachten, tenzij dit voor jou helpend is. Ook bij de beroepsbekwame fase horen een aantal LWP’s:","page":15},{"id":"bron-4-43","sourceId":"bron-4","title":"Periodes","text":"Werkbegeleiding Theorielessen. Je mag als vervanging van deze LWP ook de cursus werkbegeleiding volgen vanuit de zorggroep. Stem dit af met je coach.","page":15},{"id":"bron-4-44","sourceId":"bron-4","title":"CGI Theorielessen","text":"Overige LWP’s Er zijn nog een aantal LWP’s die naar keuze kunnen worden gemaakt of worden opgenomen in het lesrooster. Beroepsethiek is een LWP die we binnen de setting van Boerhaavehof dusdanig belangrijk vinden dat dit wordt ingeroosterd.","page":15},{"id":"bron-4-45","sourceId":"bron-4","title":"Feedbackformulieren","text":"Je bent in opleiding dus het is belangrijk niet ‘zomaar je dienst te komen werken’. Voor aanvang van een dienst geef je een leerdoel voor die dag aan. Na afloop bespreek je hoe het gegaan is en vraag je om feedback. Minimaal 2x per week laat je door je collega/begeleider een feedbackformulier invullen. Deze plaats je vervolgens in Teams (zorggroep-Boerhaave hof).","page":16},{"id":"bron-4-46","sourceId":"bron-4","title":"BPV meter","text":"De BPV meter heeft als doel jouw ontwikkeling en voortgang in beeld te brengen. 2 keer per jaar vullen zowel jij als je begeleider(s) onafhankelijk van elkaar een BPV meter in. Jij beoordeeld dus jezelf en je begeleiders beoordelen jou. Vervolgens ga je samen in gesprek. Je vergelijkt de BPV meters met elkaar en bespreekt de verschillen. Samen kom je tot een definitieve beoordeling. Op www.debpvwijzer.nl vind je de BPV meter, uitleg en een handige onderlegger.","page":16},{"id":"bron-4-47","sourceId":"bron-4","title":"BPV opdrachten","text":"Op www.debpvwijzer.nl vind je BPV opdrachten. Dit zijn opdrachten die je kunt uitwerken ter voorbereiding op je examens. Advies is om gedurende je opleiding +- 18 opdrachten uit te werken, je zult werken dat je dit houvast geeft in je leerontwikkeling. Je bent zelf vrij om opdrachten te kiezen waarvan jij denkt dat ze van toegevoegde waarde zijn voor jouw leerproces. Je kunt hierin ook overleggen met je praktijkleercoach.","page":16},{"id":"bron-4-48","sourceId":"bron-4","title":"BPV opdrachten","text":"Je BPV opdrachten laat je beoordelen door je werkbegeleider binnen Boerhaavehof.","page":16},{"id":"bron-4-49","sourceId":"bron-4","title":"Gesprekken","text":"Binnen je opleiding voer je regelmatig gesprekken om jouw voortgang te bespreken. In dit hoofdstuk vind je een overzicht van de gesprekken en wat er per gesprek gevraagd wordt qua voorbereiding en evt. ter verwerking.","page":17},{"id":"bron-4-50","sourceId":"bron-4","title":"Voortgangsgesprek","text":"Iedere 3 weken evalueer je met je werkbegeleider(s) jouw voortgang. Punten die besproken zijn:","page":17},{"id":"bron-4-51","sourceId":"bron-4","title":"Voortgangsgesprek","text":"Hoe gaat het met je? Loop je ergens tegenaan? • Waar sta je in je leerproces? • Wat zijn je doelen voor de komende 3 weken? Naar welk examen werk je toe? • Hoe gaat het met het verzamelen van feedback en het plaatsen in de leeromgeving?","page":17},{"id":"bron-4-52","sourceId":"bron-4","title":"Actie werkbegeleider:","text":"Bij missend initiatief de student aanspreken. • Verslag van de student binnen 1 week beoordelen en Go/No Go geven binnen de chatpagina.","page":17},{"id":"bron-4-53","sourceId":"bron-4","title":"BPV-gesprek","text":"In het BPV-gesprek bespreek je jouw voortgang in studie en praktijk. Aan de hand van je POP & PAP wordt gekeken naar je functioneren op de werkvloer en je studievoortgang. Ook de BPV meter kan hierbij worden ingevuld, al loopt dit niet altijd synchroon met de BPV gesprekken.","page":18},{"id":"bron-4-54","sourceId":"bron-4","title":"BPV-gesprek","text":"Aanwezig: Student, praktijkleercoach (Everlien), coach (Hennie/Henri) en minimaal één van je werkbegeleiders (of een vervanger) Student, werkbegeleider(s)","page":18},{"id":"bron-4-55","sourceId":"bron-4","title":"Actie werkbegeleider:","text":"Indien nodig de BPV meter invullen • Aanwezig zijn bij het BPV-gesprek","page":18},{"id":"bron-4-56","sourceId":"bron-4","title":"Leermetergesprek","text":"In het leermetergesprek bespreek je samen met je coach jouw voortgang a.d.h.v. de leermeter in ETO. Je geeft aan bij je coach waar jij denkt dat de leermeter opgeschoven kan worden en ondersteund dat met argumenten/bewijs. Aanwezig: Student & coach (Hennie/Henri)","page":18},{"id":"bron-4-57","sourceId":"bron-4","title":"Gaandeweg de opleiding rond je verschillende examens af:","text":"Rekenen, Engels, Nederlands • Werk in uitvoering • Zorg op maat • Communicatie en preventie • Afstemmen en samenwerken (2e voorlaatste examen) • Reageren in onvoorziene situatie(s) (Voorlaatste examen) • Professionele ontwikkeling en kwaliteit (Laatste examen)","page":19},{"id":"bron-4-58","sourceId":"bron-4","title":"Gaandeweg de opleiding rond je verschillende examens af:","text":"Je ziet dat de examens in een bepaalde volgorde zijn geplaatst. Dit is de meest logische volgorde om de examens af te nemen tijdens je opleiding. In de praktijk zal je als eerst aan het werk gaan met ‘werk in uitvoering'. Je coach zal je hier tijdens je opleiding verder in sturen.","page":19},{"id":"bron-4-59","sourceId":"bron-4","title":"Gaandeweg de opleiding rond je verschillende examens af:","text":"Om een examen te mogen examineren heb je toestemming van je werkbegeleider en je coach nodig. Dit kan je formeel vastleggen via een toestemmingsformulier. Verder moet je de bijbehorende theorie hebben afgerond.","page":19},{"id":"bron-4-60","sourceId":"bron-4","title":"Elektronisch Portfolio Prove2Move (EPP)","text":"Je krijgt bij de start van je opleiding toegang tot een ''digitale examenmap''. Dit is het EPP. Je coach zorgt ervoor dat je wordt aangemeld in het EPP. Je krijgt via de mail een link waarin je vervolgens kan inloggen in het EPP.","page":19},{"id":"bron-4-61","sourceId":"bron-4","title":"Elektronisch Portfolio Prove2Move (EPP)","text":"Zodra je eraan toe bent een examen te gaan afleggen en je aan de voorwaarden voldoet (toestemmingsformulier), meld je dit bij je coach. Die plaatst het betreffende examen van in het EPP. De examinator vult dan de beoordeling digitaal in.","page":19},{"id":"bron-4-62","sourceId":"bron-4","title":"Elektronisch Portfolio Prove2Move (EPP)","text":"Per examen wat in het EPP wordt geplaatst worden kosten in rekening gebracht aan de school. Dat is de reden dat niet direct alle examens op voorhand al in de EPP worden geplaatst.","page":19},{"id":"bron-4-63","sourceId":"bron-4","title":"Elektronisch Portfolio Prove2Move (EPP)","text":"Binnen het EPP vind je duidelijke handleidingen voor het gebruik. Advies is om deze even te bekijken aan het begin van je opleiding.","page":19},{"id":"bron-4-64","sourceId":"bron-4","title":"Koppeling LWP's en examens","text":"Onderstaand een overzicht van de koppeling tussen de verschillende LWP’s en de examens.","page":20},{"id":"bron-4-65","sourceId":"bron-4","title":"Veel gestelde vragen","text":"Waar vind ik alle informatie over BPV (opdrachten, gesprekken, BPV meter etc.?) Op www.debpvwijzer.nl • Ik heb binnenkort een BPV-gesprek. Moet dat moment ook de BPV meter zijn ingevuld? Dat kan, maar hoeft niet persé. De BPV meter moet 2x per jaar worden ingevuld maar staat in principe los van het BPV gesprek. Als het wel ongeveer gelijk loopt is dat mooi meegenomen. • Hoe schrijf ik je in voor een BPV-gesprek of leermeter gesprek?","page":22},{"id":"bron-4-66","sourceId":"bron-4","title":"Veel gestelde vragen","text":"Het rooster in Teams bevat een tabel waar je kan inschrijven op een datum. • Ik wil een BPV-gesprek plannen maar het lukt echt niet om dit te plannen met mijn werkbegeleiders. Regel i.o. met je werkbegeleiders een vervangende die hen kan vervangen in het gesprek. Het is handig dat dit een collega is waar je ook regelmatig mee hebt gewerkt.","page":22},{"id":"bron-5-1","sourceId":"bron-5","title":"Reglement","text":"Begrip Toelichting Artikel In het examenreglement wordt soms verwezen naar een ‘artikel’, hiermee wordt het nummer van een kopje bedoeld. Beoordelaar Degene die het examen beoordeelt. Wordt in de WEB examinator genoemd.","page":5},{"id":"bron-5-2","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"Examens die specifiek voor jouw opleiding gelden en vallen onder de kerntaken van je opleiding. Worden in het EKB WEB specifieke examens genoemd. Centrale examens Landelijke examens die elke mbo-student moet maken, en voor iedereen hetzelfde zijn. Het gaat om de examens Nederlands (lezen en luisteren), rekenen en Engels (lezen en luisteren, alleen niveau 4). Commissie van Beroep voor de Examens","page":5},{"id":"bron-5-3","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"De onafhankelijke beroepscommissie van Landstede MBO zoals bedoeld in artikel 7.5.1. van de WEB. Deze commissie oordeelt over het beroep tegen een beslissing van de beoordelaar of examencommissie.","page":5},{"id":"bron-5-4","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"Examenbureau Op iedere school is een examenbureau dat zorgt voor de planning, afname en verwerking van examens. Examencommissie Dit is de examencommissie van Landstede MBO zoals bedoeld in artikel 7.4.5. van de WEB.","page":5},{"id":"bron-5-5","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"Examenplan Plan waarin, per opleiding, alle examens staan die je moet afleggen om je diploma te behalen. Deze staat in e-TO (kluis). Examenreglement Dit examenreglement.","page":5},{"id":"bron-5-6","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"Examenstudent Iemand die geen onderwijs volgt maar wel examen doet (tegen betaling per examen) bij Landstede MBO. Generieke examens De examens voor de onderdelen Nederlands, rekenen, Engels (alleen niveau 4) en Loopbaan & Burgerschap. Instellingsexamens Examens voor Nederlands en Engels (alleen niveau 4) die door de school zijn bepaald. Het gaat om de onderdelen schrijven, spreken en gesprekken voeren.","page":5},{"id":"bron-5-7","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"Landstede Groep Onderwijsinstelling met scholen zowel in het voortgezet onderwijs als in het middelbaar beroepsonderwijs.","page":5},{"id":"bron-5-8","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"Landstede MBO Middelbaar beroepsonderwijs van Landstede Groep dat wordt aangeboden door Landstede MBO en mbo Menso Alting.","page":5},{"id":"bron-5-9","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"Opleiding Middelbaar beroepsonderwijs ('mbo') als bedoeld in artikel 7.2.2. van de WEB. Praktijkexamen Examen in de beroepspraktijk of door middel van simulatie. Wordt ook wel proeve van bekwaamheid genoemd.","page":5},{"id":"bron-5-10","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"Proces-verbaal Een verslag door of namens Landstede MBO waarin de feiten van een situatie beschreven worden. SAB De afdeling Student, Advies en Begeleiding.","page":5},{"id":"bron-5-11","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"Startkwalificatie Dit is een diploma havo, vwo, mbo niveau 2 of hoger. Dit is volgens de overheid het minimale onderwijsniveau dat nodig is om kans te maken op duurzaam werk. Student Iemand die een opleiding volgt bij Landstede MBO.","page":6},{"id":"bron-5-12","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"Vrijstelling Wanneer je van de examencommissie een examen(onderdeel) niet hoeft te maken omdat je al eerder een daarmee gelijkwaardig resultaat hebt behaald.","page":6},{"id":"bron-5-13","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"Zak-/slaagregeling Eisen waaraan je moet voldoen om je mbo-diploma te behalen (zichtbaar in e-TO).","page":6},{"id":"bron-5-14","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"1. Het examenreglement is een overzicht van alle regels die gelden voor de","page":6},{"id":"bron-5-15","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"organisatie en de beoordeling van de examenonderdelen. 2. Het examenreglement is van toepassing voor alle opleidingen van Landstede MBO en","page":6},{"id":"bron-5-16","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"gaat in met ingang van 1 augustus 2025. 3. Het examenreglement is een uitwerking van de examenbepalingen van de Wet Educatie","page":6},{"id":"bron-5-17","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"en Beroepsonderwijs (\"WEB\") en het Examen- en Kwalificatiebesluit WEB (\"EKB\"). Wil je de volledige teksten zien? Kijk dan op www.wetten.overheid.nl.","page":6},{"id":"bron-5-18","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"1.3. Deelnemen aan examens 1. Heb je een inschrijvingsbewijs van Landstede Groep en volg je een opleiding bij Landstede MBO? Dan mag je aan de examens van die opleiding deelnemen. 2. Bij Landstede MBO bepaal je samen met je coach of vakdocent het moment waarop je deelneemt aan examens. Dan weet je ook dat je eraan toe bent, en de meeste kans maakt om een goed resultaat te halen.","page":6},{"id":"bron-5-19","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"1.4. Inschrijving als examenstudent 1. Als je na afloop van je onderwijsovereenkomst of inschrijving als student er niet in geslaagd bent om alle examens te behalen, kun je je inschrijven als examenstudent. Je volgt dan geen onderwijs meer. In plaats van schoolgeld betaal je inschrijfgeld als examenstudent en een bedrag per examen. 2. Je kunt maximaal twee jaar ingeschreven staan als examenstudent. 3.","page":6},{"id":"bron-5-20","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"Als je besluit om geen examenstudent te worden, heb je twee jaar de tijd om terug te komen op dit besluit en kun je alsnog ingeschreven worden als examenstudent.","page":6},{"id":"bron-5-21","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"Bij enkele opleidingen moet je ook examens maken die door de branche verplicht zijn gesteld om daar te mogen werken. Deze heten ‘wettelijke beroepsvereisten‘. Alleen als deze wettelijke beroepsvereisten zijn opgenomen in jouw examenplan, is dit examenreglement van toepassing op deze examens.","page":6},{"id":"bron-5-22","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"1. Landstede MBO heeft drie onafhankelijke examencommissies. Deze commissies zien","page":7},{"id":"bron-5-23","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"erop toe dat alles rond de examens goed verloopt. 2. De examencommissie besluit of een (examen)student aan alle formele voorwaarden heeft","page":7},{"id":"bron-5-24","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"voldaan voor het verstrekken van een mbo-diploma, mbo-certificaat of mbo-verklaring. 3. De examencommissie verstrekt mbo-diploma’s, mbo-certificaten en mbo-verklaringen. 4. Ook neemt de examencommissie besluiten over aanvragen voor vrijstellingen en","page":7},{"id":"bron-5-25","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"examenfaciliteiten en behandelt ze klachten van studenten. 5. Heb je een vraag voor de examencommissie? Dan","page":7},{"id":"bron-5-26","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"1. De Onderwijsinspectie houdt toezicht op de examinering binnen Landstede MBO. Elke","page":7},{"id":"bron-5-27","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"vier jaar wordt een aantal opleidingen onderzocht. De uitkomsten van onderzoeken worden gepubliceerd op de website van de Onderwijsinspectie.","page":7},{"id":"bron-5-28","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"1. Denk jij dat je recht hebt op vrijstelling voor een examen? Dan vraag je dat samen met je","page":7},{"id":"bron-5-29","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"coach aan bij de examencommissie van jouw opleiding. 2. Je stuurt bewijzen mee van eerder behaalde resultaten. Deze bewijzen zijn bijvoorbeeld:","page":7},{"id":"bron-5-30","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"kopieën van je diploma’s, certificaten, een instellingsverklaring/mbo-verklaring van je vorige opleiding en cijferlijsten of een DUO-verklaring. Een Duo-verklaring wordt door de examencommissie alleen geaccepteerd bij vermissing van je diploma of certificaat. 3. Als de examencommissie vrijstelling verleent, wordt het behaalde resultaat overgenomen en hoef je","page":7},{"id":"bron-5-31","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"voor dat onderdeel geen examen meer te doen. 4. Op de resultatenlijst bij je diploma komt te staan dat je een vrijstelling hebt","page":7},{"id":"bron-5-32","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"voor dat examenonderdeel en het eerder behaalde resultaat staat tussen haakjes.","page":7},{"id":"bron-5-33","sourceId":"bron-5","title":"Beroepsgerichte examens","text":"5. Voor Loopbaan & Burgerschap kan je binnen Landstede mbo geen vrijstelling aanvragen.","page":7},{"id":"bron-5-34","sourceId":"bron-5","title":"3.2 Veel voorkomende situaties die voor een vrijstelling in aanmerking komen","text":"1. Je hebt al eerder generieke examens Nederlands, Engels of rekenen afgesloten met een","page":7},{"id":"bron-5-35","sourceId":"bron-5","title":"3.2 Veel voorkomende situaties die voor een vrijstelling in aanmerking komen","text":"voldoende resultaat. Als het examen op hetzelfde niveau is, kun je hiervoor vaak een vrijstelling krijgen.","page":7},{"id":"bron-5-36","sourceId":"bron-5","title":"3.2 Veel voorkomende situaties die voor een vrijstelling in aanmerking komen","text":"2. Ook bij een onvoldoende resultaat bij generieke examens kun je soms toch nog in","page":7},{"id":"bron-5-37","sourceId":"bron-5","title":"3.2 Veel voorkomende situaties die voor een vrijstelling in aanmerking komen","text":"aanmerking komen voor een vrijstelling, maar dat hangt af van de resultaten van examens die je bij andere onderdelen hebt behaald. Deze vrijstellingen kun je aanvragen vanaf het moment dat de examencommissie kan vaststellen dat je ondanks de onvoldoende toch voldoet aan de diplomaeisen van jouw opleiding.","page":7},{"id":"bron-5-38","sourceId":"bron-5","title":"3.2 Veel voorkomende situaties die voor een vrijstelling in aanmerking komen","text":"3. Je hebt bij een andere mbo-opleiding al beroepsgerichte examens afgelegd. Als bij deze examens","page":7},{"id":"bron-5-39","sourceId":"bron-5","title":"3.2 Veel voorkomende situaties die voor een vrijstelling in aanmerking komen","text":"dezelfde kerntaken en onderliggende werkprocessen zijn geëxamineerd van het kwalificatiedossier van je opleiding kun je ook hiervoor een vrijstelling krijgen als het resultaat voldoende is.","page":7},{"id":"bron-5-40","sourceId":"bron-5","title":"3.2 Veel voorkomende situaties die voor een vrijstelling in aanmerking komen","text":"Bij elke opleiding moet je examens doen voor keuzedelen. Als je overstapt naar een andere opleiding kun","page":7},{"id":"bron-5-41","sourceId":"bron-5","title":"3.2 Veel voorkomende situaties die voor een vrijstelling in aanmerking komen","text":"je een vrijstelling aanvragen als het resultaat voldoende is en het keuzedeel waar je vrijstelling voor vraagt geen overlap heeft met je kwalificatiedossier in je nieuwe opleiding. In uitzonderlijke gevallen kan de examencommissie besluiten om ook een vrijstelling te geven voor een keuzedeel met een onvoldoende resultaat. Je moet altijd onderbouwen waarom je een vrijstelling aanvraagt.","page":8},{"id":"bron-5-42","sourceId":"bron-5","title":"3.2 Veel voorkomende situaties die voor een vrijstelling in aanmerking komen","text":"Binnen je opleiding worden een aantal keuzedelen aangeboden. Wanneer je liever een ander keuzedeel zou willen volgen, dan mag je dat aanvragen bij de examencommissie van jouw opleiding. Het team controleert of er geen overlap zit tussen het keuzedeel en jouw opleiding. Als dat niet het geval is kun je hiervoor toestemming krijgen. Als er wel overlap blijkt te zijn, dan kun je dat keuzedeel helaas niet volgen. 4. Aangepaste examinering","page":8},{"id":"bron-5-43","sourceId":"bron-5","title":"3.2 Veel voorkomende situaties die voor een vrijstelling in aanmerking komen","text":"1. Als je baat hebt bij aanpassingen van je examen, bijvoorbeeld omdat je een functiebeperking hebt, kun je examenfaciliteiten aanvragen bij de examencommissie. Dit doe je samen met je coach. 2. Bij een ernstige functiebeperking kan het nodig zijn dat (delen van) je examen aangepast moet(en) worden.","page":8},{"id":"bron-5-44","sourceId":"bron-5","title":"3.2 Veel voorkomende situaties die voor een vrijstelling in aanmerking komen","text":"3. Het SAB vraagt namens jou examenfaciliteiten aan bij de examencommissie. Ze bekijken samen met jou of je hiervoor in aanmerking komt en welke aanpassing voor jou nodig is. Je maakt hiervoor zelf een afspraak. Dat kan digitaal.","page":8},{"id":"bron-5-45","sourceId":"bron-5","title":"3.2 Veel voorkomende situaties die voor een vrijstelling in aanmerking komen","text":"4. Als je dyslexie hebt, krijg je een standaardpakket aan faciliteiten. Het SAB bekijkt dit op basis van bewijsstukken zoals een dyslexieverklaring. Als je meer nodig hebt dan dit pakket, of als het SAB aanvullende vragen heeft, kan je via je coach een afspraak inplannen.","page":8},{"id":"bron-5-46","sourceId":"bron-5","title":"3.2 Veel voorkomende situaties die voor een vrijstelling in aanmerking komen","text":"5. Als je overstapt naar een andere opleiding moet je opnieuw examenfaciliteiten aanvragen.","page":8},{"id":"bron-5-47","sourceId":"bron-5","title":"3.2 Veel voorkomende situaties die voor een vrijstelling in aanmerking komen","text":"6. Ook voor centrale examens kun je examenfaciliteiten krijgen. Deze faciliteiten zijn landelijk vastgesteld en worden verstrekt door het College van Toetsing en Examinering (het CvTE). Deze faciliteiten worden door het SAB aangevraagd. Zie hiervoor ook Passend examineren in het Mbo .","page":8},{"id":"bron-5-48","sourceId":"bron-5","title":"3.2 Veel voorkomende situaties die voor een vrijstelling in aanmerking komen","text":"7. De examencommissie zal de aangevraagde examenfaciliteiten toewijzen als zij naar haar oordeel doeltreffend zijn en voor Landstede MBO geen onevenredige belasting vormen. De afwijkende wijze van examinering moet zodanig zijn dat de inhoudelijke eisen gelijkwaardig zijn aan die voor de andere studenten.","page":8},{"id":"bron-5-49","sourceId":"bron-5","title":"3.2 Veel voorkomende situaties die voor een vrijstelling in aanmerking komen","text":"4.2. Korter dan zes jaar Nederlandstalig onderwijs 1. Studenten die korter dan zes jaar Nederlandstalig onderwijs hebben gevolgd","page":8},{"id":"bron-5-50","sourceId":"bron-5","title":"3.2 Veel voorkomende situaties die voor een vrijstelling in aanmerking komen","text":"(inclusief het studiejaar waarin het examen wordt gemaakt), kunnen bij de examencommissie een aanvraag indienen voor de hierna in lid 2, 3, 4 en 5 te noemen examenfaciliteiten. 2. Een half uur tijdverlenging voor de centrale examens lezen en luisteren Nederlands","page":8},{"id":"bron-5-51","sourceId":"bron-5","title":"3.2 Veel voorkomende situaties die voor een vrijstelling in aanmerking komen","text":"en Engels (alleen niveau 4). 3. Gebruik maken van een woordenboek dat Nederlandse woorden vertaalt naar je moedertaal. 4. 25% meer tijd voor instellingsexamens, omdat er per examen andere tijdslimieten zijn","page":8},{"id":"bron-5-52","sourceId":"bron-5","title":"5.1 Het examenplan","text":"1. In het examenplan kun je zien welke examens je moet behalen om een diploma te krijgen.","page":8},{"id":"bron-5-53","sourceId":"bron-5","title":"5.1 Het examenplan","text":"Het examenplan (kluis) wordt jaarlijks met je besproken. Je bepaalt samen met je coach of vakdocent of en wanneer je deel kan nemen aan examens.","page":8},{"id":"bron-5-54","sourceId":"bron-5","title":"5.1 Het examenplan","text":"2. Het examenplan van je opleiding vind je in je digitale leeromgeving e-TO en is onderdeel van","page":9},{"id":"bron-5-55","sourceId":"bron-5","title":"5.1 Het examenplan","text":"de Studiegids. Het kan voorkomen dat je examenplan tussentijds wijzigt. In dat geval zal je coach dit met je bespreken. Als je niet akkoord gaat met de wijzigingen heb je het recht om dit te weigeren. Dan blijft voor jou het oorspronkelijke examenplan van toepassing.","page":9},{"id":"bron-5-56","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"1. Je examenplan bestaat uit de volgende examens: beroepsgerichte examens,","page":9},{"id":"bron-5-57","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"examens voor keuzedelen en generieke examens. 2. Generieke examens zijn: Nederlands, rekenen en Engels (alleen niveau 4). Via je","page":9},{"id":"bron-5-58","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"opleiding word je geïnformeerd over deelname aan generieke examens. 3. Behalve examens moet je ook voldoen aan de volgende twee diplomaeisen:","page":9},{"id":"bron-5-59","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"a. In je opleiding moet je voldoende uren hebben besteed aan stage/BPV","page":9},{"id":"bron-5-60","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"(beroepspraktijkvorming) en je laatste BPV- periode moet beoordeeld zijn met een voldoende. b. Voor het onderdeel Loopbaan & Burgerschap ga je tijdens de gehele opleiding aan de","page":9},{"id":"bron-5-61","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"slag met allerlei opdrachten. Je legt daarvoor een portfolio aan dat in de laatste periode van de opleiding wordt beoordeeld. Als je portfolio met een voldoende wordt beoordeeld, heb je voldaan aan dit onderdeel. Je moet dit dus altijd hebben afgerond om in aanmerking te komen voor een diploma. 4. Sommige opleidingen hebben wettelijke beroepsvereisten. Zie ook artikel 1.5. Dat betekent","page":9},{"id":"bron-5-62","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"dat de branche aanvullende eisen stelt om te mogen werken in deze bedrijven. Je maakt dan ook nog hiervoor examens. Soms kan dat op school, maar het kan ook voorkomen dat je daarvoor naar een extern examencentrum moet reizen.","page":9},{"id":"bron-5-63","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"1. Je wordt minimaal drie weken voor een examen geïnformeerd over tijdstip en plaats van het examen.","page":9},{"id":"bron-5-64","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"2. Voor generieke examens kun je jezelf aanmelden via een digitale aanmeldtool. Je bent zelf verantwoordelijk voor het bijhouden en registreren van deze datum in je eigen agenda.","page":9},{"id":"bron-5-65","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"3. Een aantal examens, zoals centrale examens Nederlands, Engels en rekenen maak je op computers op school. Overige theorie-examens maak je handgeschreven of op een schoolcomputer.","page":9},{"id":"bron-5-66","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"4. Tijdens het examen zijn er surveillanten die toezicht houden dat het examen goed verloopt. Bij theorie-examens in de klas kan een docent ook optreden als surveillant. 5. Je krijgt per examenonderdeel te horen van je (vak)docent welke hulpmiddelen (rekenmachine, woordenboek, AI) je mag gebruiken bij het examen.","page":9},{"id":"bron-5-67","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"1. Je hebt zelf de keuze gemaakt om je voor het examen aan te melden. Dat betekent dat je ook aanwezig moet zijn en op tijd aanwezig bent. Als je te laat bent betekent dat je niet meer wordt toegelaten tot het examen. Dit betekent dat je als ‘niet verschenen/absent’ wordt geregistreerd. Zie hiervoor de regels in artikel 8.1. 2. Voor een centraal examen mag je binnen een half uur na de start van het examen nog wel deelnemen.","page":9},{"id":"bron-5-68","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"Je hebt dan wel minder tijd. 3. Leg je legitimatiebewijs neer op tafel voor je gaat deelnemen aan het examen. Een schoolpas, waarbij je foto duidelijk te zien moet zijn, ID-kaart, paspoort of rijbewijs zijn geldig.","page":9},{"id":"bron-5-69","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"4. Je mag alleen een pen en je legitimatiebewijs meenemen in de examenruimte. Zoek voor de rest van je spullen (jas, pet, mobieltje, smartwatch, tas e.d.) op tijd een goede en veilige opbergplaats in je eigen kluisje. Op sommige scholen zijn ook aparte kluisjes op de gang in de","page":9},{"id":"bron-5-70","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"5. In het examenlokaal zijn hulpmiddelen aanwezig als deze zijn toegestaan, zoals koptelefoons, woordenboeken en rekenmachines. 6. Ga rustig zitten en volg de aanwijzingen op van de surveillant. Begin met het examen na het startsein van de surveillant. 7. Als je tijdens het examen de regels niet naleeft wordt door de surveillant een proces-verbaal opgemaakt. Dit kan aanleiding zijn om het examen ongeldig te verklaren.","page":10},{"id":"bron-5-71","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"1. Je moet ook een aantal mondelinge examens doen. Deze examens worden door een onafhankelijke beoordelaar afgenomen. Dit kan gebeuren op school, maar ook online via Teams. 2. Van de meeste examens wordt een geluidsopname gemaakt, tenzij er twee beoordelaars bij de afname van het examen zijn.","page":10},{"id":"bron-5-72","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"Als het examen online wordt afgenomen, kan de beoordelaar je vragen om met de webcam je kamer te laten zien, een presentatie staande te doen en niet zittend of de uitwerking van je examenopdracht te delen op het scherm. 3. Omdat de examinator jou niet altijd kent, moet jij je kunnen legitimeren. Dit kan via de fysieke schoolpas of een schoolpas in een wallet waarbij jouw foto duidelijk te zien moet zijn, of een legitimatiebewijs.","page":10},{"id":"bron-5-73","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"1. Je maakt ook een aantal examens in de beroepspraktijk, vaak aan het einde van een BPV","page":10},{"id":"bron-5-74","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"periode. Deze examens worden afgenomen door een beoordelaar van het bedrijf of de instelling waar je BPV loopt. De beoordelaar van het bedrijf is niet je praktijkbegeleider. Soms zal een beoordelaar van school aansluiten bij de beoordeling. De school blijft altijd verantwoordelijk voor het examen in de praktijk en bepaalt het definitieve resultaat. 2. Het kan voorkomen dat je een praktijkexamen op school maakt ('simulatie'). Bij de","page":10},{"id":"bron-5-75","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"meeste opleidingen wordt dan een beoordelaar uit de praktijk betrokken bij de beoordeling.","page":10},{"id":"bron-5-76","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"1. Bij Landstede MBO heb je als student voor ieder examen twee gelegenheden. Je mag een","page":10},{"id":"bron-5-77","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"examen met een onvoldoende of voldoende resultaat opnieuw maken in tweede gelegenheid. Het hoogste resultaat telt. 2. Je kunt als student aan het einde van de opleiding eenmalig een finale gelegenheid","page":10},{"id":"bron-5-78","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"aanvragen bij de examencommissie als je één examen nog niet hebt behaald. Voorwaarde is dat alle andere examens die meetellen in de zak-slaagregeling van de opleiding met een voldoende zijn afgesloten. 3. Als je geen examengelegenheden meer hebt, kun je niet meer binnen je huidige inschrijving","page":10},{"id":"bron-5-79","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"als student diplomeren. Je kunt er dan voor kiezen om je in te schrijven als examenstudent (zie artikel 1.4).","page":10},{"id":"bron-5-80","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"1. Je maakt generieke examens Nederlands, Engels en rekenen op het niveau van je","page":10},{"id":"bron-5-81","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"opleiding. Dit is uitgedrukt in referentieniveaus. Voor Nederlands en rekenen gaat het om het 2F of 3F niveau, voor Engels gelden de niveaus A2/B1, B1/B2 of B2. Engels is alleen verplicht voor studenten die een opleiding volgen op niveau 4. Voor (examen)studenten","page":10},{"id":"bron-5-82","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"2. Als je bij de eerste examengelegenheid een voldoende hebt behaald voor het niveau dat","page":11},{"id":"bron-5-83","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"voor de opleiding noodzakelijk is, mag je het examen op een hoger niveau afleggen. Hiervoor krijg je twee nieuwe gelegenheden. Als je hiervoor geen voldoende haalt, blijft het resultaat van de eerste gelegenheid staan van het lagere niveau. Als je bij eerste gelegenheid een onvoldoende haalt, kan de student kiezen om terug te keren op het vereiste lagere niveau of alsnog in tweede gelegenheid een voldoende te halen,","page":11},{"id":"bron-5-84","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"3. In bijzondere gevallen kun je rechtstreeks deelnemen aan examens Nederlands, Engels en","page":11},{"id":"bron-5-85","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"rekenen op een hoger niveau. Je moet via het examenbureau een verzoek indienen bij de examencommissie en bewijzen toevoegen waarom je daarvoor in aanmerking komt, bijvoorbeeld omdat je tweetalig bent opgevoed of hoge resultaten kunt laten zien uit voortgangstoetsen die je hebt gemaakt in de les.","page":11},{"id":"bron-5-86","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"4. Als je resultaten hebt op twee verschillende niveaus, dan maak je de keuze welk niveau","page":11},{"id":"bron-5-87","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"1. Als je niet verschijnt op het examen en je niet hebt afgemeld, verlies je een examengelegenheid. Er","page":11},{"id":"bron-5-88","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"wordt dan een ‘Absent’ in jouw kluis in e_TO ingevoerd. 2. Je kunt binnen 3 maanden na het geplande examen een verzoek indienen bij de","page":11},{"id":"bron-5-89","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"examencommissie als je kunt aantonen dat je buiten je schuld niet bent verschenen. Als je kan aantonen dat er sprake was van ziekte of overmacht (bijv. sterfgeval, treinstaking etc.) kan de coach/RvK de absent binnen twee weken na invoering verwijderen.","page":11},{"id":"bron-5-90","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"3. Je kan je tot twee weken voor het examen afmelden met behoud van gelegenheid.","page":11},{"id":"bron-5-91","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"1. Als je tijdens het examen ziek wordt, mag je het examen onderbreken. Er wordt dan een","page":11},{"id":"bron-5-92","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"proces- verbaal opgemaakt door de surveillant. 2. De examencommissie bepaalt dan of het examen geheel of gedeeltelijk overgemaakt moet worden. 3. In incidentele gevallen kun je het examen op dezelfde dag opnieuw maken. Je mag dan","page":11},{"id":"bron-5-93","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"geen contact hebben met andere studenten. Dat kan betekenen dat je in een aparte ruimte moet zitten en geen gebruik mag maken van een eigen laptop of mobiele telefoon.","page":11},{"id":"bron-5-94","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"1. Als tijdens een examen iets bijzonders gebeurt, is er sprake van een onregelmatigheid. Dit","page":11},{"id":"bron-5-95","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"kan bijvoorbeeld een computerstoring zijn, hinderlijke geluiden in de omgeving, iemand die ziek wordt, je hebt niet de toegekende faciliteiten gekregen bij het examen of er is een verkeerd examen afgenomen. 2. De surveillant maakt een proces-verbaal op van de situatie en het examenbureau stuurt dit naar de","page":11},{"id":"bron-5-96","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"examencommissie. Dit moet binnen twee weken na afname van het examen gemeld worden. De examencommissie kan maatregelen nemen, zoals een examen opnieuw laten afnemen of de beoordeling bijstellen.","page":11},{"id":"bron-5-97","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"1. Is het je niet gelukt om je te houden aan de examenregels dan wordt dit aangemerkt als","page":11},{"id":"bron-5-98","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"fraude. Denk aan spieken, het gebruik van mobiele telefoon, smartwatch e.d., het overnemen van teksten of inhoud van internet of andere studenten, geen eigen, authentiek werk inleveren, het gebruik van AI als dit niet is toegestaan en/of het aanpassen van een","page":11},{"id":"bron-5-99","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"beoordeling. De examenregels zijn gepubliceerd in de opleidingsgids. 2. Ook hiervan maakt de surveillant een proces-verbaal op en het examenbureau stuurt dit","page":12},{"id":"bron-5-100","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"naar de examencommissie. Zij kunnen, afhankelijk van de ernst van de opgetreden fraude, maatregelen nemen zoals het ongeldig verklaren van het examen en daarmee het ontnemen van een examengelegenheid. Ook kan je voor een half jaar worden uitgesloten van het specifieke examen. Ook kan de examencommissie besluiten dat je gedurende een bepaalde periode geen examen mag doen. 3. Ook kan de examencommissie de directeur het advies geven om je volledig uit te sluiten","page":12},{"id":"bron-5-101","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"van examens, bijvoorbeeld omdat er al eerder fraude is gepleegd of de fraude heel ernstig is. In dat geval kan de directeur besluiten om je van school te verwijderen en hiervan melding te maken bij de Onderwijsinspectie. 4. Je hebt de mogelijkheid om in beroep te gaan tegen een besluit van de examencommissie, zie","page":12},{"id":"bron-5-102","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"1. Het eindresultaat van een kerntaak of keuzedeel wordt vastgesteld met de","page":12},{"id":"bron-5-103","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"begrippen ‘onvoldoende, ‘voldoende’ of ‘goed’ of op een cijferschaal van 1 tot en met 10. Deelresultaten van een kerntaak of keuzedelen, kunnen bestaan uit cijfers op de schaal van 1 tot en met 10 of met de begrippen onvoldoende, ‘voldoende’ of ‘goed’.","page":12},{"id":"bron-5-104","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"a. Wanneer het eindresultaat is opgebouwd uit deelcijfers, worden alle","page":12},{"id":"bron-5-105","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"deelcijfers vastgesteld op één decimaal omgezet naar de begrippen 'onvoldoende', ‘voldoende’ of ‘goed’ . Bij afronding naar het eindresultaat wordt het eindcijfer naar boven afgerond als de eerste decimaal een 5 of hoger is, en naar beneden als de eerste decimaal een 4 of lager is (5,49=5) b. Cijfers worden als volgt omgezet naar O-V-G","page":12},{"id":"bron-5-106","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"▪ Onvoldoende : lager dan 5,5 ▪ Voldoende : 5,5 – 7,5 ▪ Goed : 7,5 of hoger c. Voor het omzetten van woordoordelen O-V-G naar cijfers wordt O= 4, V= 6 en G=8. 2. Generieke examens worden altijd uitgedrukt in een cijferresultaat. Losse onderdelen worden vastgesteld op één decimaal. Op de resultatenlijst worden de resultaten van de instellingsexamens én de centrale examens apart vermeld met één decimaal.","page":12},{"id":"bron-5-107","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"Het eindresultaat wordt afgerond op een geheel getal. 3. Studenten van niveau 1 en niveau 2 krijgen een punt extra voor het resultaat van het generiek examen Nederlands. Dit resultaat blijft staan als je doorstroomt naar een opleiding op een hoger niveau. Als je afstroomt van niveau 3 naar niveau 2 heb je recht op een vrijstelling bij een voldoende, maar krijg je niet alsnog een extra punt toegekend.","page":12},{"id":"bron-5-108","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"Je mag wel nieuwe examens maken om je resultaat te verbeteren. Je hebt dan twee examengelegenheden. Het hoogste cijfer telt. 4. Op de resultatenlijst bij het diploma worden de resultaten van keuzedelen weergegeven met een afgerond cijfer of met de begrippen ‘onvoldoende’, ‘voldoende’ of ‘goed. Keuzedelen tellen mee in de zak-slaagregeling.. Hiervoor geldt de volgende regeling:","page":12},{"id":"bron-5-109","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"a. Het gemiddelde examenresultaat voor keuzedelen is ten minste een “voldoende” of een zes (6). b. Voor minimaal de helft van de keuzedelen is ten minste een “voldoende” of een zes (6) gehaald. c. Het resultaat van een keuzedeel is minimaal een vier (4) of een gelijkwaardige eindwaardering. d. De grootte van het keuzedeel weegt niet mee in de berekening van het gemiddelde.","page":12},{"id":"bron-5-110","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"5. Het resultaat voor Loopbaan & Burgerschap wordt weergegeven met het begrip “voldaan”. 6. Je kunt de vermelding cum laude op je diploma krijgen als alle eindresultaten van de resultatenlijst zijn afgerond met minstens een (afgerond) cijfer acht (8) of een woordoordeel “goed”. 7. Als er wettelijke beroepsvereisten zijn opgenomen in het kwalificatiedossier dan wordt dit apart vermeld op het diploma met verwijzing naar het betreffende artikel in de wet.","page":13},{"id":"bron-5-111","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"10.2. Diplomering 1. De examencommissie beoordeelt of jij voldoet aan de eisen voor diplomering. Als je geslaagd bent krijg je daarvan een bevestiging in je schoolmail. Hierin staat de datum waarop je bent geslaagd. Deze datum wordt overgenomen op je diploma en moet je hanteren voor melding aan DUO i.v.m. studiefinanciering. 2.","page":13},{"id":"bron-5-112","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"Daarna volgt op een later tijdstip de uitreiking van je diploma en resultatenlijst en teken je voor ontvangst en de juistheid van de resultaten. 3. Je bent geslaagd voor de opleiding wanneer je:","page":13},{"id":"bron-5-113","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"a. alle kerntaken met minimaal een voldoende afsluit; b. aan alle eisen van de overige verplichte examenonderdelen hebt voldaan; c. Voldaan hebt aan de diploma-eisen Loopbaan & Burgerschap en ´Voldoende voor de BPV´. 4. Als je zonder diploma de opleiding verlaat, maar al wel resultaten het behaald, kun je een mbo- verklaring krijgen.","page":13},{"id":"bron-5-114","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"Daarop staan alle resultaten vermeld van de examens die je hebt gemaakt, de beoordeling van de BPV en eventuele andere resultaten. Als je jonger dan 23 jaar bent en zonder startkwalificatie de opleiding verlaat, is de opleiding verplicht een mbo-verklaring mee te geven. Als je niet onder deze doelgroep valt kan je een mbo-verklaring aanvragen via je coach. 5.","page":13},{"id":"bron-5-115","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"Ook kun je voor sommige keuzedelen of onderdelen van je opleiding een mbo-certificaat krijgen. Deze keuzedelen of onderdelen zijn door de Minister van Onderwijs aangewezen. Je ontvangt dit certificaat alleen als je zonder diploma de opleiding verlaat.","page":13},{"id":"bron-5-116","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"11.1. Inzien en bespreken examenwerk 1. Je mag binnen twee weken nadat het voorlopig examenresultaat is gepubliceerd in de examenkluis het beoordeelde werk inzien bij het examenbureau. 2. Je mag dan het beoordelingsformulier inzien, en het gemaakte examenwerk als hierop beoordeeld is. Al het overige gemaakte examenwerk heb je vaak zelf al of heb je opgeslagen in je examenkluis. 3.","page":13},{"id":"bron-5-117","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"Tijdens de inzage mag je geen aantekeningen en/of foto’s maken. Als je dat fijn vindt, kan de beoordelaar of coach met je meegaan. Je moet daar dan zelf met hen een afspraak voor maken. 4. Je kunt ook de uitkomsten van de centrale examens inzien. Voor de examens Nederlands en Engels krijg je alleen inzage in je eigen antwoorden, het antwoordmodel en de score per vraag. De opgaves zelf krijg je niet te zien.","page":13},{"id":"bron-5-118","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"11.2. Kopie examenwerk Je hebt volgens de privacywetgeving AVG recht op een kopie van het eigen gemaakte en nagekeken examenwerk wanneer hier persoonsgegevens op staan. Je kunt dit via een e-mail aanvragen binnen twee weken na de beoordeling bij het examenbureau.","page":13},{"id":"bron-5-119","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"11.3. Bewaring 1. Landstede Groep is verplicht om na afloop van je uitschrijving alle examengegevens te bewaren gedurende een periode van 2 jaar.","page":13},{"id":"bron-5-120","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"2. Onder deze gegevens vallen de beoordelingsformulieren, proces-verbaal, bewijzen van vrijstellingen, toekenning van examenfaciliteiten, etc. 3. Diploma’s, resultatenlijsten en certificaten worden 50 jaar bewaard. 4. Indien binnen de hiervoor genoemde bewaartermijnen examengegevens en/of gemaakt examenwerk onderdeel vormen van een klacht of juridische procedure, worden de betreffende gegevens bewaard tot na afwikkeling van de klacht of een definitieve rechterlijke uitspraak.","page":14},{"id":"bron-5-121","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"12.1 Klachten over procedures Als je niet tevreden bent over algemene de gang van zaken bij de afname van een examen, (bijvoorbeeld overlast tijdens het examen), dan kun je dat melden bij de examencommissie. Dat moet binnen twee weken na het plaatsvinden van het incident. Ben je het niet eens met de beoordeling van een examen, dan kun je dat als klacht melden bij de examencommissie.","page":15},{"id":"bron-5-122","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"Naam student - Naam examen - Datum van afname - Beschrijving van de klacht Als het klacht over een beoordeling betreft moet er een motivering worden toegevoegd. Dit betekent dat je de beoordeling hebt ingezien. Binnen twee weken neemt de examencommissie een besluit over je klacht. De examencommissie kan deze periode één keer verlengen met maximaal twee weken. De examencommissie maakt de beslissing over de klacht via de mail aan jou bekend.","page":15},{"id":"bron-5-123","sourceId":"bron-5","title":"5.2 Onderdelen examenplan","text":"Als je het niet eens bent met de beslissing van de examencommissie dan kan je beroep aantekenen tegen deze beslissing bij de Commissie van Beroep voor de examens (zie 12.2) Een onafhankelijke commissie zal de klacht dan in behandeling nemen.","page":15},{"id":"bron-5-124","sourceId":"bron-5","title":"12.3 De Commissie van Beroep voor de Examens","text":"1. Je kunt in beroep gaan tegen beslissingen van de examencommissie bij de Commissie van Beroep voor de Examens van Landstede Groep. Dit is een onafhankelijke commissie, bestaande uit deskundigen die niet werkzaam zijn binnen Landstede Groep. 2. Je kunt binnen twee weken (14 kalenderdagen) na bekendmaking van de beslissing van de examencommissie een beroepschrift indienen. Het beroep moet het volgende bevatten:","page":15},{"id":"bron-5-125","sourceId":"bron-5","title":"12.3 De Commissie van Beroep voor de Examens","text":"Voordat de commissie een beslissing neemt stelt zij een onderzoek in waarbij de indiener van het beroepschrift en de examinator/examencommissie (online) worden gehoord. In het kader van dit onderzoek kan de commissie beproeven of een minnelijke regeling mogelijk is. 5. De commissie zal binnen vier weken na het verstrijken van de indieningstermijn van het beroep een uitspraak doen.","page":15},{"id":"bron-5-126","sourceId":"bron-5","title":"12.3 De Commissie van Beroep voor de Examens","text":"De commissie kan deze termijn met ten hoogste twee weken verlengen, tenzij beide partijen akkoord zijn met een verdere verlenging. 6. De commissie maakt haar uitspraak bekend aan de (examen)student dan wel zijn of haar wettelijk vertegenwoordigers, aan Landstede MBO, het bedrijf of de organisatie die de beroepspraktijkvorming verzorgt (indien aan de orde), en aan de Onderwijsinspectie. 7.","page":15},{"id":"bron-5-127","sourceId":"bron-5","title":"12.3 De Commissie van Beroep voor de Examens","text":"Als de commissie het beroep gegrond acht, vernietigt zij de bestreden beslissing geheel of gedeeltelijk. Zij is in dat geval niet bevoegd om een nieuwe beslissing te nemen, maar kan wel bepalen dat opnieuw of alsnog een beslissing moet worden genomen, en aan de te nemen beslissing nadere voorwaarden stellen.","page":15},{"id":"bron-5-128","sourceId":"bron-5","title":"12.3 De Commissie van Beroep voor de Examens","text":"8. De uitspraak van de commissie is voor iedereen bindend en moet onverkort worden uitgevoerd. De examencommissie of de examinator van wie de beslissing (gedeeltelijk) is vernietigd, moet zo nodig een nieuwe beslissing nemen met inachtneming van de uitspraak van de commissie. De commissie kan voor het nemen van een nieuwe beslissing een termijn stellen in haar uitspraak. 9.","page":16},{"id":"bron-5-129","sourceId":"bron-5","title":"12.3 De Commissie van Beroep voor de Examens","text":"Tegen de uitspraak van de commissie kan binnen zes weken hoger beroep worden ingesteld bij de Afdeling bestuursrechtspraak van de Raad van State. Informatie over deze procedure en een voorbeeld-beroepschrift vind je hier: Studentenzaken - Raad van State.","page":16},{"id":"bron-5-130","sourceId":"bron-5","title":"12.3 De Commissie van Beroep voor de Examens","text":"1. In geval van situaties die niet in dit reglement staan, beslist de examencommissie. 2. Iedereen die betrokken is bij de examens en vertrouwelijke gegevens krijgt in te zien,","page":16},{"id":"bron-5-131","sourceId":"bron-5","title":"12.3 De Commissie van Beroep voor de Examens","text":"mag die gegevens niet delen met derden. Behalve als hij of zij daartoe wettelijk verplicht is. 3. Als onderdelen uit de onderwijs- en examenregeling (OER) strijdig zijn met de","page":16},{"id":"bron-5-132","sourceId":"bron-5","title":"12.3 De Commissie van Beroep voor de Examens","text":"bepalingen uit dit reglement, gelden de bepalingen uit dit examenreglement. 4. Als onderdelen uit dit examenreglement strijdig zijn met bepalingen van de WEB en/of","page":16},{"id":"bron-5-133","sourceId":"bron-5","title":"12.3 De Commissie van Beroep voor de Examens","text":"het EKB, gelden de bepalingen van laatstgenoemde regelingen. 5. De examencommissie kan, in uitzonderlijke gevallen waarin de toepassing van dit","page":16},{"id":"bron-5-134","sourceId":"bron-5","title":"12.3 De Commissie van Beroep voor de Examens","text":"examenreglement tot onredelijke gevolgen leidt, besluiten een bepaling van dit examenreglement geheel of gedeeltelijk buiten toepassing te laten. 6. Dit examenreglement is vastgesteld op 17 juni 2026 door het College van Bestuur van","page":16},{"id":"bron-6-1","sourceId":"bron-6","title":"2.4 Van onderwijs naar examinering – wat kan een student verwachten","text":"1. De student wordt in de eerste periode van zijn opleiding door het onderwijsteam geïnformeerd over","page":20},{"id":"bron-6-2","sourceId":"bron-6","title":"2.4 Van onderwijs naar examinering – wat kan een student verwachten","text":"de wijze van examinering in de opleiding, waarbij ook het gehele examenplan wordt toegelicht. Het examenplan wordt jaarlijks met de studenten besproken. Het examenplan is onderdeel van de Onderwijs- en examenregeling (OER). De OER, waarin ook het examenreglement is opgenomen, wordt bij Landstede gepubliceerd in de Studiegids in e-TO. 2. Bij ingekochte examens is de validering geborgd door de werkwijze zoals beschreven in het","page":20},{"id":"bron-6-3","sourceId":"bron-6","title":"2.4 Van onderwijs naar examinering – wat kan een student verwachten","text":"betreffende examen. In alle gevallen is de kwaliteit van de bewijslast belangrijk. De bewijzen moeten altijd valide, betrouwbaar, representatief, authentiek en waar van toepassing vanuit de reële beroepspraktijk. Wanneer bewijzen moeten worden beoordeeld, dan gebeurt dat objectief, deskundig en met een duidelijk aangegeven cesuur. Hierbij wordt altijd de werkwijze gevolgd van het geldende examen. 3.","page":20},{"id":"bron-6-4","sourceId":"bron-6","title":"2.4 Van onderwijs naar examinering – wat kan een student verwachten","text":"Er kunnen voorwaarden gesteld worden aan deelname van examens. Deze voorwaarden dienen","page":20},{"id":"bron-6-5","sourceId":"bron-6","title":"2.4 Van onderwijs naar examinering – wat kan een student verwachten","text":"een onderwijskundig doel, zijn vastgelegd in de opleidingsgids en zijn voor aanvang van de opleiding gecommuniceerd met studenten. Aanvullende informatie over voorwaardelijke examinering is beschikbaar op de website van het Kennispunt: Handreiking – Voorwaardelijke toetsing en examinering - Onderwijs en examinering.","page":20},{"id":"bron-6-6","sourceId":"bron-6","title":"2.4 Van onderwijs naar examinering – wat kan een student verwachten","text":"A. Regeling examenprotocol centrale examinering mbo, dat gepubliceerd is op Examenbladmbo.nl.","page":20},{"id":"bron-6-7","sourceId":"bron-6","title":"2.4 Van onderwijs naar examinering – wat kan een student verwachten","text":"Hierin staan alle regels die gelden voor de examinering van centrale examens (Nederlands Lezen en Luisteren, Rekenen (t/m cohort 2022) en voor niveau 4 studenten Engels Lezen en Luisteren). B. Het examenreglement (bijlage 4) voor Landstede examinering. Dit examenreglement is voor","page":20},{"id":"bron-6-8","sourceId":"bron-6","title":"2.4 Van onderwijs naar examinering – wat kan een student verwachten","text":"studenten via de algemene Informatiegids in e-TO in te zien. Hierin staan alle regels die gelden voor de organisatie en de beoordeling van alle overige examenonderdelen","page":20},{"id":"bron-6-9","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"Landstede Groep kiest ervoor om alle examens in te kopen bij gecertificeerde examenleveranciers. Dit geldt voor alle beroepsgerichte examens, instellingsexamens en examens voor keuzedelen. Alleen als er geen examenproducten beschikbaar zijn kunnen examens zelf worden geconstrueerd.","page":20},{"id":"bron-6-10","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"Daarmee voldoet Landstede Groep aan de richtlijn die geldt sinds 1 augustus 2018, waarin de MBO Raad, het bedrijfsleven, het ministerie van OC&W, de Onderwijsinspectie van het Onderwijs en examenleveranciers met elkaar de afspraak gemaakt dat vanaf 1 augustus 2018 alleen nog valide examens ingezet mogen worden voor alle opleidingen na de invoering van de herziening van de kwalificatiestructuur vanaf 2016.","page":20},{"id":"bron-6-11","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"Hoewel de inzet van valide exameninstrumenten nog geen wettelijke verplichting is, hebben alle mbo’s zich hieraan geconformeerd. Centrale examens, examens van wettelijke beroepsvereisten en examens van keuzedelen vallen niet onder deze collectieve afspraak. Vanuit deze afspraak zijn drie routes ontwikkeld om tot valide examenproducten te komen:","page":20},{"id":"bron-6-12","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"Route 1: Inkoop van examenproducten bij een gecertificeerde examenleverancier. Route 2: Zelf ontwikkelen van examenproducten binnen de collectieve afspraken (alléén construeren als er geen producten voorhanden zijn in route 1). Route 3: Zelfontwikkelde examenproducten aanbieden voor externe validering. Dit kan van toepassing zijn voor examens die niet mogen worden ontwikkeld in route 2.","page":20},{"id":"bron-6-13","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"3.1.1 Organisatie van het examen 1. Studenten worden door het onderwijsteam minimaal vijftien werkdagen voorafgaand aan het","page":24},{"id":"bron-6-14","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"examen geïnformeerd over de aanmelding en het proces van examinering. 2. Alle examens die afgenomen worden, zijn vooraf vastgesteld door de examencommissie en worden","page":24},{"id":"bron-6-15","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"ongewijzigd afgenomen conform de beschrijvingen en procedures in het betreffende examen. 3. Het examenbureau heeft een coördinerende rol bij de afname van theorie-examens, generieke- en","page":24},{"id":"bron-6-16","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"centrale examens. Het examenbureau is verantwoordelijk voor surveillance tijdens deze examens en zorgt vooraf voor aanwezigheid van en uitleg over protocollen, hantering proces-verbaal bij onregelmatigheid en presentielijsten. 4. Bij examens die in de praktijk plaatsvinden, L&B en mondelinge examens is het team","page":24},{"id":"bron-6-17","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"verantwoordelijk voor een kwalitatief goede afname en beoordeling. Het examenbureau kan hierbij in overleg een ondersteunende rol vervullen. 5. Sommige studenten hebben examenfaciliteiten toegekend gekregen door de examencommissie. Het","page":24},{"id":"bron-6-18","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"examenbureau zorgt ervoor dat surveillanten en beoordelaars vooraf geïnformeerd zijn over de aard van de faciliteiten en zorgt ervoor dat de faciliteiten beschikbaar zijn tijdens het examen. Bij examens die in de praktijk plaatsvinden zorgt het team daarvoor.","page":24},{"id":"bron-6-19","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"3.1.2 Beoordeling examens De bewijzen voor diplomering worden onafhankelijk, objectief en deskundig beoordeeld. Dit gebeurt op basis van de kwaliteitseisen zoals beschreven in bijlage 17. We hanteren de volgende kwaliteitseisen:","page":24},{"id":"bron-6-20","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"1. De bewijzen t.b.v. diplomering worden onafhankelijk (objectief) en deskundig beoordeeld 2. De examinering is betrouwbaar 3. De afnamecondities en beoordelingen zijn voor studenten gelijkwaardig 4. De examinering is transparant","page":24},{"id":"bron-6-21","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"Deze kwaliteitseisen zijn gebaseerd op de richtlijnen van het Klim MBO en zijn van toepassing op alle examens: generiek, beroepsgericht en keuzedelen, zowel in simulatie als in de praktijk.","page":24},{"id":"bron-6-22","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"Examinering met externe beoordelaars en beoordeling in de beroepspraktijk Bij examens waarbij externe beoordelaars worden ingezet, blijft de opleiding te allen tijde verantwoordelijk voor de kwaliteit van de afname, de beoordeling van het examen en het uiteindelijke examenresultaat. Ter ondersteuning hiervan is Bijlage 38 – Handreiking afname en beoordeling in de praktijk beschikbaar.","page":24},{"id":"bron-6-23","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"Deze handreiking biedt kaders en richtlijnen voor het verantwoord afnemen en beoordelen van examens (of onderdelen daarvan) in de beroepspraktijk, bijvoorbeeld bij BPV-bedrijven, en beschrijft de uitgangspunten voor valide en betrouwbare examinering, deskundige en onafhankelijke beoordeling en het borgen van zicht en grip door opleiding en examencommissie.","page":24},{"id":"bron-6-24","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"Het onderwijsteam legt schriftelijk vast in de examenplaat op welke wijze de beoordeling van examens in de beroepspraktijk wordt geborgd. De examencommissie kan de examenplaat opvragen. Van de opleiding wordt verwacht dat zij actief betrokken is bij de beoordeling in de beroepspraktijk. Vooraf beoordeelt de opleiding of het examen objectief, onafhankelijk en deskundig kan worden afgenomen.","page":24},{"id":"bron-6-25","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"Indien dit niet voldoende kan worden geborgd, treft de opleiding passende maatregelen, bijvoorbeeld door het examen (mede) zelf in de beroepspraktijk af te nemen of te beoordelen. Daarbij dient vooraf de rolverdeling en scheiding tussen opleider en beoordelaar duidelijk te zijn vastgelegd. De student dient alle kerntaken met minimaal een voldoende af te sluiten.","page":24},{"id":"bron-6-26","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"3.1.3 Na afloop van het examen 1. De surveillant levert direct na afloop gemaakt examenwerk, presentielijsten en eventueel","page":27},{"id":"bron-6-27","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"opgemaakt proces-verbaal van onregelmatigheid in bij het examenbureau. 2. De beoordelaar, of bij inzet van een externe partij de verantwoordelijke docent uit het team, van","page":27},{"id":"bron-6-28","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"het examen levert het gemaakte examenwerk en de beoordelingsprotocollen in bij het examenbureau binnen twee weken na afname van het examen. 3. Het publiceren van een examenresultaat gebeurt binnen de termijn van twee werkdagen na","page":27},{"id":"bron-6-29","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"afname. Uitzondering hierop zijn de centrale examens en het instellingsexamen rekenen. Bij deze examens moet je langer wachten op het resultaat. 4. Een resultaat is, vanaf het moment dat het in e-TO is gezet, twee weken lang een voorlopig","page":27},{"id":"bron-6-30","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"resultaat, tenzij de examencommissie eerder een besluit neemt over het voorlopige resultaat (bijvoorbeeld bij een diploma, certificaat of mbo-verklaring). Als je het niet eens bent met het niet vastgestelde resultaat kan je een klacht indienen bij de examencommissie.","page":27},{"id":"bron-6-31","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"Als het resultaat dat gepubliceerd is in e-TO is vastgesteld (binnen 2 maanden na publicatie), kan je hierover alleen nog een beroepsschrift indienen bij de Commissie van Beroep voor de Examens. Informatie over Klacht en beroep vind je in artikel 3.15 van het Handboek Examinering. 5. De student heeft recht op inzage in gemaakt werk binnen twee weken nadat het resultaat is","page":27},{"id":"bron-6-32","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"gepubliceerd in e-TO. Als de termijn langer wordt is de student daarover vooraf geïnformeerd. 6. Het examenwerk wordt in beheer gegeven bij het examenbureau. Elke student heeft een eigen","page":27},{"id":"bron-6-33","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"diplomadossier. Alleen de medewerkers van het Examenbureau en de RVK hebben rechtstreeks toegang tot het archief. 7. Na afname van het examen kan de examencommissie besluiten om het resultaat te wijzigen of","page":27},{"id":"bron-6-34","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"in uitzonderingsgevallen de cesuur te wijzigen. 8. De hierboven genoemde termijn van twee weken is van toepassing met uitzondering van","page":27},{"id":"bron-6-35","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"3.2.1 Aanmelden voor centrale examens en instellingsexamens. Elke eenheid informeert aan het begin van het schooljaar de studenten over het aanmelden voor deze examens. De meeste locaties gebruiken voor de aanmelding van de centrale examens een digitale inschrijvingstool. Omdat de examinator de student niet altijd kent, dient de student zich te kunnen legitimeren. Dit kan via een legitimatiebewijs of de fysieke schoolpas met foto.","page":27},{"id":"bron-6-36","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"3.2.2 Rekenexamens De komende jaren zijn er twee verschillende situaties met betrekking tot de rekeneisen. Voor studenten tot en met cohort 2021 telt het resultaat van rekenen niet mee in de zak-slaagregeling. Voor deze studenten gelden de volgende rekeneisen:","page":27},{"id":"bron-6-37","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"Entree: maken een nul- en voortgangsmeting • Studenten van niveau 2/3: rekenen 2F • Studenten van niveau 4: rekenen 3F Voor studenten vanaf cohort 2022 telt het resultaat van rekenen wel mee in de zak-slaagregeling. Voor deze studenten gelden de volgende rekeneisen:","page":27},{"id":"bron-6-38","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"Entree: studenten hebben voldaan aan de inspanningsverplichting voor rekenen wanneer hun rekenontwikkeling, inclusief de beheersing op het eind, in beeld is gebracht.(zie 3.2.11) Wanneer de student bij de nulmeting aantoont dat hij het rekenen niveau 2 al beheerst, kan de student op een hoger niveau het rekenexamen afleggen. Op de resultatenlijst komt één resultaat. Minimaal moet de voortgang op de resultatenlijst.","page":27},{"id":"bron-6-39","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"Doet de student een examen op een hoger niveau dan wordt de voortgang niet vermeld.","page":27},{"id":"bron-6-40","sourceId":"bron-6","title":"2.6 Valide examenproducten","text":"Mbo 2: rekenen niveau 2 • Mbo 3: rekenen niveau 3 • Mbo 4: rekenen niveau 4","page":27},{"id":"bron-6-41","sourceId":"bron-6","title":"3.5 Examens in het kader van Wettelijke Beroepsvereisten","text":"Bij een aantal opleidingen eist de branche bepaalde aantoonbare theoretische kennis of beroepsvaardigheden om in de branche te mogen werken. Een voorbeeld is de opleiding Veiligheid en Toezicht. Alle medewerkers in deze branche moeten van het Ministerie van Justitie een praktijkexamen afleggen in een eigen examencentrum.","page":36},{"id":"bron-6-42","sourceId":"bron-6","title":"3.5 Examens in het kader van Wettelijke Beroepsvereisten","text":"Wettelijke vereisten zijn opgenomen in het kwalificatiedossier en moeten altijd opgenomen worden in het examenplan en worden op het diploma vermeld. De verantwoordelijkheid voor de afname en beoordeling van deze examens ligt bij de branche. Er kunnen afwijkende afnamecondities van toepassing zijn, zoals toestaan van meerdere gelegenheden en een eigen procedure voor het toekennen van eventuele examenfaciliteiten.","page":36},{"id":"bron-6-43","sourceId":"bron-6","title":"3.5 Examens in het kader van Wettelijke Beroepsvereisten","text":"3.6 Aantal gelegenheden 3.6.1 Recht op twee gelegenheden Wettelijk heeft een student het recht op minimaal één herkansing voor ieder examenmoment. De meest voorkomende redenen voor een tweede gelegenheid zijn:","page":36},{"id":"bron-6-44","sourceId":"bron-6","title":"3.5 Examens in het kader van Wettelijke Beroepsvereisten","text":"Het behalen van een onvoldoende in de 1e gelegenheid. • Het niet verschijnen bij het examen. • Het niet voldoen aan de in het examen gestelde precondities (dit levert bijvoorbeeld het resultaat Onbepaald op in TOA) • Gemiste deadlines waardoor het resultaat Absent in e-TO is geregistreerd. • Het proberen te behalen van een hoger examenresultaat. Het hoogste resultaat telt.","page":36},{"id":"bron-6-45","sourceId":"bron-6","title":"3.5 Examens in het kader van Wettelijke Beroepsvereisten","text":"• Het examen van de student is in 1e gelegenheid ongeldig verklaard door de examencommissie vanwege fraude of onregelmatigheden. 3.6.2 Finale gelegenheid Studenten hebben de mogelijkheid aan het eind van de opleiding om één finale gelegenheid aan te vragen als één examen nog niet is behaald bij de examencommissie. Hier zijn de volgende voorwaarden aan verbonden:","page":36},{"id":"bron-6-46","sourceId":"bron-6","title":"3.5 Examens in het kader van Wettelijke Beroepsvereisten","text":"Voor het herkansen van één voldoende of onvoldoende resultaat dat nodig is om aan de zak- slaagregeling/compensatieregeling in de examenmap te voldoen.","page":36},{"id":"bron-6-47","sourceId":"bron-6","title":"3.5 Examens in het kader van Wettelijke Beroepsvereisten","text":"Alle overige examens (inclusief L&B), voldoen aan de in de zak-slaagregeling gestelde eisen. Rekenexamens (tot en met cohort 2021) en keuzedelen (tot en met cohort 2019) vallen niet onder de zak-slaagregeling. Een finale gelegenheid mag wel worden ingezet om een onvoldoende resultaat voor een van deze onderdelen te herkansen.","page":36},{"id":"bron-6-48","sourceId":"bron-6","title":"3.5 Examens in het kader van Wettelijke Beroepsvereisten","text":"Wanneer aan bovenstaande voorwaarden voldaan wordt, kan de RVK van het team een finale gelegenheid voor een student via het examenbureau aanvragen bij de examencommissie. Dit kan gedaan worden via het online invulbare formulier ‘Aanvraag Finale gelegenheid’ (bijlage 11).","page":36},{"id":"bron-6-49","sourceId":"bron-6","title":"3.5 Examens in het kader van Wettelijke Beroepsvereisten","text":"Wanneer een student voor meerdere onderdelen een 3e gelegenheid nodig heeft, dan kan dit alleen als examenstudent (zie 4.6).","page":36},{"id":"bron-6-50","sourceId":"bron-6","title":"3.5 Examens in het kader van Wettelijke Beroepsvereisten","text":"3.6.3 Deel van het examen overdoen als herkansing Wanneer een onvoldoende is behaald en een herkansing nodig is, dan kan herkanst worden op een deel van het examen (bijvoorbeeld werkprocesniveau of opdrachtniveau) als het te herkansen werkproces/opdracht dit toelaat en het niet in strijd is met de beschreven procedure van het betreffende examen. Bij herkansing op opdrachtniveau moet er vooraf met de DEC worden afgestemd.","page":36},{"id":"bron-6-51","sourceId":"bron-6","title":"3.5 Examens in het kader van Wettelijke Beroepsvereisten","text":"3.6.4 Nieuwe gelegenheden bij identiek examen bij doorstroom of afstroom Bij een beperkt aantal kwalificaties zijn de examens van het hogere niveau en het lagere niveau waarnaar de student doorstroomt of afstroomt, volledig identiek. Heeft de student een identiek examen al afgelegd op het hogere niveau met een resultaat waarbij de student voldoet aan de zak-slaagregeling, moet hier een","page":36},{"id":"bron-6-52","sourceId":"bron-6","title":"3.5 Examens in het kader van Wettelijke Beroepsvereisten","text":"Stap 6 De RVK verwijdert het geregistreerde speciale resultaat ‘Absent’ binnen twee weken uit e-TO.","page":38},{"id":"bron-6-53","sourceId":"bron-6","title":"3.5 Examens in het kader van Wettelijke Beroepsvereisten","text":"3.7 Onregelmatigheid en fraude bij examens 3.7.1 Onregelmatigheid Iedere onregelmatigheid of (vermoedelijke) fraude moet door de surveillant/beoordelaar worden gemeld bij het examenbureau, dat dit binnen één week doorgeeft aan de examencommissie. De surveillant of beoordelaar stelt na afloop van het examen een proces-verbaal van het examenmoment (bijlage 13) op waarin de situatie wordt vastgelegd.","page":38},{"id":"bron-6-54","sourceId":"bron-6","title":"3.5 Examens in het kader van Wettelijke Beroepsvereisten","text":"Er is sprake van onregelmatigheden tijdens het examenproces of het examen als zaken ongewenst anders verlopen dan is afgesproken, zonder dat daarbij opzet in het spel is. De surveillant of beoordelaar bepaalt (eventueel in overleg met de student) of het examen kan worden voortgezet. Voorbeelden van onregelmatigheid, die zowel individueel als collectief kunnen voorkomen:","page":38},{"id":"bron-6-55","sourceId":"bron-6","title":"3.5 Examens in het kader van Wettelijke Beroepsvereisten","text":"Een deel van het examen is niet uitgevoerd; - Er zijn computer- of andere (technische) problemen opgetreden (uitval stroom, airco, brandalarm gaat af) waardoor het examen slechts deels of niet volgens de instructie heeft plaatsgevonden; - Een student wordt onwel en kan het examen niet voltooien; - Het examen is niet conform het originele vastgestelde examen afgenomen; - Er is een verkeerd examen afgenomen;","page":38},{"id":"bron-6-56","sourceId":"bron-6","title":"3.5 Examens in het kader van Wettelijke Beroepsvereisten","text":"- Door de examencommissie toegekende faciliteiten zijn tijdens het examen niet beschikbaar. Let op: alleen de examencommissie kan een afgenomen examen ongeldig verklaren. Indien de examencommissie tot het oordeel komt dat één of meerdere studenten verwijtbaar gedrag hebben vertoond dan wordt dat als fraude aangemerkt. Voor de procedure rondom fraude, zie paragraaf 3.7.2.","page":38},{"id":"bron-6-57","sourceId":"bron-6","title":"3.5 Examens in het kader van Wettelijke Beroepsvereisten","text":"Stappenplan procedure ‘onregelmatigheden’ Stappen Wat? Door wie? Stap 1 Constateren van een onregelmatigheid Surveillant of beoordelaar Stap 2 Bepalen of het examen kan worden voortgezet of niet, zo nodig in overleg met de student(en)","page":38},{"id":"bron-6-58","sourceId":"bron-6","title":"3.5 Examens in het kader van Wettelijke Beroepsvereisten","text":"Surveillant of beoordelaar (waar nodig in overleg met het examenbureau) Stap 3 Opmaken proces- verbaal met vermelding van toedracht en de ondernomen acties (bijlage 13)","page":38},{"id":"bron-6-59","sourceId":"bron-6","title":"Surveillant of beoordelaar","text":"Stap 4 Proces-verbaal naar examenbureau Surveillant of beoordelaar Stap 5 Proces-verbaal wordt per e-mail opgestuurd naar de examencommissie. Het examenbureau informeert de RVK per mail over de onregelmatigheid","page":38},{"id":"bron-6-60","sourceId":"bron-6","title":"Examenbureau","text":"Stap 6 Examencommissie bepaalt of er sprake is van een onregelmatigheid of fraude, neemt besluit over de consequenties, legt dit vast en communiceert met alle betrokkenen.","page":38},{"id":"bron-6-61","sourceId":"bron-6","title":"Examencommissie","text":"3.7.2 Fraude Bij fraude is sprake van verwijtbaar en opzettelijk gedrag. Dat is het geval wanneer (onderdelen van) het gehele examenproces bewust wordt beïnvloed met als doel een ander resultaat uit het examen te verkrijgen. Voorbeelden, die zowel studenten als een beoordelaar kunnen betreffen:","page":38},{"id":"bron-6-62","sourceId":"bron-6","title":"Examencommissie","text":"Een student gebruikt een spiekbriefje of andere gegevensdrager tijdens een examen waar dit niet is toegestaan.","page":38},{"id":"bron-6-63","sourceId":"bron-6","title":"Examencommissie","text":"3.9 Vrijstellingsprocedure - algemene kaders 3.9.1 Vrijstelling a. Vrijstellingen voor beroepsgerichte examens kunnen alleen worden toegekend als het resultaat minimaal voldoende is. b. Voor generieke examens, beroepsgerichte theorie-examens en keuzedelen gelden aangepaste regels, waarbij ook voor onvoldoende resultaten vrijstelling kan worden gegeven als de student daarmee voldoet aan de zak-slaagregeling. c.","page":42},{"id":"bron-6-64","sourceId":"bron-6","title":"Examencommissie","text":"Vrijstellingen die worden aangevraagd voor voldoende resultaten kunnen gedurende de gehele opleiding aangevraagd worden. d. Vrijstellingen die worden aangevraagd voor onvoldoende resultaten kunnen pas worden aangevraagd wanneer bepaald kan worden of aan de zak-slaagregeling is voldaan. e. Een vrijstelling heeft geen eindtermijn en geldt voor de gehele opleidingsduur (uitgezonderd verlopen keuzedelen). 3.9.2 Procedure a.","page":42},{"id":"bron-6-65","sourceId":"bron-6","title":"Examencommissie","text":"De student dient, in afstemming met de Resultaatverantwoordelijke Kwaliteit (RVK), een aanvraag voor vrijstelling in via het examenbureau. Hiervoor wordt het 'Aanvraagformulier vrijstelling' (bijlage 14) gebruikt, dat altijd onderbouwd moet zijn met bewijzen. b. De medewerker van het examenbureau dient vervolgens een verzoek in e-TO via de button 'formele verzoeken' en voegt het aanvraagformulier inclusief bewijsstukken toe. c.","page":42},{"id":"bron-6-66","sourceId":"bron-6","title":"Examencommissie","text":"Bij de aanvraag voor vrijstellingen voor de generieke vakken op alle examenonderdelen moeten vanaf schooljaar 2025-2026 net als bij de keuzedelen vrijstellingsmappen gebruikt worden voor studenten vanaf cohort 2022-2023. d. De examencommissie behandelt de aanvraag en licht de student in over de beslissing. Bij goedkeuring wordt dit gefiatteerd in e-TO.","page":42},{"id":"bron-6-67","sourceId":"bron-6","title":"Examencommissie","text":"De examencommissie behandelt alleen vrijstellingen die volgens de geldende procedure binnen e-TO worden aangevraagd. De examencommissie licht bij afwijzing altijd toe waarop haar besluit is gebaseerd. e. Verleende vrijstellingen worden met de term 'vrijstelling' en het oorspronkelijke resultaat in e-TO geregistreerd. Op de resultatenlijst bij het diploma is zichtbaar dat het resultaat tot stand is gekomen door een vrijstelling.","page":42},{"id":"bron-6-68","sourceId":"bron-6","title":"Examencommissie","text":"a. In alle gevallen neemt de examencommissie het besluit over het wel of niet verlenen van een","page":42},{"id":"bron-6-69","sourceId":"bron-6","title":"Examencommissie","text":"vrijstelling. b. Er is een vrijstellingenregister beschikbaar via de tegel van de examencommissie.","page":42},{"id":"bron-6-70","sourceId":"bron-6","title":"Examencommissie","text":"3.9.9.3 Vrijstelling keuzedeel Duits op basis van examens Goethe Instituut a. Voor een behaald certificaat van het Goethe Instituut kan een examencommissie een vrijstelling verlenen voor het keuzedeel 'Duits in het beroepsonderwijs' op hetzelfde of een onderliggend niveau. b. Er kan vrijstelling worden verleend voor een afzonderlijke vaardigheid. c. Er kan geen vrijstelling worden verleend voor beroepsgerichte examens. d.","page":48},{"id":"bron-6-71","sourceId":"bron-6","title":"Examencommissie","text":"Een vrijstelling wordt alleen verleend op het hele keuzedeel wanneer alle afzonderlijke onderdelen zijn behaald op de betreffende niveaus van het keuzedeel.. 3.9.9.4 Vrijstelling remediërende keuzedelen a. Voor remediërende keuzedelen wordt bij doorstroom naar niveau 2 en/of 3 geen vrijstelling verleend. b. Bij de overstap van Entree naar niveau 2 is het wel toegestaan een remediërend keuzedeel opnieuw te kiezen en te volgen. c.","page":48},{"id":"bron-6-72","sourceId":"bron-6","title":"Examencommissie","text":"Daarbij moeten wel de voorwaarden van de niveau 2 opleiding in acht worden genomen, zoals het aantonen van een achterstand. d. Er worden dan dus extra (keuzedeel) uren gerealiseerd. 3.10 Bijzondere situaties 3.10.1 Identieke examens bij door- of afstroom a.","page":48},{"id":"bron-6-73","sourceId":"bron-6","title":"Examencommissie","text":"Als examens van een hoger en lager niveau volledig identiek zijn en de student het identieke examen op het hogere niveau met een voldoende resultaat heeft behaald, moet hier een vrijstelling voor worden aangevraagd bij door- of afstroom naar het lagere niveau. b.","page":48},{"id":"bron-6-74","sourceId":"bron-6","title":"Examencommissie","text":"Bij een tussentijdse door- of afstroom krijgt de student een nieuw examenplan dat recht geeft op twee nieuwe gelegenheden per examen, tenzij het een doorstroom binnen een kwalificatiedossier van een 23000-nummer naar een 25000-nummer betreft. 3.11 Vermelding op resultatenlijst 3.11.1 Vermelding van vrijstellingen a.","page":48},{"id":"bron-6-75","sourceId":"bron-6","title":"Examencommissie","text":"Examenfaciliteiten zijn aanpassingen (qua vorm, niet op inhoud) in of bij het examen voor studenten met een extra ondersteuningsbehoefte, bijvoorbeeld op basis van een functiebeperking. Iedere student (met een geldige reden) kan een aanvraag doen voor examenfaciliteiten.","page":48},{"id":"bron-6-76","sourceId":"bron-6","title":"Examencommissie","text":"Het is wenselijk dat examenfaciliteiten zo vroeg mogelijk worden aangevraagd, maar pas nadat er binnen het onderwijs voldoende tijd is genomen om te oefenen met de ondersteuning waar de student het meest baat bij heeft. De examencommissie besluit over het toekennen van faciliteiten. Het onderwijsteam, vaak de coach, vraagt voor de student examenfaciliteiten aan en stelt daarvoor via e- TO een hulpvraag aan SAB.","page":48},{"id":"bron-6-77","sourceId":"bron-6","title":"Examencommissie","text":"Er kunnen faciliteiten aangevraagd worden voor generieke en beroepsgerichte examens. Indien nodig neemt de student contact op met de studentadviseur van SAB voor een gesprek waarin de aanvraag wordt besproken. . Bij twijfel over de praktische uitvoerbaarheid van een voorgestelde examenfaciliteit neemt de studentadviseur contact op met het examenbureau of het onderwijsteam.","page":48},{"id":"bron-6-78","sourceId":"bron-6","title":"Examencommissie","text":"Na afstemming vraagt de studentadviseur de faciliteiten aan in e-TO bij de examencommissie. De examencommissie neemt op basis van de aanvraag van SAB een besluit. Als een student overstapt naar een andere opleiding moeten faciliteiten opnieuw worden aangevraagd bij de examencommissie. Het is niet altijd nodig dat de student opnieuw een gesprek heeft met de studentadviseur. De coach kan dit kenbaar maken in de hulpvraag aan SAB.","page":48},{"id":"bron-6-79","sourceId":"bron-6","title":"Examencommissie","text":"In bijlage 15 is een lijst opgenomen ‘Overzicht examenfaciliteiten’. Deze procedure geldt ook voor studenten uit de geïntegreerde leerroutes wanneer ze in het mbo worden ingeschreven.","page":48},{"id":"bron-6-80","sourceId":"bron-6","title":"Examencommissie","text":"3.12.1 Ondersteuning studenten met dyslexie Studenten met dyslexie krijgen een standaardpakket aan faciliteiten ter ondersteuning van het onderwijs dat ze volgen en de examens die zij afleggen. Als studenten meer nodig hebben dan dit pakket, kunnen ze dit aangeven bij hun coach, zie hoofdstuk 3.10.3 voor het stappenplan voor het aanvragen van faciliteiten voor dyslexie. Het standaardpakket aan faciliteiten voor examinering voor een dyslectische student:","page":49},{"id":"bron-6-81","sourceId":"bron-6","title":"Examencommissie","text":"Extra tijd • Verklanking • Spellingscontrole (voor elke student beschikbaar in TOA) Alle studenten vanaf cohort 2022 krijgen de volgende voorzieningen bij afname van het rekenexamen:","page":49},{"id":"bron-6-82","sourceId":"bron-6","title":"Examencommissie","text":"Extra tijd (30 minuten), dit betreft standaard extra tijd die voor alle studenten geldt. - Rekenkaart van de Coöperatie Examens MBO - Fysieke rekenmachine Deze faciliteiten voor generieke examens hoeven niet meer apart aangevraagd te worden bij SAB. Dit moet wél op het moment dat een beroepsgericht examen beroep doet op rekenvaardigheid.","page":49},{"id":"bron-6-83","sourceId":"bron-6","title":"Examencommissie","text":"3.12.2 Stappenplan aanvraag deelexamen rekenen Voor het generieke examen rekenen bestaat de mogelijkheid om gebruik te maken van een ‘deelexamen’. Stap 1: Signalering","page":49},{"id":"bron-6-84","sourceId":"bron-6","title":"Examencommissie","text":"De student en/of docent signaleert dat er sprake is van ernstige concentratieproblemen. • Er wordt vastgesteld dat een deelexamen mogelijk passend is. Stap 2: Opbouwen rekendossier","page":49},{"id":"bron-6-85","sourceId":"bron-6","title":"Examencommissie","text":"De rekenspecialist of rekendocent stelt een rekendossier samen. • In dit dossier wordt onderbouwd dat de student baat heeft bij een deelexamen. • Het dossier bevat:","page":49},{"id":"bron-6-86","sourceId":"bron-6","title":"Examencommissie","text":"o Resultaten van oefenexamens o Resultaten van deel-oefenexamens o Eventuele aanvullende observaties of onderbouwingen • Indien er geen rekenspecialist aanwezig is binnen de eenheid, voert de rekendocent deze taak uit. Stap 3: Beoordeling geschiktheid","page":49},{"id":"bron-6-87","sourceId":"bron-6","title":"Examencommissie","text":"Op basis van het rekendossier wordt vastgesteld dat het deelexamen een passende faciliteit is voor de student. Stap 4: Aanvraag faciliteit","page":49},{"id":"bron-6-88","sourceId":"bron-6","title":"Examencommissie","text":"De student dient via SAB een aanvraag in voor de faciliteit: ‘GE10 Gebruik van deelexamens rekenen op basis van rekendossier’. • Het rekendossier wordt toegevoegd aan de aanvraag. Stap 5: Besluitvorming","page":49},{"id":"bron-6-89","sourceId":"bron-6","title":"Examencommissie","text":"De examencommissie beoordeelt de aanvraag. • De examencommissie neemt een besluit op basis van het rekendossier en de onderbouwing. Stap 6: Organisatie van het deelexamen","page":49},{"id":"bron-6-90","sourceId":"bron-6","title":"• Bij goedkeuring wordt het examen als deelexamen ingepland:","text":"o Het examen wordt afgenomen in twee delen o De afnamemomenten vinden plaats:","page":49},{"id":"bron-6-91","sourceId":"bron-6","title":"• Bij goedkeuring wordt het examen als deelexamen ingepland:","text":"▪ Binnen één week ▪ Binnen één examenperiode Stap 7: Afname en borging","page":49},{"id":"bron-6-92","sourceId":"bron-6","title":"• Bij goedkeuring wordt het examen als deelexamen ingepland:","text":"Beide delen van het examen worden afgenomen volgens de geldende examenprocedures. • De resultaten worden gezamenlijk beoordeeld om het eindniveau vast te stellen. 3.12.3 Engelstalige rekenexamens Engelstalige rekenexamens zijn beschikbaar voor mbo-studenten die moeite hebben met de Nederlandse","page":49},{"id":"bron-6-93","sourceId":"bron-6","title":"• Bij goedkeuring wordt het examen als deelexamen ingepland:","text":"rekentoets door taalproblemen. Het gebruik van een Engelstalig examen kan worden aangevraagd via SAB (faciliteit GE 16) bij de examencommissie worden aangevraagd. 3.12.4 Begeleide afname reken- en taalexamens Voor de volledige uitwerking van kaders, rollen en verantwoordelijkheden wordt verwezen naar het beleidsdocument Begeleide afname Landstede mbo.","page":50},{"id":"bron-6-94","sourceId":"bron-6","title":"• Bij goedkeuring wordt het examen als deelexamen ingepland:","text":"Onderstaand zijn de belangrijkste uitgangspunten en werkwijzen voor onderwijsteams opgenomen. Definitie en doel Begeleide afname is een examenvorm waarbij een student het reken- of taalexamen maakt met ondersteuning van een begeleider.","page":50},{"id":"bron-6-95","sourceId":"bron-6","title":"• Bij goedkeuring wordt het examen als deelexamen ingepland:","text":"Deze ondersteuning is gericht op het creëren van passende randvoorwaarden, zoals het verminderen van spanning, het verduidelijken van niet-examenrelevante taal en het ondersteunen bij het gebruik van (digitale) hulpmiddelen. De begeleiding heeft geen invloed op de inhoudelijke beantwoording van het examen. Voorwaarden voor inzet Begeleide afname kan alleen worden ingezet wanneer de student:","page":50},{"id":"bron-6-96","sourceId":"bron-6","title":"• Bij goedkeuring wordt het examen als deelexamen ingepland:","text":"heeft deelgenomen aan het reguliere onderwijs (rekenen en/of taal); • gebruik heeft gemaakt van extra ondersteuningsaanbod; • minimaal één regulier (oefen)examen heeft afgelegd. Het onderwijsteam is verantwoordelijk voor het verzamelen en onderbouwen van deze gegevens. Aanvraagprocedure De aanvraag voor begeleide afname kan worden aangevraagd bij SAB via faciliteit GE16.","page":50},{"id":"bron-6-97","sourceId":"bron-6","title":"• Bij goedkeuring wordt het examen als deelexamen ingepland:","text":"Op basis van een deskundigenverklaring adviseert SAB over de ondersteuningsbehoefte van de student. De decentrale examencommissie (DEC) neemt vervolgens een besluit. Doelgroep: Begeleide afname kan worden ingezet voor studenten met aantoonbare ondersteuningsbehoeften, zoals:","page":50},{"id":"bron-6-98","sourceId":"bron-6","title":"• Bij goedkeuring wordt het examen als deelexamen ingepland:","text":"faalangst of rekenangst; • dyslexie (bij taalexamens), dyscalculie of TOS; • beperkte digitale vaardigheden; • onvoldoende beheersing van de Nederlandse taal (bij rekenexamens). Begeleider: Het team regelt de begeleider. De begeleider is een onafhankelijke reken- of taaldocent van een ander team en ondersteunt de student binnen vastgestelde kaders. De begeleiding is gericht op een rustige en veilige examensituatie. De begeleider mag:","page":50},{"id":"bron-6-99","sourceId":"bron-6","title":"• Bij goedkeuring wordt het examen als deelexamen ingepland:","text":"geruststellen en bemoedigen; • helpen bij het opstarten en gebruik van het digitale examen; • attenderen op hulpmiddelen; • teksten voorlezen of wijzen op voorleesfuncties; • niet-examenrelevante woorden verhelderen of vertalen. De begeleider mag niet:","page":50},{"id":"bron-6-100","sourceId":"bron-6","title":"• Bij goedkeuring wordt het examen als deelexamen ingepland:","text":"inhoudelijke hulp geven of antwoorden beïnvloeden; • vragen herformuleren of aanwijzingen geven binnen opgaven; • verwijzen naar specifieke oplossingen of hulpmiddelen die de uitkomst sturen; • betrokken zijn bij de beoordeling van het examen. Door deze afspraken na te leven, wordt geborgd dat studenten passende ondersteuning krijgen zonder dat de betrouwbaarheid en validiteit van het examen in het geding komen.","page":50},{"id":"bron-6-101","sourceId":"bron-6","title":"• Bij goedkeuring wordt het examen als deelexamen ingepland:","text":"3.12.5 Aangepaste examinering voor studenten met een ernstige functiebeperking In het kader van passend onderwijs wil Landstede Groep studenten met een ernstige functiebeperking in staat stellen om een beroepsopleiding te volgen en af te sluiten met een diploma. Zij lopen vaak aan tegen de eisen die gesteld worden aan de examinering van de beroepsgerichte examens. Het Onderzoekskader van de","page":50},{"id":"bron-6-102","sourceId":"bron-6","title":"• Bij goedkeuring wordt het examen als deelexamen ingepland:","text":"Onderwijsinspectie biedt ruimte voor aangepaste examinering bij deze deelnemers. Afnamecondities en beoordelingen moeten gelijkwaardig zijn voor studenten, maar hoeven niet volledig identiek te zijn. De coach is regiehouder, d.w.z. dat hij het proces in gang zet en de voortgang monitort.","page":51},{"id":"bron-6-103","sourceId":"bron-6","title":"• Bij goedkeuring wordt het examen als deelexamen ingepland:","text":"Stappenplan procedure ‘aanvraag aangepaste examinering voor studenten met een ernstige functiebeperking’ Stappen Wat? Door wie? Stap 1 Vaststellen ondersteuningsbehoefte bij student voor aanvang opleiding.","page":51},{"id":"bron-6-104","sourceId":"bron-6","title":"Scout/SAB","text":"Stap 2 Team dient verzoek in voor aanpassing in examencondities en/of voorstel voor aanpassing in vorm en/of inhoud van examen (route 2, zie H2.9.2).","page":51},{"id":"bron-6-105","sourceId":"bron-6","title":"Coach, ondersteund door RVK en SAB","text":"Stap 3a Bij bijzonderheden wordt er door het SAB vooraf overlegd met de examensecretaris","page":51},{"id":"bron-6-106","sourceId":"bron-6","title":"Coach, ondersteund door RVK en SAB","text":"Stap 3b Examencommissie neemt een besluit over het voorstel voor aangepaste examinering.","page":51},{"id":"bron-6-107","sourceId":"bron-6","title":"Examencommissie","text":"Stap 4 Als de student het niet eens is met de beslissing van de examencommissie kan hij zich wenden tot de Commissie van Beroep voor Examens (zie hfst. 3.13.2).","page":51},{"id":"bron-6-108","sourceId":"bron-6","title":"Student","text":"Het team kan een verzoek indienen voor aangepaste examinering bij de examencommissie:","page":51},{"id":"bron-6-109","sourceId":"bron-6","title":"Student","text":"1. Aanpassing in de examencondities: zoals het gebruik van een loep voor slechtzienden, een","page":51},{"id":"bron-6-110","sourceId":"bron-6","title":"Student","text":"aangepaste stoel, de aanwezigheid van een extern begeleider of een examen in meerdere delen vanwege beperkte belastbaarheid. 2. Aanpassingen in de vorm en inhoud van de examens, die alleen voor deze student gelden. Zolang deze","page":51},{"id":"bron-6-111","sourceId":"bron-6","title":"Student","text":"aanpassingen niet strijdig zijn met de eisen van de kwalificatiedossiers kan ook hiervoor een aanvraag worden gedaan voor een aangepast examen.","page":51},{"id":"bron-6-112","sourceId":"bron-6","title":"Student","text":"De examencommissie besluit over het voorstel voor aangepaste examinering en over het vaststellen van het aangepaste examen voor de individuele student. De examencommissie laat zich bij het besluit over de beroepsgerichte examens leiden door twee kwaliteitscriteria:","page":51},{"id":"bron-6-113","sourceId":"bron-6","title":"Student","text":"1. Doen de voorgestelde aanpassingen geen afbreuk aan de eisen uit het kwalificatiedossier? Is het","page":51},{"id":"bron-6-114","sourceId":"bron-6","title":"Student","text":"examenproduct vergelijkbaar en komt het oordeel vergelijkbaar tot stand? 2. Is de gekozen aanpassing doeltreffend (geschikt en noodzakelijk)? Neemt de aanpassing de","page":51},{"id":"bron-6-115","sourceId":"bron-6","title":"Student","text":"belemmering weg en zijn er geen beter passende opties? In het geval van een budgettaire ingreep wordt aan de betreffende mbo-directeur goedkeuring gevraagd door de examencommissie, voordat zij het besluit nemen. Alle aangepaste beroepsgerichte examens moeten afzonderlijk vastgesteld worden in route 2 (zie hoofdstuk 2.9.2 vaststelling examens in route 2).","page":51},{"id":"bron-6-116","sourceId":"bron-6","title":"Student","text":"Dat betekent dat het team een voorstel doet aan de examencommissie voor een aangepast examen. Deze stelt vervolgens het examen vast. Gezien de complexiteit is het van belang om vroegtijdig afstemming te zoeken met de examencommissies. Voor aanvullende informatie en advies over aanpassing van beroepsgerichte examens is een expertgroep ingericht bij het Kennispunt Onderwijs en Examinering. Zij kunnen meedenken in het aanpassen van examens.","page":51},{"id":"bron-6-117","sourceId":"bron-6","title":"Student","text":"Zie hiervoor het ‘servicedocument: passende examinering’ van KLIMmbo. Op www.examenbladmbo.nl is de brochure ‘ ‘Passend examineren in het mbo’.","page":51},{"id":"bron-6-118","sourceId":"bron-6","title":"Student","text":"Voor aanvullende informatie bij slechthorenden kunnen de Handreiking examinering dove en slechthorende studenten van het kennispunt MBO Taal & Rekenen of de Siméa richtlijnen geraadpleegd worden.","page":51},{"id":"bron-6-119","sourceId":"bron-6","title":"Studentadministrati e","text":"Stap 5 De administratie van SAB doet aanvraag voor toekenning van faciliteiten bij de Examencommissie en voegt de verklaring van DUO toe aan de hulpvraag onder “activiteiten”.","page":54},{"id":"bron-6-120","sourceId":"bron-6","title":"Administratie SAB","text":"Stap 6 Aanvraag wordt behandeld door de examencommissie. Bij afkeuring: onderbouwing in e-TO Bij goedkeuring: en fiatteren in e-TO","page":54},{"id":"bron-6-121","sourceId":"bron-6","title":"Examencommissie","text":"Stap 7 Student en examenbureau krijgen melding van besluit Examencommissie in e-TO 3.13 Het diplomadossier Het examenbureau beheert van iedere student een diplomadossier. Voorin het diplomadossier bevindt zich het Proces-verbaal (PV - bijlage 18) aangevuld met een checklist van alle beroepsgerichte- en keuzedeelexamens die in het dossier zijn opgenomen.","page":54},{"id":"bron-6-122","sourceId":"bron-6","title":"Examencommissie","text":"Het PV en de checklist maken het de examencommissie eenvoudiger om vlot de dossiers te kunnen controleren. Het is wenselijk dat de documenten in het dossier op dezelfde volgorde als het PV en de checklist is. Het format ‘checklist diplomadossier’ (bijlage 16) wordt ingevuld door de RVK van het onderwijsteam.","page":54},{"id":"bron-6-123","sourceId":"bron-6","title":"Examencommissie","text":"Het examenbureau is verantwoordelijk voor het overzichtelijk archiveren van de inhoud van het diplomadossier, aan de hand van de checklist. Voor de digitalisering van het diplomadossier is er een verzamelmap in e-TO (dossier op orde) beschikbaar, waarin het ‘formulier voldoende voor de BPV’, proces-verbaal, TOA-resultaten kan worden opgeslagen. Daarnaast is er een check ingebouwd op de keuzedeeluren.","page":54},{"id":"bron-6-124","sourceId":"bron-6","title":"Examencommissie","text":"De map maakt deel uit van de ZSR en moet worden toegevoegd aan het examenplan. Zie hiervoor ook: - Handleiding digitaal archiveren diplomadossier.pdf - 3.13.1 Diplomadossier","page":54},{"id":"bron-6-125","sourceId":"bron-6","title":"Examencommissie","text":"Elke student voldoet aan alle diplomavereisten. Dit zijn naast de examens die zijn vastgelegd in het examenplan ook diplomavoorwaarden ‘voldoende voor de BPV’ en de inspanningsverplichting voor L&B. Ook aan eventuele wettelijke beroepsvereisten moet zijn voldaan.","page":58},{"id":"bron-6-126","sourceId":"bron-6","title":"Examencommissie","text":"• Een diploma kan alleen worden aangevraagd als in e-TO is aangetoond dat alle examenmappen gevuld zijn met resultaten en die op basis van de geldende zak-slaagregeling leiden tot een diploma. • Het besluit tot diplomering wordt genomen door de examencommissie op basis van het bewijsmateriaal in het diplomadossier. • De student krijgt een melding via zijn schoolmail wanneer de examencommissie het diploma heeft gefiatteerd.","page":58},{"id":"bron-6-127","sourceId":"bron-6","title":"Examencommissie","text":"Deze datum geldt als de officiële diplomadatum en wordt overgenomen op het diploma. • Het diploma voldoet aan de eisen van het op dat moment geldende diplomamodel. • Diploma’s worden uitsluitend uitgedraaid door een daartoe bevoegde medewerker van het examenbureau of decentrale deelnemersadministratie. • Het diploma moet altijd worden ondertekend door een lid van de examencommissie.","page":58},{"id":"bron-6-128","sourceId":"bron-6","title":"Examencommissie","text":"Alle diplomastukken worden bewaard volgens de wettelijke richtlijnen die gelden voor officiële documenten die betrekking hebben op examinering en diplomering. 4.2 Proces-verbaal diplomering Voor fiattering van een diploma wordt een proces-verbaal opgemaakt, zie hiervoor bijlage 18 ‘Proces-verbaal diplomering’. Aan de hand van het diplomadossier wordt door de examencommissie vastgesteld of de student heeft voldaan aan alle vereisten.","page":58},{"id":"bron-6-129","sourceId":"bron-6","title":"Examencommissie","text":"De examencommissie zal voorafgaand aan het fiatteren van het diploma het diplomadossier controleren. Zij kan dit doen door elk dossier afzonderlijk te controleren, of bij gebleken vertrouwen vanuit vorige controles op basis van een steekproef. Dit is ter bepaling van de examencommissie zelf. Naast de controles aan het einde van de opleiding neemt de examencommissie tussentijds steekproeven.","page":58},{"id":"bron-6-130","sourceId":"bron-6","title":"Examencommissie","text":"Ook neemt de examencommissie steekproeven in e-TO of resultaten in e-TO correct zijn overgenomen. Voor beschrijving van de inhoud van het diplomadossier: zie hoofdstuk 3.11. 4.2.1 Voldoende voor de BPV In de WEB is als diplomavoorwaarde opgenomen dat een student een voldoende voor de BPV (beroepspraktijkvorming) moet hebben. Hiervoor is een bijlage beschikbaar: ‘Formulier voldoende voor de BPV’ (bijlage 19).","page":58},{"id":"bron-6-131","sourceId":"bron-6","title":"Examencommissie","text":"Het onderwijsteam verklaart met dit formulier dat de laatste BPV-periode met een voldoende resultaat is beoordeeld. Dit formulier wordt dus enkel gebruikt voor de afronding van de laatste BPV-periode.","page":58},{"id":"bron-6-132","sourceId":"bron-6","title":"Examencommissie","text":"Hoe de beoordeling van eerdere BPV-periodes plaatsvindt valt niet onder examinering, maar onder onderwijs. Het is daarom aan de onderwijsteams om daar invulling aan te geven. 4.2.2. Overzicht wettelijk minimumaantal uren BPV","page":58},{"id":"bron-6-133","sourceId":"bron-6","title":"Examencommissie","text":"Bovenstaande tabel geldt voor BOL-opleidingen. De opleiding verpleegkunde dient te voldoen aan de vereisten uit de Wet BIG en de WEB. Aanvullend op de urennorm van de wet WEB (de zogenaamde 1000 urennorm) zijn aanvullende uren van toepassing vanuit de wet BIG. Voor de wet BIG moeten minimaal 1535 klokuren theorie en 2300 praktijk gemaakt worden. Volg deze link voor de tabel norm begeleide onderwijsuren voor de BBL-opleidingen.","page":59},{"id":"bron-6-134","sourceId":"bron-6","title":"Examencommissie","text":"4.3 Cum laude diplomeren Vanaf het schooljaar 2020-2021 kunnen studenten een vermelding krijgen op het diploma dat ze cum laude geslaagd zijn. Een student slaagt cum laude als alle eindresultaten van de examenonderdelen van de resultatenlijst zijn afgesloten met een (afgerond) cijfer 'acht' of een woordoordeel 'goed'. Dit geldt ook voor de examenresultaten die geen onderdeel uitmaken van de zak-slaagregeling.","page":59},{"id":"bron-6-135","sourceId":"bron-6","title":"Examencommissie","text":"De RVK noteert dat de student voldoet aan de voorwaarden voor cum laude diplomeren en voegt dit toe aan het diplomadossier.","page":59},{"id":"bron-6-136","sourceId":"bron-6","title":"Examencommissie","text":"De RVK dient in het scherm <Studievoortgang en diplomering> een verzoek in bij de examencommissie om de student cum laude te diplomeren. Dat gebeurt door het aanvragen van het Speciale Zakslaagresultaat cum laude als onderdeel van de zak-slaagregeling waarvoor diplomering wordt aangevraagd. • De examencommissie controleert het diplomadossier.","page":59},{"id":"bron-6-137","sourceId":"bron-6","title":"Examencommissie","text":"• De examencommissie fiatteert het verzoek, waarna een regel op het diploma wordt toegevoegd dat de student voldaan heeft aan de voorwaarden om cum laude te diplomeren. • In de kluis van de student verschijnt een groene ster bij de voortgangsmeter van de betreffende zak-slaagregeling. 4.4 Diplomapapier De diploma’s, certificaten en mbo-verklaringen van Landstede Groep voldoen aan de wettelijke eisen t.a.v. de beveiliging van diplomapapier.","page":59},{"id":"bron-6-138","sourceId":"bron-6","title":"Examencommissie","text":"Het waardepapier waarop diploma's en mbo-verklaringen worden afgedrukt voldoet aan echtheidskenmerken d.m.v. vezels die zichtbaar worden bij ultraviolet licht, een diepdruk waardoor een reliëf ontstaat, holografische folie, een microtekst en een watermerk. Diploma’s en resultatenlijsten worden verstrekt op het Landstede diplomapapier met de blauwe balk.","page":59},{"id":"bron-6-139","sourceId":"bron-6","title":"Examencommissie","text":"Certificaten, mbo- verklaringen en diplomaverklaringen worden verstrekt op het Landstede waardepapier met de oranje balk. 4.5 Een student verlaat de opleiding met diploma Studenten die alle examenonderdelen van een opleiding met voldoende resultaat hebben afgesloten en voldaan hebben aan alle overige diploma-eisen, ontvangen een diploma en een resultatenlijst. De examencommissie verstrekt en ondertekent de diploma’s.","page":59},{"id":"bron-6-140","sourceId":"bron-6","title":"Examencommissie","text":"In bijlage 20 van dit handboek is een vastgesteld voorbeeldmodel opgenomen: ‘Model diploma en resultatenlijst HKS’.","page":59},{"id":"bron-7-1","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"Inhoud 1. Algemeen .............................................................................................................................. 2","page":2},{"id":"bron-7-2","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"2. Beoordeling ........................................................................................................................... 2","page":2},{"id":"bron-7-3","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"3. Herkansing ............................................................................................................................ 5","page":2},{"id":"bron-7-4","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"4. Toelichting wijzigen ............................................................................................................... 5","page":2},{"id":"bron-7-5","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"5. Technische handelingen ....................................................................................................... 6","page":2},{"id":"bron-7-6","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"6. Vaststelling afgekeurd .......................................................................................................... 6","page":2},{"id":"bron-7-7","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"7. Criteriumgericht interview ..................................................................................................... 7","page":2},{"id":"bron-7-8","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"Voorbereiding op het examen ● Lees de algemene handleiding door zodat je weet hoe de examinering is opgebouwd en wat","page":3},{"id":"bron-7-9","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"er van iedereen verwacht wordt bij de uitvoering van de examenopdrachten. ● Lees de examenopdracht en de beoordelingscriteria door. ● Maak een afspraak met de beoordelaar nadat deze digitaal is uitgenodigd.","page":3},{"id":"bron-7-10","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"Bespreek de afnamecondities die bij de examenopdracht horen. ● Spreek af met je beoordelaar wanneer je de examenopdracht uit gaat voeren.","page":3},{"id":"bron-7-11","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"Uitvoering van het examen ● Voer de examenopdracht uit zoals in de uitvoering beschreven is. ● Laat het beoordelingsformulier invullen door de beoordelaar. ● Bespreek de beoordeling met de beoordelaar. ● Controleer de beoordeling en bevestig deze eventueel volgens afspraak van de","page":3},{"id":"bron-7-12","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"Om de beoordeling volledig te doorlopen en af te ronden, volg je de onderstaande stappen 1 t/m 11. Het beoordelingsformulier kan ingevuld worden op een computer/laptop of een tablet. 1. Om je gekoppelde examens in te zien klik je op ‘Mijn examenmap’.","page":3},{"id":"bron-7-13","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"2. Klik op een examenopdracht om deze te openen. In dit overzicht kan je zien welke status de","page":3},{"id":"bron-7-14","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"3. Als er door jouw onderwijsinstelling voor is gekozen dat jij als student een beoordelaar mag","page":4},{"id":"bron-7-15","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"uitnodigen, is de knop ‘Kies beoordelaars’ zichtbaar. Wanneer je een beoordelaar wil uitnodigen klik je op de knop ‘Kies beoordelaars’.","page":4},{"id":"bron-7-16","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"4. Typ hier het e-mailadres in van jouw beoordelaar en klik op de knop ’Toevoegen’. Indien je","page":4},{"id":"bron-7-17","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"meer beoordelaars wil toevoegen herhaal je deze stap. Wanneer je alle beoordelaars hebt toegevoegd, klik je op de blauwe button ‘Beoordeling starten’. Het is mogelijk om later nog een extra beoordelaar toe te voegen.","page":4},{"id":"bron-7-18","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"7. Zodra de beoordelaar de examenopdracht heeft beoordeeld verandert de status van de","page":5},{"id":"bron-7-19","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"opdracht in ‘Controle door de student’. Niet elke onderwijsinstelling heeft deze optie geactiveerd. De status is in dat geval ‘Beoordeeld’. De stappen 7 t/m 9 zijn dan niet van toepassing. Klik op de examenopdracht om de controle uit te voeren.","page":5},{"id":"bron-7-20","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"10. De status wordt nu ‘Beoordeeld’. De studentbegeleider zet de beoordeling door naar de","page":6},{"id":"bron-7-21","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"examencommissie. Daardoor krijgt de examenopdracht de status ‘Vaststelling’. Wanneer de examencommissie de beoordeling heeft vastgesteld krijgt de examenopdracht de status ‘Vastgesteld’. 11. De administrateur heeft nu de mogelijkheid om de beoordeelde examenopdracht te","page":6},{"id":"bron-7-22","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"archiveren. De status van de examenopdracht verandert nu in ‘Gearchiveerd’. Dit is de laatste stap in het beoordelingsproces.","page":6},{"id":"bron-7-23","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"1. Afhankelijk van het beleid van de onderwijsinstelling start de studentbegeleider of de","page":6},{"id":"bron-7-24","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"examencommissie de herkansing. Een eventuele tweede herkansing moet altijd door een examencommissie klaargezet worden. De status ‘Wacht op herkansing’ geeft aan dat er een nieuwe examenopdracht klaarstaat om beoordeeld te worden. Bij de herkansing van de examenopdracht komt dan een ‘H1’ te staan. Er komt een ‘H2’ te staan wanneer het een tweede herkansing betreft.","page":6},{"id":"bron-7-25","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"2. Doorloop vervolgens de stappen die bij ‘hoofdstuk 2. Beoordeling' beschreven staan.","page":6},{"id":"bron-7-26","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"1. Het kan voorkomen dat de toelichting van een beoordeling van een examenopdracht gewijzigd","page":6},{"id":"bron-7-27","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"moet worden. De studentbegeleider kan dit proces in gang zetten. De status van de examenopdracht verandert in ‘Toelichting wijzigen’. De beoordelaar krijgt een e-mail met daarin de vraag om de toelichting te wijzigen. Wanneer dit is gewijzigd verandert de status in ‘Controle door de student'.","page":6},{"id":"bron-7-28","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"1. Een aantal examenopdrachten bevatten technische handelingen. Elke technische handeling","page":7},{"id":"bron-7-29","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"moet afzonderlijk worden beoordeeld. Je kan per technische handeling een beoordelaar uitnodigen. Ook is het mogelijk om meerdere technische handelingen te selecteren en daarvoor één beoordelaar uit te nodigen. Het beoordelingsproces van technische handelingen bevatten dezelfde stappen als de overige examenopdrachten.","page":7},{"id":"bron-7-30","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"2. Als het minimale aantal handelingen is beoordeeld, kan de gehele examenopdracht worden","page":7},{"id":"bron-7-31","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"ingeleverd. Indien je meer handelingen wil laten beoordelen, is het belangrijk om te wachten met het inleveren. Na het inleveren is het niet meer mogelijk om extra handelingen te laten beoordelen. Het inleveren doe je door op de blauwe button te klikken ‘Lever handelingen in'.","page":7},{"id":"bron-7-32","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"1. Wanneer de examencommissie de beoordeling van de examenopdracht heeft afgekeurd","page":7},{"id":"bron-7-33","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"verandert de status in ‘Beoordeling afgekeurd'. De studentbegeleider heeft nu de opties:","page":7},{"id":"bron-7-34","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"om de toelichting door de beoordelaar te laten wijzigen, of - om de beoordeling van een examenopdracht opnieuw naar de examencommissie te sturen.","page":7},{"id":"bron-7-35","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"1. Om te kunnen starten met het criteriumgericht interview moet er bewijslast worden","page":8},{"id":"bron-7-36","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"aangeleverd. Dit kan je doen in het blok ‘Bewijsstukken’. 2. Wanneer je een video wil toevoegen, klink op de blauwe button ‘Voeg video toe’.","page":8},{"id":"bron-7-37","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"3. Bij het toevoegen van een bestand is het noodzakelijk om het bewijsstuk in PDF aan te","page":8},{"id":"bron-7-38","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"leveren. Hiervoor kan je gebruikmaken van de blauwe button ‘Voeg bestand toe’. Zorg ervoor dat het bestand niet groter is dan 16 MB.","page":8},{"id":"bron-7-39","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"4. Klik op de titel van het bewijsstuk om een begeleider uit te nodigen om het bewijsstuk te","page":8},{"id":"bron-7-40","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"5. Klik op de button ‘Kies begeleider’ om vervolgens het e-mailadres van de begeleider te","page":8},{"id":"bron-7-41","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"6. Wanneer de begeleider is uitgenodigd om het bewijsstuk te controleren verandert de status","page":9},{"id":"bron-7-42","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"De status van ‘In beoordeling’ verandert als de begeleider het bewijsstuk heeft gecontroleerd in ‘Akkoord na controle’.","page":9},{"id":"bron-7-43","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"7. Voeg de verantwoording toe en koppel het bewijsstuk. De verantwoording mag uit maximaal","page":9},{"id":"bron-7-44","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"8. Wanneer alle beoordelingscriteria zijn gekoppeld aan één of meerdere bewijsstukken en er is","page":9},{"id":"bron-7-45","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"bij elk bewijsstuk een verantwoording toegevoegd, wordt de blauwe button ‘Inzenden voor de check op volledigheid’ actief. 9. Zet de bewijsstukken in de volgorde waarop je het gesprek graag wilt voeren.","page":9},{"id":"bron-7-46","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"10. Klik op de blauwe button ‘Inzenden voor de check op volledigheid’ om jouw portfolio in te","page":9},{"id":"bron-7-47","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"11. Je ontvangt een e-mail zodra de studentbegeleider het portfolio gecontroleerd heeft op","page":9},{"id":"bron-7-48","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"volledigheid. 12. Afhankelijk van het beleid van de onderwijsinstelling nodig jij de beoordelaars uit of worden de","page":9},{"id":"bron-7-49","sourceId":"bron-7","title":"Instructie student – Digitaal beoordelen September 2025","text":"beoordelaars door de onderwijsinstelling uitgenodigd wanneer het portfolio is gecontroleerd op volledigheid. 13. Neem deel aan het cgi.","page":9},{"id":"bron-8-1","sourceId":"bron-8","title":"Stap 1:","text":"Studenten en studentbegeleiders ontvangen op initiatief van de beheerder een uitnodiging per email om een account aan te maken.","page":1},{"id":"bron-9-1","sourceId":"bron-9","title":"Routeplanner rekenen Landstede Harderwijk/Lelystad/Dronten","text":"Versie 2025-2026 Rekenen telt mee Rekenen is 1 van de zogenaamde generieke vakken, net als Nederlands en Engels. Rekenen telt mee voor zak/slaag. Dit betekent dat je kan zakken als je een onvoldoende haalt voor je diploma. Je moet minimaal een 5,5 halen (afgerond een 6). Eventueel mag je voor maximaal 1 van je generieke vakken een 5 halen, mits je voor de andere generieke vakken minimaal een 6 hebt gehaald.","page":1},{"id":"bron-9-2","sourceId":"bron-9","title":"Routeplanner rekenen Landstede Harderwijk/Lelystad/Dronten","text":"Vrijstelling Je kan via je coach een vrijstelling aanvragen voor rekenen als je eerder op het MBO, of op de Havo een voldoende hebt gehaald voor rekenen, of een 5 die je compenseert met een 6 voor Nederlands en eventueel ook Engels. Met een rekenresultaat van het VMBO kan je geen vrijstelling aanvragen. Nulmeting Als eerstejaars student krijg je (na een korte introductieperiode) een nulmeting.","page":1},{"id":"bron-9-3","sourceId":"bron-9","title":"Routeplanner rekenen Landstede Harderwijk/Lelystad/Dronten","text":"Deze meting is een rekentoets die niet meetelt, maar geeft wel inzicht in je huidige rekenniveau. Meestal wordt deze toets afgenomen met TOA (Toets.nl). Als blijkt dat je op niveau zit mag je je in overleg met de rekendocent inschrijven voor het rekenexamen. Dit kan via Supersaas. Rekenexamen Het rekenexamen wordt meerdere keren per jaar aangeboden. De eerste keer is meestal in november, of op aanvraag.","page":1},{"id":"bron-9-4","sourceId":"bron-9","title":"Routeplanner rekenen Landstede Harderwijk/Lelystad/Dronten","text":"Je hebt recht op maximaal 2 examenmogelijkheden (1 herkansing). Het rekenexamen wordt online aangeboden via Remindo in een examenlokaal. Je mag hierbij een rekenkaart en een rekenmachine gebruiken. De rekenkaart wordt uitgedeeld voor het examen en een rekenmachine zit in het programma, maar je mag ook om een fysieke rekenmachine vragen.","page":1},{"id":"bron-9-5","sourceId":"bron-9","title":"Routeplanner rekenen Landstede Harderwijk/Lelystad/Dronten","text":"De rekendocent kan je voor het rekenexamen eventueel laten oefenen met de Remindo toetsomgeving door bijvoorbeeld een kennismakingstoets of een proefexamen voor je klaar te zetten. Op de site van CEM (examensmbo.nl/downloads) vind je ook een aantal video’s met uitleg en voorbeeldexamens. De rekendocent kan je vooraf ook voorzien van tips die je helpen bij het maken van het rekenexamen.","page":1},{"id":"bron-9-6","sourceId":"bron-9","title":"Routeplanner rekenen Landstede Harderwijk/Lelystad/Dronten","text":"Smartrekenen (Eduhint) Bij Landstede Harderwijk/Lelystad/Dronten werken we met de online rekenmethode Smartrekenen van Eduhint. Je gaat met deze methode werken als uit de nulmeting blijkt dat je nog niet op het benodigde niveau zit. Deze rekenmethode behandelt alle domeinen (onderwerpen) die ook bij het rekenexamen worden gevraagd en bestaat uit 18 hoofdstukken.","page":2},{"id":"bron-9-7","sourceId":"bron-9","title":"Routeplanner rekenen Landstede Harderwijk/Lelystad/Dronten","text":"De docent zal uitleggen hoe de methode werkt en bepaalt hoeveel tijd je hieraan gaat besteden. Of je in Smartrekenen ook de eindtoetsen en domeintoetsen moet maken verschilt per docent. De rekendocent kan trouwens zien hoeveel en wat je per week gedaan hebt in Smartrekenen. Bij de meeste opleidingen staat rekenen ongeveer een uur per week op het rooster. Dit is meestal voldoende om in 1 jaar de hele methode te kunnen voltooien.","page":2},{"id":"bron-9-8","sourceId":"bron-9","title":"Routeplanner rekenen Landstede Harderwijk/Lelystad/Dronten","text":"Je kan versnellen binnen de methode. Je begint bijvoorbeeld telkens met een hoofdstuktoets en als je hierbij een score haalt van minimaal 80% dan kan je de bijbehorende paragrafen overslaan en gelijk door naar het volgende hoofdstuk. Dat schiet dan dus lekker op. Als je klaar bent met Smartrekenen zal de rekendocent je werk controleren en misschien nog een afsluitende voortgangstoets afnemen.","page":2},{"id":"bron-9-9","sourceId":"bron-9","title":"Routeplanner rekenen Landstede Harderwijk/Lelystad/Dronten","text":"Als dan blijkt dat je op niveau zit krijg je waarschijnlijk het advies je in te schrijven voor het rekenexamen. Net als bij het rekenexamen mag je ook bij het werken met Smartrekenen altijd de rekenkaart en een rekenmachine gebruiken. Bijles en extra faciliteiten Als je veel moeite hebt met rekenen zijn er mogelijkheden voor bijles en extra faciliteiten, zoals een gedeeld of begeleid examen.","page":2},{"id":"bron-9-10","sourceId":"bron-9","title":"Routeplanner rekenen Landstede Harderwijk/Lelystad/Dronten","text":"Of je voor bijles in aanmerking komt bepaalt de rekendocent en of je recht hebt op extra faciliteiten wordt bepaald door het SAB (via je rekendocent).","page":2},{"id":"bron-9-11","sourceId":"bron-9","title":"Routeplanner rekenen Landstede Harderwijk/Lelystad/Dronten","text":"Heb je nog vragen over rekenen? Schroom niet en stel ze aan je rekendocent of coach!","page":2},{"id":"bron-10-1","sourceId":"bron-10","title":"Aftekenboek Verpleegtechnische handelingen","text":"Aftekenboek Verpleegtechnische handelingen. “ Spelregels voor student en docent”","page":2},{"id":"bron-10-2","sourceId":"bron-10","title":"Skills","text":"Geen aftekenboekje geen handtekening! • In Bijlage 1 moeten alle handelingen voorzien zijn van naam docent, datum en hantekening docent. • Aan het eind van je opleiding moet dit ingeleverd worden bij de examen commisie. Ga daarom zorgvuldig om met dit boekje. • Je komt voorbereid je les in. Dit doe je door e-learnings, protocollen en opgeven theorie te maken en/of bustuderen.","page":2},{"id":"bron-10-3","sourceId":"bron-10","title":"Skills","text":"• Heb je theorielessen gemist dan overleg je met je theorie docent hoe dit in te halen. • Heb je praktijklessen gemist dan is het verplicht deze handeling(en) in te halen in de bufferweek.","page":2},{"id":"bron-10-4","sourceId":"bron-10","title":"Ouderdomspak","text":"Ondersteunen bij eten en/of drinken Hulp bieden aan een zorgvrager die niet zelf kan eten of drinken.","page":4},{"id":"bron-10-5","sourceId":"bron-10","title":"Ouderdomspak","text":"Aanleggen en bijhouden van persoonlijke vochtbalans (skills opdracht aan de hand van casus)","page":4},{"id":"bron-10-6","sourceId":"bron-10","title":"Ouderdomspak","text":"Ondersteunen bij de uitscheiding Hulp bieden bij het gebruik van een urinaal op bed","page":5},{"id":"bron-10-7","sourceId":"bron-10","title":"Beschrijving Vaardigheid Medisch rekenen","text":"Bloedglucose controle Sondevoeding toedienen kan opgedeeld worden in: met medisch rekenen","page":6},{"id":"bron-10-8","sourceId":"bron-10","title":"Beschrijving Vaardigheid Medisch rekenen","text":"Klaar maken van de 10L Cilinder • Zuurstof toedienen (met neusbril, neuskatheter, neuskatheter met spons, zuurstofmasker) • Aansluiten van bevochtiging • Ontluchten en opbergen van de cilinder","page":6},{"id":"bron-10-9","sourceId":"bron-10","title":"Beschrijving Vaardigheid Medisch rekenen","text":"Zuurstofcilinder • Concentrator • Zuurstof uit de muur, flowmeter EHBO & Reanimatie kan opgedeeld worden in:","page":6},{"id":"bron-10-10","sourceId":"bron-10","title":"Beschrijving Vaardigheid Medisch rekenen","text":"Buik naar rug draaien • Stabiele zijligging • Verplaatsingstechnieken (o.a Rauwtek techniek) • Brandwonden • Acute bloedingen • Vingerverband aanleggen • Stikken en verslikken, buikstoten (heimlich) • Verstuiken, verzwikken en kneuzingen • Heupfractuur • Vergiftiging • Bloedneus • Reanimatie + AED","page":6},{"id":"bron-10-11","sourceId":"bron-10","title":"Beschrijving Vaardigheid Medisch rekenen","text":"Bijlage 1: Aftekenlijst onderwijsproces van werkproces ‘Voert verpleegtechnische handelingen uit’ Verzorgende-IG","page":7},{"id":"bron-10-12","sourceId":"bron-10","title":"Beschrijving Vaardigheid Medisch rekenen","text":"Verpleegtechnische handeling Theorie behandeld Voor- en achternaam docent / instructeur, datum en handtekening","page":7},{"id":"bron-10-13","sourceId":"bron-10","title":"Beschrijving Vaardigheid Medisch rekenen","text":"Student beheerst de handeling Voor- en achternaam docent / instructeur, datum en handtekening Naam student: 1 Eerste hulp (somatisch) verlenen verwondingen, vergiftigingen, verstikking, verslikken","page":7},{"id":"bron-10-14","sourceId":"bron-10","title":"Verzorgen van een stoma","text":"* Voorbehouden handeling Alle handelingen moeten voorzien zijn van een handtekening Verplicht als examen in Prove2Move map + 4 handelingen naar keuze","page":8},{"id":"bron-11-1","sourceId":"bron-11","title":"Versie Juni 2024 Landstede Harderwijk Niveau 4","text":"Geen aftekenboekje geen handtekening! • In Bijlage 2 moeten alle handelingen voorzien zijn van naam docent, datum en hantekening docent. • Aan het eind van je opleiding moet dit ingeleverd worden bij de examen commisie. Ga daarom zorgvuldig om met dit boekje. • Je komt voorbereid je les in. Dit doe je door e-learnings, protocollen en opgeven theorie te maken en/of bustuderen.","page":2},{"id":"bron-11-2","sourceId":"bron-11","title":"Versie Juni 2024 Landstede Harderwijk Niveau 4","text":"• Heb je theorielessen gemist dan overleg je met je theorie docent hoe dit in te halen. • Heb je praktijklessen gemist dan is het verplicht deze handeling(en) in te halen in de bufferweek.","page":2},{"id":"bron-11-3","sourceId":"bron-11","title":"Algemene uitleg skills","text":"X Hygiënisch werken Handreiniging dmv zeep/handalcohol Isolatieverpleging","page":3},{"id":"bron-11-4","sourceId":"bron-11","title":"Algemene uitleg skills","text":"Creëren van een schoon of steriel werkveld Aan- en uittrekken van steriele handschoenen","page":3},{"id":"bron-11-5","sourceId":"bron-11","title":"Bedverzorging","text":"Het afhalen en opmaken van het bed zonder zorgvrager Het afhalen en opmaken van het bed met een zorgvrager die kan draaien Het opmaken van het bed met hulpmiddelen in en aan het bed","page":3},{"id":"bron-11-6","sourceId":"bron-11","title":"Ergonomisch werken Maakt gebruik van:","text":"Verplaatsen van een zorgvrager omhoog in bed mbv glijzeil en Trendelenburg/anti-Trendelenburg","page":3},{"id":"bron-11-7","sourceId":"bron-11","title":"Ondersteunen bij persoonlijke basiszorg","text":"Wasbeurt op bed Aan de wastafel, Douchen/bad Mondverzorging: eigen gebit Verzorging gebitsprothese Nagelverzorging Haarverzorging Scheren Oog- en oor verzorging Aan-en uitkleden","page":4},{"id":"bron-11-8","sourceId":"bron-11","title":"Therapeutische elastische kousen aantrekken","text":"Ondersteunen bij transfers Transfer met de passieve lift Transfer met de actieve lift Turner","page":4},{"id":"bron-11-9","sourceId":"bron-11","title":"Therapeutische elastische kousen aantrekken","text":"Ondersteunen bij het lopen met een rollator en looprekje Voortbewegen met behulp van een rolstoel Ouderdomspak","page":4},{"id":"bron-11-10","sourceId":"bron-11","title":"Therapeutische elastische kousen aantrekken","text":"Ondersteunen bij eten en/of drinken Hulp bieden aan een zorgvrager die niet zelf kan eten of drinken. Aanleggen en bijhouden van persoonlijke vochtbalans","page":4},{"id":"bron-11-11","sourceId":"bron-11","title":"Ondersteunen bij de uitscheiding","text":"Hulp bieden bij het gebruik van een urinaal op bed Hulp bieden bij het gebruik van een po op bed Aanbrengen en verwisselen van incontinentiemateriaal Het aanbrengen van een externe katheter Verzorgen van een blaaskatheter Verwisselen van een katheterzak Manueel verwijderen van ontlasting Opgeven van sputum Hulp bieden bij braken Hulp bieden bij menstruatie","page":5},{"id":"bron-11-12","sourceId":"bron-11","title":"Vitale functies","text":"Observatie van het bewustzijn Observatie en meten van de hartslag Observatie en meten van de bloeddruk Observatie en meten van de ademhaling Observatie en meten van de lichaamstemperatuur Observatie en meten van het lichaamsgewicht Observatie en meten van de lichaamslengte","page":5},{"id":"bron-11-13","sourceId":"bron-11","title":"Beschrijving Vaardigheid Medisch rekenen:","text":"Subcutaan huidplooi • Vleugelnaald (met verlengslang) • Insulinepen • Intramusculair - ventrogluteaal - rangeer - loodrecht","page":6},{"id":"bron-11-14","sourceId":"bron-11","title":"via pomp:","text":"Bolus • Intermitterend • Continue PEG-sonde Zuurstof kan opgedeeld worden in: met medisch rekenen","page":6},{"id":"bron-11-15","sourceId":"bron-11","title":"via pomp:","text":"Klaar maken van de 10L Cilinder • Zuurstof toedienen (met neusbril, neuskatheter, neuskatheter met spons, zuurstofmasker) • Aansluiten van bevochtiging • Ontluchten en opbergen van de cilinder","page":6},{"id":"bron-11-16","sourceId":"bron-11","title":"EHBO & Reanimatie kan opgedeeld worden in:","text":"Buik naar rug draaien • Stabiele zijligging • Verplaatsingstechnieken (o.a Rauwtek techniek) • Brandwonden • Acute bloedingen • Vingerverband aanleggen • Stikken en verslikken, buikstoten (heimlich) • Verstuiken, verzwikken en kneuzingen • Heupfractuur • Vergiftiging • Bloedneus • Reanimatie + AED","page":6},{"id":"bron-11-17","sourceId":"bron-11","title":"Versie Juni 2024 Landstede Harderwijk Niveau 4","text":"Bijlage 2: Aftekenlijst onderwijsproces van werkproces ‘Voert verpleegtechnische handelingen uit’ Mbo-Verpleegkundige","page":7},{"id":"bron-11-18","sourceId":"bron-11","title":"Versie Juni 2024 Landstede Harderwijk Niveau 4","text":"Verpleegtechnische handeling Theorie behandeld Voor- en achternaam docent / instructeur, datum en handtekening","page":7},{"id":"bron-11-19","sourceId":"bron-11","title":"Versie Juni 2024 Landstede Harderwijk Niveau 4","text":"Student beheerst de handeling Voor- en achternaam docent / instructeur, datum en handtekening","page":7},{"id":"bron-11-20","sourceId":"bron-11","title":"Intraveneus injecteren*","text":"Geneesmiddelen in opgeloste vorm toedienen via een infuussysteem/toedieningssysteem (pomp, kolf of zakje)","page":7},{"id":"bron-11-21","sourceId":"bron-11","title":"25 Maaghevel uitvoeren","text":"Verpleegtechnische handeling Theorie behandeld Voor- en achternaam docent / instructeur, datum en handtekening","page":8},{"id":"bron-11-22","sourceId":"bron-11","title":"25 Maaghevel uitvoeren","text":"Student beheerst de handeling Voor- en achternaam docent / instructeur, datum en handtekening","page":8},{"id":"bron-11-23","sourceId":"bron-11","title":"Hielprik bij neonaten*","text":"Verzamelen van monsters ten behoeve van diagnostiek (steriel en niet-steriel materiaal)","page":9},{"id":"bron-11-24","sourceId":"bron-11","title":"Hielprik bij neonaten*","text":"Alle handelingen moeten voorzien zijn van een handtekening. Verplicht als examen in Prove2Move map. Hiervan zijn 5 verpleegtechnische handelingen verplicht voor de verpleegkundige in de Prove2Move map. + 9 verpleegtechnische handelingen naar keuze.","page":9},{"id":"bron-12-1","sourceId":"bron-12","title":"Algemene handleiding","text":"Inhoud Algemene handleiding (voor het EPP) ........................................................................................... 9","page":2},{"id":"bron-12-2","sourceId":"bron-12","title":"Algemene handleiding","text":"Inleiding ......................................................................................................................................... 9","page":2},{"id":"bron-12-3","sourceId":"bron-12","title":"Algemene handleiding","text":"1. De examenproducten en het kwalificatiedossier ..................................................................... 9","page":2},{"id":"bron-12-4","sourceId":"bron-12","title":"Algemene handleiding","text":"2. Opbouw examenmap .............................................................................................................. 9","page":2},{"id":"bron-12-5","sourceId":"bron-12","title":"Algemene handleiding","text":"3. Onderdelen van de examenopdracht .................................................................................... 10","page":2},{"id":"bron-12-6","sourceId":"bron-12","title":"Algemene handleiding","text":"4. Toelichting op de beoordelingscriteria ................................................................................... 11","page":2},{"id":"bron-12-7","sourceId":"bron-12","title":"Algemene handleiding","text":"5. Beoordelingssystematiek ...................................................................................................... 11","page":2},{"id":"bron-12-8","sourceId":"bron-12","title":"Algemene handleiding","text":"6. Complexiteit en zelfstandigheid ............................................................................................. 12","page":2},{"id":"bron-12-9","sourceId":"bron-12","title":"Algemene handleiding","text":"6.1 Complexiteit ................................................................................................................... 12","page":2},{"id":"bron-12-10","sourceId":"bron-12","title":"Algemene handleiding","text":"6.2 Zelfstandigheid .............................................................................................................. 13","page":2},{"id":"bron-12-11","sourceId":"bron-12","title":"Algemene handleiding","text":"7. Algemene begrippen ............................................................................................................. 13","page":2},{"id":"bron-12-12","sourceId":"bron-12","title":"Algemene handleiding","text":"8. Instructie beoordelaar ........................................................................................................... 14","page":2},{"id":"bron-12-13","sourceId":"bron-12","title":"Algemene handleiding","text":"9. Instructie student .................................................................................................................. 14","page":2},{"id":"bron-12-14","sourceId":"bron-12","title":"Algemene handleiding","text":"bijlage 1: Richtlijn voor het bepalen van complexiteit van zorg (alleen voor Verzorgende-IG en Mbo-Verpleegkundige) ................................................................................................................. 15","page":2},{"id":"bron-12-15","sourceId":"bron-12","title":"Inleiding","text":"Deze algemene handleiding bevat informatie over de uitvoering en beoordeling van de examenopdrachten. Door het afleggen van de examenopdrachten wordt de bekwaamheid van de student aangetoond. De resultaten van de examenopdrachten tellen mee voor het behalen van het diploma. Met andere woorden: de examenopdrachten zijn kwalificerend. De onderwijsinstelling heeft gekozen voor de examenopdrachten van examenleverancier Prove2Move.","page":3},{"id":"bron-12-16","sourceId":"bron-12","title":"Inleiding","text":"Prove2Move ontwikkelt examenopdrachten voor het beroepsgerichte deel van verschillende opleidingen in het mbo. Daar waar in de examenmap hij staat, kan ook zij gelezen worden en andersom.","page":3},{"id":"bron-12-17","sourceId":"bron-12","title":"Inleiding","text":"In een kwalificatiedossier staan beroepen beschreven waar het mbo voor opleidt. De examenproducten dekken het beroepsspecifieke deel van het kwalificatiedossier. De kwalificatiedossiers bevatten een basisdeel en soms een profieldeel. Het kwalificatiedossier kent kerntaken en werkprocessen.","page":3},{"id":"bron-12-18","sourceId":"bron-12","title":"Inleiding","text":"De kerntaken en werkprocessen uit het basisdeel van het kwalificatiedossier worden aangeduid met bijvoorbeeld: B1-K1-W1 (Basisdeel 1 - Kerntaak 1 - Werkproces 1). De kerntaken en werkprocessen uit het profieldeel (indien aanwezig) van het kwalificatiedossier worden aangeduid met bijvoorbeeld: P3-K1-W2 (Profiel 3 - Kerntaak 1 - Werkproces 2).","page":3},{"id":"bron-12-19","sourceId":"bron-12","title":"Inleiding","text":"Ieder werkproces wordt één keer geëxamineerd op het niveau van een beginnend beroepsbeoefenaar. Het totaaloverzicht laat zien welke kerntaken en werkprocessen binnen welke examenopdracht worden geëxamineerd. Ook wordt hier aangegeven of het een profielonafhankelijk examen, een profielafhankelijk examen of een lintexamen betreft.","page":3},{"id":"bron-12-20","sourceId":"bron-12","title":"Inleiding","text":"Profielonafhankelijk examen De profielonafhankelijke examenopdrachten examineren alleen kerntaken en werkprocessen uit het basisdeel van het kwalificatiedossier.","page":3},{"id":"bron-12-21","sourceId":"bron-12","title":"Inleiding","text":"Profielafhankelijk examen De profielafhankelijke examenopdrachten examineren kerntaken en werkprocessen die gelden voor een specifieke beroepscontext. Hierin kunnen combinaties van profiel- en basiswerkprocessen voorkomen. De keuzes voor combinaties van profiel- en basiswerkprocessen zijn gebaseerd op de werksituaties in de beroepspraktijk.","page":3},{"id":"bron-12-22","sourceId":"bron-12","title":"Inleiding","text":"Lintexamen Aan lintexamenopdrachten wordt gedurende een langere periode gewerkt. De student rondt (een deel van) de examenopdracht af wanneer de examensituatie zich voordoet. Lintexamenopdrachten zijn meestal profielonafhankelijk.","page":3},{"id":"bron-12-23","sourceId":"bron-12","title":"Inleiding","text":"Toetsvormen De volgende toetsvormen kunnen voorkomen: • praktijkexamen • simulatie • criteriumgericht interview (cgi) aan de hand van verzamelde bewijsstukken","page":3},{"id":"bron-12-24","sourceId":"bron-12","title":"Een examenopdracht bestaat uit de volgende onderdelen:","text":"Inleiding Hierin wordt de beroepscontext beschreven waarbinnen het examen plaatsvindt. De inleiding zegt iets over het uitoefenen van het beroep in de beschreven beroepspraktijk.","page":4},{"id":"bron-12-25","sourceId":"bron-12","title":"Een examenopdracht bestaat uit de volgende onderdelen:","text":"Kerntaken en werkprocessen In de examenopdracht worden de hier vermelde kernta(a)k(en) en werkproces(sen) geëxamineerd.","page":4},{"id":"bron-12-26","sourceId":"bron-12","title":"Een examenopdracht bestaat uit de volgende onderdelen:","text":"Opdracht In de opdracht staat kort beschreven wat de student tijdens het examen moet doen.","page":4},{"id":"bron-12-27","sourceId":"bron-12","title":"Een examenopdracht bestaat uit de volgende onderdelen:","text":"Afnamecondities Bij de afnamecondities worden toetsvorm, examentijd en eventuele bijzonderheden beschreven.","page":4},{"id":"bron-12-28","sourceId":"bron-12","title":"Een examenopdracht bestaat uit de volgende onderdelen:","text":"● toetsvorm: de manier waarop de examenopdracht wordt afgenomen ● examentijd: in overleg met de begeleider en/of de beoordelaar wordt de duur van het examen bepaald. Wat binnen de betreffende beroepspraktijk gebruikelijk is, is leidend voor de duur van het examen. De in de examenopdracht aangegeven tijd is de maximale tijdsduur. ● bijzonderheden: hier kunnen voor de opdracht specifieke voorwaarden en/of aanwijzingen worden benoemd.","page":4},{"id":"bron-12-29","sourceId":"bron-12","title":"Een examenopdracht bestaat uit de volgende onderdelen:","text":"Uitvoering Bij de uitvoering wordt in volgorde beschreven wat de student tijdens de uitvoering van de examenopdracht moet doen.","page":4},{"id":"bron-12-30","sourceId":"bron-12","title":"Een examenopdracht bestaat uit de volgende onderdelen:","text":"In de uitvoeringsstappen worden geen aantallen zorgvragers, cliënten, klanten en/of kinderen genoemd. Aantallen worden in overleg met de begeleider en/of beoordelaar bepaald, tenzij hierover iets in de bijzonderheden bij de afnamecondities is opgenomen. De betreffende beroepspraktijk is hierin leidend.","page":4},{"id":"bron-12-31","sourceId":"bron-12","title":"Een examenopdracht bestaat uit de volgende onderdelen:","text":"Beoordelingsformulier inclusief Bewijs van bekwaamheid Het beoordelingsformulier bevat de criteria waarop de student wordt beoordeeld. Hierin wordt beschreven hoe de student de examenopdracht dient uit te voeren. In het beoordelingsformulier is de cesuur verwerkt. Het resultaat van de examenopdracht wordt vermeld als onvoldoende/voldoende/goed.","page":4},{"id":"bron-12-32","sourceId":"bron-12","title":"Algemene handleiding","text":"In het beoordelingsformulier zijn drie vormen van beoordelingscriteria te onderscheiden:","page":5},{"id":"bron-12-33","sourceId":"bron-12","title":"Algemene handleiding","text":"Zien: Aan de hand van deze criteria observeert de beoordelaar de student. Het gaat hier om wat de beoordelaar de student ziet en hoort doen tijdens de uitvoering van de examenopdracht.","page":5},{"id":"bron-12-34","sourceId":"bron-12","title":"Algemene handleiding","text":"Lezen: Aan de hand van deze criteria beoordeelt de beoordelaar een schriftelijke uitwerking van de student, zoals bijvoorbeeld een handelingsplan of een rapportage.","page":5},{"id":"bron-12-35","sourceId":"bron-12","title":"Algemene handleiding","text":"Horen: Aan de hand van deze criteria stelt de beoordelaar vragen aan de student. De beoordelaar vraagt van de student, op basis van het beoordelingscriterium, een mondelinge verantwoording. De verantwoording gaat altijd over het vertoonde gedrag en/of over een product, gemaakt tijdens de uitvoering van de examenopdracht.","page":5},{"id":"bron-12-36","sourceId":"bron-12","title":"Algemene handleiding","text":"Hiermee kunnen keuzes of afwegingen duidelijk worden gemaakt of kan de redenering achter een bepaald plan verantwoord worden. De beoordelaar kan beoordelen of de student met kennis van zaken heeft gehandeld.","page":5},{"id":"bron-12-37","sourceId":"bron-12","title":"Algemene handleiding","text":"Per examenopdracht worden drie prestatieniveaus onderscheiden: goed, voldoende en onvoldoende.","page":5},{"id":"bron-12-38","sourceId":"bron-12","title":"Algemene handleiding","text":"Ieder beoordelingscriterium wordt aan de hand van onderstaande ratingschaal (0, 1, 2, 3) beoordeeld.","page":5},{"id":"bron-12-39","sourceId":"bron-12","title":"De student heeft het genoemde beoordelingscriterium:","text":"Opgeteld leiden de punten tot een score voor de opdracht, die vervolgens wordt omgezet in een beoordeling.","page":5},{"id":"bron-12-40","sourceId":"bron-12","title":"De student heeft het genoemde beoordelingscriterium:","text":"Als dit gebeurt dan is je opdracht onvoldoende. ● Je mag voor maximaal 10% van de beoordelingscriteria een 1 scoren om de opdracht met een positief resultaat af te ronden. ● Scores onder de ondergrens voor ‘voldoende’ resulteren in een beoordeling ‘onvoldoende’. ● De opdracht sluit je af met een ‘goed’ als je 4/5 van het maximaal aantal te behalen punten hebt gescoord. ● Afronden: De score 0,5 en hoger wordt afgerond naar boven = 1.","page":5},{"id":"bron-12-41","sourceId":"bron-12","title":"De student heeft het genoemde beoordelingscriterium:","text":"De score lager dan 0,5 wordt afgerond naar beneden = 0. ● Per opdracht is steeds vermeld waar de grens ligt tussen een goed, voldoende en onvoldoende.","page":5},{"id":"bron-12-42","sourceId":"bron-12","title":"Voorbeeld (met 15 beoordelingscriteria):","text":"● Maximale totaalscore = 45 punten (15 x score 3) ● Maximaal aantal criteria met score 1 = 2 (10% van 15 = 1,5 = afgerond 2) ● Minimale score voor voldoende = 28 punten (13 x score 2 + 2 x score 1= 28 punten) ● Minimale score voor goed = 36 (4/5 van 45 punten)","page":6},{"id":"bron-12-43","sourceId":"bron-12","title":"Voorbeeld (met 15 beoordelingscriteria):","text":"Het kwalificatiedossier kent kerntaken. Elke kerntaak moet een beoordeling krijgen. Ook hier geldt: heb je 4/5 van de opdrachten behorende bij de kerntaak met een ‘goed’ behaald, dan krijgt de kerntaak de beoordeling ‘goed’.","page":6},{"id":"bron-12-44","sourceId":"bron-12","title":"Voorbeeld (met 15 beoordelingscriteria):","text":"Hieronder staat een beschrijving van de begrippen complexiteit en zelfstandigheid gekoppeld aan het niveau van een beginnend beroepsbeoefenaar. Hierbij wordt onderscheid gemaakt tussen niveaus van complexiteit en zelfstandigheid, passend bij de examencontext van de student. De indeling is als volgt:","page":6},{"id":"bron-12-45","sourceId":"bron-12","title":"Voorbeeld (met 15 beoordelingscriteria):","text":"● Lage complexiteit en zelfstandigheid (opleidingsniveau 1 en 2) ● Gemiddelde complexiteit en zelfstandigheid (opleidingsniveau 3) ● Hoge complexiteit en zelfstandigheid (opleidingsniveau 4)","page":6},{"id":"bron-12-46","sourceId":"bron-12","title":"6.1 Complexiteit","text":"De context is herkenbaar, overzichtelijk en de werkzaamheden worden uitgevoerd in een bekende situatie","page":6},{"id":"bron-12-47","sourceId":"bron-12","title":"6.1 Complexiteit","text":"De context is herkenbaar en de werkzaamheden kunnen in wisselende situaties plaatsvinden","page":6},{"id":"bron-12-48","sourceId":"bron-12","title":"6.1 Complexiteit","text":"De context kan onbekend zijn en de werkzaamheden worden uitgevoerd in wisselende en nieuwe situaties","page":6},{"id":"bron-12-49","sourceId":"bron-12","title":"Toepassen van standaardprocedures","text":"De standaardprocedures moeten in wisselende situaties worden aangepast","page":6},{"id":"bron-12-50","sourceId":"bron-12","title":"Toepassen van standaardprocedures","text":"Er kan een standaard aanpak zijn maar indien van toepassing worden nieuwe procedures toegepast/bedacht","page":6},{"id":"bron-12-51","sourceId":"bron-12","title":"Is gedeeltelijk verantwoordelijk voor het resultaat van anderen","text":"Werkt monodisciplinair Werkt multidisciplinair Werkt multidisciplinair en heeft in voorkomende situaties een coördinerende rol","page":6},{"id":"bron-12-52","sourceId":"bron-12","title":"Is gedeeltelijk verantwoordelijk voor het resultaat van anderen","text":"Tijdens de werkzaamheden worden basiskennis en -vaardigheden toegepast","page":6},{"id":"bron-12-53","sourceId":"bron-12","title":"Is gedeeltelijk verantwoordelijk voor het resultaat van anderen","text":"Tijdens de werkzaamheden worden specialistische kennis en vaardigheden toegepast","page":6},{"id":"bron-12-54","sourceId":"bron-12","title":"Is gedeeltelijk verantwoordelijk voor het resultaat van anderen","text":"Tijdens de werkzaamheden worden brede en specialistische kennis en vaardigheden toegepast","page":6},{"id":"bron-12-55","sourceId":"bron-12","title":"Een beginnend beroepsbeoefenaar:","text":"krijgt instructie, werkt onder begeleiding en/of toezicht en overlegt over te maken keuzes;","page":7},{"id":"bron-12-56","sourceId":"bron-12","title":"Een beginnend beroepsbeoefenaar:","text":"heeft vrijheid van handelen binnen vastgestelde kaders en wijkt waar nodig onderbouwd af;","page":7},{"id":"bron-12-57","sourceId":"bron-12","title":"Een beginnend beroepsbeoefenaar:","text":"niveau 1: is met begeleiding verantwoordelijk voor het resultaat van eigen, afgebakende, eenvoudige werkzaamheden;","page":7},{"id":"bron-12-58","sourceId":"bron-12","title":"Een beginnend beroepsbeoefenaar:","text":"niveau 2: is verantwoordelijk voor het resultaat van eigen, afgebakende, eenvoudige werkzaamheden;","page":7},{"id":"bron-12-59","sourceId":"bron-12","title":"Een beginnend beroepsbeoefenaar:","text":"is verantwoordelijk voor het resultaat van eigen, afgebakende werkzaamheden;","page":7},{"id":"bron-12-60","sourceId":"bron-12","title":"Een beginnend beroepsbeoefenaar:","text":"Bronnen: Bulthuis, P.H. (2013), De samenhang tussen zelfstandigheid en complexiteit. Het ZelCommodel, grip op competentieniveaus. Examens, 2013 (2), 5 -10.","page":7},{"id":"bron-12-61","sourceId":"bron-12","title":"Een beginnend beroepsbeoefenaar:","text":"NLQF. Het Nederlands Kwalificatieraamwerk NLQF. Geraadpleegd op 30 oktober 2020, van [webadres: zie officieel systeem]","page":7},{"id":"bron-12-62","sourceId":"bron-12","title":"Een beginnend beroepsbeoefenaar:","text":"Op de website is een lijst opgenomen met begrippen die gebruikt worden in de examenopdrachten. Deze lijst is te vinden op www.prove2move.nl onder ‘Examens’.","page":7},{"id":"bron-12-63","sourceId":"bron-12","title":"Voorbereiding op de beoordeling van het examen","text":"● Lees de algemene handleiding en de instructie voor de student door. ● Lees de examenopdracht en de beoordelingscriteria door. ● Bespreek met de student de afnamecondities. ● Spreek de start van het examen af en vul dit in op het beoordelingsformulier.","page":8},{"id":"bron-12-64","sourceId":"bron-12","title":"Uitvoering van de beoordeling van het examen","text":"● Geef tijdens de uitvoering van de examenopdracht geen aanwijzingen, tips of handreikingen aan de student. ● Volg de student tijdens de uitvoering van de examenopdracht en maak aantekeningen. ● Zorg voor voldoende beoordelingsmomenten om een onderbouwde beoordeling van de beoordelingscriteria te kunnen geven en een rechtvaardige uitspraak te kunnen doen over het functioneren van de student tijdens de uitvoering van ","page":8},{"id":"bron-12-65","sourceId":"bron-12","title":"Uitvoering van de beoordeling van het examen","text":"het examen. ● Grijp in bij een ongewenste situatie en stop het examen*. ● Noteer bij meerdere beoordelaars alle namen ● Vul het beoordelingsformulier volledig in.","page":8},{"id":"bron-12-66","sourceId":"bron-12","title":"Uitvoering van de beoordeling van het examen","text":"Zorg bij meerdere beoordelaars voor consensus over de beoordelingscriteria. ● Beschrijf in het toelichtingskader van het beoordelingsformulier welk concreet gedrag heeft geleid tot de beoordeling. ● Licht de beoordeling mondeling toe. ● Stuur het beoordelingsformulier in","page":8},{"id":"bron-12-67","sourceId":"bron-12","title":"Voorbereiding op het examen","text":"● Lees de algemene handleiding door zodat je weet hoe de examinering is opgebouwd en wat er van iedereen verwacht wordt bij de uitvoering van de examenopdrachten. ● Lees de examenopdracht en de beoordelingscriteria door. ● Maak een afspraak met de beoordelaar nadat deze digitaal is uitgenodigd. Bespreek de afnamecondities die bij de examenopdracht horen. ● Spreek af met je beoordelaar wanneer je de examenopdracht uit gaat voeren.","page":8},{"id":"bron-12-68","sourceId":"bron-12","title":"Uitvoering van het examen","text":"● Voer de examenopdracht uit zoals in de uitvoering beschreven is. ● Let op dat alle beoordelingscriteria worden beoordeeld. ● Laat het beoordelingsformulier invullen door de beoordelaar ● Ontvang de schriftelijke en mondelinge onderbouwing van de beoordelaar. ● Controleer de beoordeling en bevestig deze met de button ‘voor gezien’.","page":8},{"id":"bron-12-69","sourceId":"bron-12","title":"Algemene handleiding","text":"bijlage 1: Richtlijn voor het bepalen van complexiteit van zorg (alleen voor Verzorgende-IG en Mbo-Verpleegkundige)","page":9},{"id":"bron-12-70","sourceId":"bron-12","title":"Stabiliteit van de zorgsituatie","text":"Gezondheidstoestand en gedrag is stabiel, wisselt beperkt en is voorspelbaar","page":9},{"id":"bron-12-71","sourceId":"bron-12","title":"Stabiliteit van de zorgsituatie","text":"Gezondheidstoestand en gedrag zijn redelijk voorspelbaar; er is maximaal twee keer per dag herziening van de zorgplanning nodig","page":9},{"id":"bron-12-72","sourceId":"bron-12","title":"Stabiliteit van de zorgsituatie","text":"Gezondheidstoestand en gedrag zijn sterk wisselend en onvoorspelbaar; er is voortdurend herziening van de zorgplanning nodig","page":9},{"id":"bron-12-73","sourceId":"bron-12","title":"Meervoudige problematiek","text":"Eén of twee soorten problemen of handicaps (somatisch en/of psychisch), die elkaar nauwelijks beïnvloeden","page":9},{"id":"bron-12-74","sourceId":"bron-12","title":"Meervoudige problematiek","text":"Maximaal twee soorten problemen of handicaps (somatisch en/of psychisch), die elkaar kunnen beïnvloeden","page":9},{"id":"bron-12-75","sourceId":"bron-12","title":"Meervoudige problematiek","text":"Er zijn drie of meer soorten problemen of handicaps (somatisch en/of psychisch), die elkaar kunnen beïnvloeden","page":9},{"id":"bron-12-76","sourceId":"bron-12","title":"Samenwerking met vier of meer andere disciplines","text":"Gemotiveerdheid Gemotiveerd, of eenvoudig te motiveren tot het volgen van behandeling","page":9},{"id":"bron-12-77","sourceId":"bron-12","title":"Samenwerking met vier of meer andere disciplines","text":"De motivatie voor het volgen van de behandeling wordt door angst en/of onzekerheid beperkt","page":9},{"id":"bron-12-78","sourceId":"bron-12","title":"Samenwerking met vier of meer andere disciplines","text":"De patiënt is niet of nauwelijks gemotiveerd en niet of nauwelijks te motiveren tot het volgen van de behandeling","page":9},{"id":"bron-12-79","sourceId":"bron-12","title":"Begeleiding mantelzorg","text":"Geen begeleiding van mantelzorg nodig; de patiënt informeert zijn mantelzorgers over zijn toestand en behandeling","page":9},{"id":"bron-12-80","sourceId":"bron-12","title":"Begeleiding mantelzorg","text":"Mantelzorg behoeft aandacht en inspanning tijdens bezoekuren en geplande gesprekken met arts en andere disciplines","page":9},{"id":"bron-12-81","sourceId":"bron-12","title":"Begeleiding mantelzorg","text":"Bronvermelding: Hogeschool van Amsterdam, HBO-Verpleegkunde (2012). CanMEDS, Competentieset van de HBO-V, geraadpleegd op 23 september 2015 [webadres: zie officieel systeem] vpk/stagedocumenten-aiz/jaar-3/competenties-jaar-3/16-17-boekje-canmeds- competentiemodel-hbov.pdf?1467970131654","page":9},{"id":"bron-13-1","sourceId":"bron-13","title":"Reflectiemethode: ABCD-methode","text":"A = Aandachtspunten Blik terug en beschrijf de ervaring/situatie en de aspecten die je het meest zijn bijgebleven. Hulpvragen die je in je antwoord kunt verwerken: Wat was de ervaring? Wat heb ik gedaan? Op welke manier? Welke bedoeling had ik ermee? Wat wilde ik dat er ging gebeuren? Wie waren er allemaal bij betrokken? Hoe heb ik het beleefd? Welke gedachte dringt zich als eerste aan mij op? Waar zat mijn twijfel?","page":null},{"id":"bron-13-2","sourceId":"bron-13","title":"Reflectiemethode: ABCD-methode","text":"Heb ik verwondering of verbazing ervaren? Wanneer dacht ik ‘aha’ (aha-erlebnis)? Welk dilemma heb ik ervaren? Waarbij voelde ik weerstand of irritatie? Wat vond ik interessant? Wat maakte me blij of juist wanhopig?","page":null},{"id":"bron-13-3","sourceId":"bron-13","title":"Reflectiemethode: ABCD-methode","text":"B = Betekenis voor mij Beschrijf welke betekenis het bovenstaande voor jou heeft. Hulpvragen die je in je antwoord kunt verwerken: Wat zegt dit over mij? Wat vind ik belangrijk? Welke normen/waarden/overtuigingen/opvattingen herken ik bij mezelf? Waar werd ik mij bewust van? Welke verwachtingen heb ik van mezelf en van anderen? Kan ik ook anders naar de situatie kijken? Wat zegt dit over andere betrokkenen? En over hun verwachtingen?","page":null},{"id":"bron-13-4","sourceId":"bron-13","title":"Reflectiemethode: ABCD-methode","text":"Hun leren, ontwikkeling, beleving en hun normen/ waarden/ opvattingen/ overtuigingen?","page":null},{"id":"bron-13-5","sourceId":"bron-13","title":"Reflectiemethode: ABCD-methode","text":"C = Consequentie Beschrijf welke conclusie je trekt en welke alternatieven en/of handvatten je ziet ter verbetering Hulpvragen die je in je antwoord kunt verwerken: Welke inzichten heb je nu? Zie je een leermoment voor jezelf? Wat betekent dat voor jou/anderen? Waar zou je meer over willen weten? Zie je alternatieven? Welke kansen zie je in deze alternatieven?","page":null},{"id":"bron-13-6","sourceId":"bron-13","title":"Reflectiemethode: ABCD-methode","text":"Welke belemmeringen hebben deze alternatieven (ja maar…) Wat zie je andere mensen in zo’n situatie doen? Wat staat je nu te doen? Welke eerste stap zou je kunnen zetten? Waar zie je tegenop, wat houd je tegen?","page":null},{"id":"bron-13-7","sourceId":"bron-13","title":"Reflectiemethode: ABCD-methode","text":"D = Doen Beschrijf welke actie je de volgende keer gaat ondernemen. Hulpvragen die je in je antwoord kunt verwerken: Wanneer ga ik de eerste stap nemen? Wat wil ik precies doen? Wat moet er gebeuren wil ik tevreden kunnen zijn (haalbaar houden)? Hoe kan ik het aanpakken? Heb ik iemand nodig om me daarbij te helpen, zo ja hoe organiseer ik die ondersteuning?","page":null},{"id":"bron-13-8","sourceId":"bron-13","title":"Reflectiemethode: ABCD-methode","text":"En onthoud... Soms gaan veranderingen of gaat je handelen aanpassen om kleine stapjes… En gaat het om uitgebreide leerpunten, kan je het ook in je POP verwerken!","page":null},{"id":"bron-14-1","sourceId":"bron-14","title":"Reflectiemethode: de STARRT-reflectiemethode","text":"Beschrijf en reflecteer op een situatie aan de hand van de onderstaande STARRT-reflectievragen.","page":null},{"id":"bron-14-2","sourceId":"bron-14","title":"Reflectiemethode: de STARRT-reflectiemethode","text":"Situatie: Beschrijf de situatie. Denk aan: Wat gebeurde er? Wie waren erbij betrokken? Waar speelde de situatie zich af? Wanneer speelde deze situatie?","page":null},{"id":"bron-14-3","sourceId":"bron-14","title":"Reflectiemethode: de STARRT-reflectiemethode","text":"Taak: Beschrijf wat jouw taak/rol/aandeel in de situatie Denk aan: Wat was jouw taak en/of rol in deze situatie? Wat werd er van je verwacht? Wat wilde jij bereiken? Wat was jouw doel? Wat verwachtte je van jezelf in die situatie/taak? Wat vond je dat je moest doen?","page":null},{"id":"bron-14-4","sourceId":"bron-14","title":"Reflectiemethode: de STARRT-reflectiemethode","text":"Actie: Beschrijf wat je concreet zei of deed. Denk aan: Hoe was je aanpak? En wat gebeurde er toen, welk effect had dit? Wat deed je toen je dit effect merkte? Hoe reageerde(n) de ander(en) op jou? Wat heb je vervolgens gezegd en/of gedaan? En toen?","page":null},{"id":"bron-14-5","sourceId":"bron-14","title":"Reflectiemethode: de STARRT-reflectiemethode","text":"Resultaat: Beschrijf het resultaat; hoe liep de situatie af? Denk aan: Wat kwam eruit? Hoe is het afgelopen? Wat was het gevolg van je actie/ handelen? Hoe reageerde de ander(en) op dit resultaat?","page":null},{"id":"bron-14-6","sourceId":"bron-14","title":"Reflectiemethode: de STARRT-reflectiemethode","text":"Reflectie: Beschrijf hoe je op de situatie terugkijkt. Denk aan: Hoe vond je (achteraf) dat jij het deed? Ben je tevreden met het resultaat? Wat ging goed? Wat kon beter of anders? Wat leer je hiervan? Wat zegt dit over jouw beroepscompetenties en/of beroepshouding in deze situatie?","page":null},{"id":"bron-14-7","sourceId":"bron-14","title":"Reflectiemethode: de STARRT-reflectiemethode","text":"Transfer: Beschrijf wat je hebt geleerd voor een volgende keer. Denk aan: Wat zijn eyeopeners voor je? Wat leer je hieruit en kan je gebruiken in een nieuwe situatie? Hoe ga je dat aanpakken? Wat heb je nodig om jezelf in deze ‘eyeopener’ te ontwikkelen? Wat heb je nodig om je in de genoemde beroepscompetenties en/of beroepshouding verder te ontwikkelen?","page":null},{"id":"bron-15-1","sourceId":"bron-15","title":"Reflectiemethode: Reflectiespiraal van Korthagen","text":"Fase 1: Wat was de situatie? (objectief) Beschrijf de situatie/wat er gebeurd is/jouw leerdoel en jouw handelen concreet.","page":null},{"id":"bron-15-2","sourceId":"bron-15","title":"Reflectiemethode: Reflectiespiraal van Korthagen","text":"Fase 2: Wat gebeurde er toen? (subjectief) Beschrijf jouw ervaring (wat voelde en/of dacht je?) Beschrijf dit van jezelf en de evt. andere partij(en)).","page":null},{"id":"bron-15-3","sourceId":"bron-15","title":"Reflectiemethode: Reflectiespiraal van Korthagen","text":"Fase 3: Analyse Beschrijf essentiële (belangrijke) aspecten; wat ging goed en wat kon beter? Beschrijf wat dit nu voor jou betekent en wat het probleem/positieve ontdekking is.","page":null},{"id":"bron-15-4","sourceId":"bron-15","title":"Reflectiemethode: Reflectiespiraal van Korthagen","text":"Fase 4: Alternatieven ontwikkelen: conclusie & actieplan Beschrijf welke alternatieven je ziet (oplossingen/manieren om je positieve ontdekking te gebruiken). Wat ga je een volgende keer anders doen? Wat neem je je voor?","page":null},{"id":"bron-16-1","sourceId":"bron-16","title":"Algemeen:","text":"Toetsen medisch rekenen vinden plaats in een aparte digitale omgeving waar de student zich van tevoren voor moet aanmelden.","page":null},{"id":"bron-16-2","sourceId":"bron-16","title":"Algemeen:","text":"Na het aanmelden zal de Medisch rekenen commissie de student koppelen aan een opleiding, waarna het voor de student mogelijk is om zelf een toets moment te plannen","page":null},{"id":"bron-16-3","sourceId":"bron-16","title":"Algemeen:","text":"De toetsen vinden plaats in week 5 (herkansingsweek) van iedere periode en in elke bufferweek op maandag tot en met vrijdag van 16:00 – 17:00 uur.","page":null},{"id":"bron-16-4","sourceId":"bron-16","title":"Algemeen:","text":"Bijzondere dagen (vakantie, afwezigheid docenten) worden meegenomen in het rooster.","page":null},{"id":"bron-16-5","sourceId":"bron-16","title":"Algemeen:","text":"Het aantal vragen per toets is variabel: voor nu geldt: 10 vragen voor VIG en 16 vragen voor VP.","page":null},{"id":"bron-16-6","sourceId":"bron-16","title":"Inschrijven voor de toets(en):","text":"Let zelf goed op wanneer je je inschrijft! Je krijgt geen bevestigingsmail. Er is geen wijziging meer mogelijk! Je kunt op je eigen dashboard wel terugzien wanneer je je hebt ingeschreven.","page":null},{"id":"bron-16-7","sourceId":"bron-16","title":"Inschrijven voor de toets(en):","text":"Je kunt je per toets moment meerdere toetsen maken: indien je dus nog een tweede (of derde, vierde) toets wilt maken kun je dit ter plekke tijdens het toets moment aanklikken: LET OP: je hebt maar max 1 uur voor alle toetsen, om 17:00 uur eindigt de toets tijd: niet af is een onvoldoende!)","page":null},{"id":"bron-16-8","sourceId":"bron-16","title":"Inschrijven voor de toets(en):","text":"Het is alleen mogelijk de toets te maken op de datum dat je je hebt ingeschreven, mocht je op een andere dag komen, omdat je je bijvoorbeeld vergist, dan kun je geen toets maken.","page":null},{"id":"bron-16-9","sourceId":"bron-16","title":"Inschrijven voor de toets(en):","text":"De locatie wordt in het toets rooster vermeld, deze hangt op het lesplein.","page":null},{"id":"bron-16-10","sourceId":"bron-16","title":"Tijdens de toets:","text":"De presentielijst wordt doorgenomen tijdens het toets moment. De surveillant ziet hierop toe. Indien niet aanwezig zal de toets niet open worden gezet en kan de student de toets ook niet maken.","page":null},{"id":"bron-16-11","sourceId":"bron-16","title":"Tijdens de toets:","text":"De surveillant deelt kladblaadjes uit, je maakt dus geen gebruik van eigen aantekeningen.","page":null},{"id":"bron-16-12","sourceId":"bron-16","title":"Tijdens de toets:","text":"Je neemt je eigen rekenmachine en eigen laptop mee (het gebruik van de rekenmachine op laptop/telefoon is niet toegestaan)","page":null},{"id":"bron-16-13","sourceId":"bron-16","title":"Tijdens de toets:","text":"De formulekaart: je krijgt tijdens de toets een uitgeprint exemplaar van de surveillant.","page":null},{"id":"bron-16-14","sourceId":"bron-16","title":"Tijdens de toets:","text":"Je hoeft voor de toets alleen het antwoord in te vullen, berekeningen tellen niet mee.","page":null},{"id":"bron-16-15","sourceId":"bron-16","title":"Tijdens de toets:","text":"Indien de toets onverhoopt toch niet klaarstaat ondanks juiste inschrijving: dan wordt in overleg met de medisch rekenen commissie (Bernice, Sandra en Annemieke) een nieuwe gelegenheid geboden. Dan geldt voor jou geen gemiste kans.","page":null},{"id":"bron-16-16","sourceId":"bron-16","title":"Je krijgt meteen het resultaat te zien","text":"Op het toetsmoment zelf is er geen gelegenheid om de toets in te zien: je dient hiervoor een afspraak te maken met Annemieke Groenendijk of Sandra de Lange.","page":null},{"id":"bron-16-17","sourceId":"bron-16","title":"Je krijgt meteen het resultaat te zien","text":"Indien de student denkt dat hij/zij het kan en tijd genoeg heeft: hij/zij kan meteen een andere MR toets maken","page":null},{"id":"bron-16-18","sourceId":"bron-16","title":"Je krijgt meteen het resultaat te zien","text":"Op je dashboard worden meteen de resultaten verwerkt: groen is gehaald, rood is onvoldoende (blauw is gepland: indien je een individuele afspraak hebt gemaakt na POP en PAP)","page":null},{"id":"bron-16-19","sourceId":"bron-16","title":"Je krijgt meteen het resultaat te zien","text":"Bij 3 keer een onvoldoende resultaat dien je contact op te nemen met je coach: er wordt een POP en PAP van je gevraagd, waarna er individuele afspraken mogelijk worden","page":null},{"id":"bron-18-1","sourceId":"bron-18","title":"Bpv","text":"Op Connect vindt je de BPV opdrachten niet meer. Dit komt doordat verschillende Mbo-scholen samenwerken met elkaar rondom BPV. Daarom is er recent een website gebouwd waarop verschillende zaken rondom BPV te vinden zijn. Dit maakt het makkelijker op alles up to date te houden en zorgt ervoor dat iedereen bij dezelfde documenten kan. (student, werkbegeleider, praktijkopleiders, docenten etc.)","page":null},{"id":"bron-18-2","sourceId":"bron-18","title":"Ga naar www.debpvwijzer.nl, dit is de website waar al deze inform","text":"Ga naar www.debpvwijzer.nl, dit is de website waar al deze informatie gebundeld is.","page":null},{"id":"bron-18-3","sourceId":"bron-18","title":"Bpv","text":"Allereerst maak je een keuze welke opleiding je volgt. Dan opent zich het deel op de website wat voor jou van toepassing is.","page":null},{"id":"bron-18-4","sourceId":"bron-18","title":"Bpv","text":"Je vindt er bijvoorbeeld de handleiding BPV-wijzer, hierin staat het hoe en waarom van de BPV wijzer. Onder BPV tools vindt je een overzicht welke BPV opdrachten bij welk werkprocessen passen, voor zowel starter als gevorderde opdrachten, evenals een feedback formulier die je kunt gebruiken bij een BPV opdracht. De BPV meter is er ook te vinden met een toelichting en ook een hulpmiddel bij het plannen; het stappenplan voor BPV tools.","page":null},{"id":"bron-18-5","sourceId":"bron-18","title":"Bpv","text":"Het onderdeel tijdsregistratie gebruiken we als V&V Landstede niet, i.v.m. de digitale urenregistratie via Eduarte.","page":null},{"id":"bron-18-6","sourceId":"bron-18","title":"Bpv","text":"Onder het kopje BPV opdrachten-starter en BPV opdrachten-gevorderd vindt je alle BPV opdrachten. Per examen zie je de BPV opdrachten die erbij horen. Zodat je op een goede manier een keus kunt maken uit de BPV opdrachten die je wilt uitvoeren (gekoppeld aan je leermeter).","page":null},{"id":"bron-18-7","sourceId":"bron-18","title":"Bpv","text":"Als laatste vindt je onder het kopje reflecteren verschillende reflectie-instrumenten die je kunt gebruiken met de uitleg ervan.","page":null},{"id":"bron-18-8","sourceId":"bron-18","title":"Bpv","text":"Wat heel handig is, is dat je alle documenten (dus ook je BPV meter en je BPV opdrachten) ook kan downloaden als PDF en daarmee kan opslaan voor jezelf om te gebruiken.","page":null},{"id":"bron-19-1","sourceId":"bron-19","title":"Skills","text":"In het skillslab is de beroepspraktijk zo goed mogelijk nagebootst. Hier kun je oefenen op de meeste vaardigheden waar je opleiding uit bestaat. In het Skills oefenen we met technische handelingen maar is het ook mogelijk om te oefenen met het omgaan met een zorgvrager ( bijvoorbeeld met behulp van een simulatie patiënt ).","page":null},{"id":"bron-19-2","sourceId":"bron-19","title":"Skills","text":"Tijdens je opleiding is het de bedoeling dat je verschillende verpleegtechnische handelingen af rond op je stage/ werkplek, mocht dit daar niet lukken dan kun je in het Skills terecht.","page":null},{"id":"bron-19-3","sourceId":"bron-19","title":"Skills","text":"Hier wordt geprobeerd om jou zo goed mogelijk voor te bereiden voor in de praktijk. Zorgvragers worden op deze manier zo min mogelijk geconfronteerd met een ongeoefende leerling verzorgende/verplegende.","page":null},{"id":"bron-19-4","sourceId":"bron-19","title":"Skills","text":"Het Skillslab bestaat uit diverse ruimtes waarin je met je groep onder begeleiding van een verpleegkunde-docent alle verpleegkundige vaardigheden kunt aanleren en oefenen.","page":null},{"id":"bron-19-5","sourceId":"bron-19","title":"Skills","text":"Ook kun je zelfstandig oefenen of onder begeleiding van een instructeur een vaardigheid aanleren. Wanneer je zelfstandig buiten de les om wilt oefenen in het skills word er van je verwacht dat je jezelf inschrijft. Je kunt je inschrijven in de gele ‘’leerlingenmap’’ die op de balie in het skills te vinden is.","page":null},{"id":"bron-19-6","sourceId":"bron-19","title":"Skills","text":"Wanneer je wilt oefenen in het skills dien je de aanvraag voor materialen enz. een week van te voren in de map te zetten, zo hebben de docenten/instructeurs voldoende tijd om alles klaar te zetten zodat jij kan oefenen. Je kunt de aangevraagde materialen vinden in de aanvraagkast rechts in het magazijn.","page":null},{"id":"bron-19-7","sourceId":"bron-19","title":"Spelregels Skills:","text":"Het is verplicht om een wit jasje te dragen zodra je de skills lokalen betreedt.","page":null},{"id":"bron-19-8","sourceId":"bron-19","title":"Spelregels Skills:","text":"Ga zorgvuldig met de materialen om. Enkele materialen kunnen wij hergebruiken, overleg met je docent wat je weg kunt gooien en wat niet.","page":null},{"id":"bron-19-9","sourceId":"bron-19","title":"Spelregels Skills:","text":"Je mag niet op het bed zitten; door een onevenwichtige belasting kan het bed defect raken. Wanneer het noodzakelijk is dat je in bed moet gaan liggen trek je je schoenen uit.","page":null},{"id":"bron-19-10","sourceId":"bron-19","title":"Spelregels Skills:","text":"In het skills mag je niet eten, je mag wel gebruik maken van een flesje water.","page":null},{"id":"bron-19-11","sourceId":"bron-19","title":"Spelregels Skills:","text":"Doe geen natte was in de waszakken maar laat deze drogen op de verwarming.","page":null},{"id":"bron-19-12","sourceId":"bron-19","title":"Spelregels Skills:","text":"Je gebruikte materialen ruim je na afloop op in de zwarte kast op de gang of in het magazijn. Zwachtels en ander verband rol je netjes op.","page":null},{"id":"bron-19-13","sourceId":"bron-19","title":"Spelregels Skills:","text":"Het is niet toegestaan om een foto en/of video te maken tijdens, voor en/of na het oefenen in het skills. Tenzij toestemming is gegeven.","page":null},{"id":"bron-19-14","sourceId":"bron-19","title":"Spelregels Skills:","text":"Aan het einde van je opleiding kun je proeve , die je niet hebt kunnen behalen in de praktijk, op school doen. Lees hiervoor de procedure op intranet.","page":null},{"id":"bron-19-15","sourceId":"bron-19","title":"Spelregels Skills:","text":"Laat de oefenlokalen netjes achter wanneer je klaar bent met oefenen. Bedden staan in de hoogste stand, beddengoed ligt netjes, de poppen liggen in de slaapzak in de hiervoor bestemde kast","page":null},{"id":"bron-20-1","sourceId":"bron-20","title":"Met onderstaande instructie kan je jezelf lid maken van het team ","text":"Met onderstaande instructie kan je jezelf lid maken van het team “Medisch rekenen”.","page":null},{"id":"bron-20-2","sourceId":"bron-20","title":"Je krijgt dan toegang tot een reader en filmpjes met uitleg bij d","text":"Je krijgt dan toegang tot een reader en filmpjes met uitleg bij de moeilijkste oefenvragen.","page":null},{"id":"bron-20-3","sourceId":"bron-20","title":"Lukt dit niet, neem dan even contact op met je docent medisch rek","text":"Lukt dit niet, neem dan even contact op met je docent medisch rekenen, of met Edwin Dekker.","page":null},{"id":"bron-20-4","sourceId":"bron-20","title":"Klik op de optie “Teams”","text":"Klik dan op de knop “Lid worden of team maken”. Deze bevindt zich rechtsboven in beeld als je de standaard indeling “raster” hebt (met tegels).","page":null},{"id":"bron-20-5","sourceId":"bron-20","title":"Klik op de optie “Teams”","text":"Heb je de indeling “Lijst”, dan klik je links onderaan op de knop “Lid worden van een team of een team maken”.","page":null},{"id":"bron-20-6","sourceId":"bron-20","title":"Klik op de optie “Teams”","text":"Je krijgt dan een mogelijkheid om onderstaande code in te vullen onder “Lid worden van een team met code”.","page":null},{"id":"bron-20-7","sourceId":"bron-20","title":"Gebruik dan deze code om lid te worden: uun9num","text":"Naast een reader (met theorie, voorbeeldvragen en oefenopgaven) en formulekaart vind je er filmpjes met uitleg bij de meeste oefenopgaven uit de reader:","page":null}],"info":{"version":"1.1","note":"Beknopte bronpassages uit door de gebruiker aangeleverde documenten. Geen volledige PDF’s; bron en pagina worden getoond. Bronbestanden zijn niet publiek toegevoegd."}};
